/// Global shutdown flag
static SHUTDOWN: AtomicBool = AtomicBool::new(false);

/// Whether the shutdown signal has arrived.
pub(crate) fn shutting_down() -> bool {
    #[cfg(test)]
    if SHUTDOWN_FOR_TEST.with(std::cell::Cell::get) {
        return true;
    }
    SHUTDOWN.load(Ordering::SeqCst)
}

// A shutdown seen only by the calling test's thread. The process-wide flag would
// also refuse the creates and the S5/S8 requests of tests running alongside.
#[cfg(test)]
thread_local! {
    static SHUTDOWN_FOR_TEST: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Set the calling thread's [`shutting_down`] for a test.
#[cfg(test)]
pub(crate) fn set_shutting_down_for_test(on: bool) {
    SHUTDOWN_FOR_TEST.with(|s| s.set(on));
}

/// When the shutdown signal arrived (#941 review M2): the start of the one deadline
/// every shutdown phase is bounded by.
static SHUTDOWN_STARTED: std::sync::OnceLock<std::time::Instant> = std::sync::OnceLock::new();

/// Where the Prometheus endpoint listens (`SMF_METRICS_PORT`, default 9090 — the port
/// `sgwud` uses and the port `configs/observability/prometheus.yml` already scrapes
/// `172.23.0.4` on).
fn metrics_addr() -> SocketAddr {
    let port: u16 = std::env::var("SMF_METRICS_PORT")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(9090);
    // Loopback unless NEXTGCORE_METRICS_BIND says otherwise (#837).
    nextgcore_metrics::nes_energy::metrics_bind_addr(port)
}

/// Render this SMF/PGW-C's runtime state in Prometheus text format (#380).
///
/// The numbers that distinguish a working session anchor from a bound-but-useless one:
/// the N4 association count, whether the S5/S8 (PGW-C) socket is serving, and the
/// session census. All read from live state — `smf_n4_associations` comes from the
/// per-peer `PfcpClient` gauges, not from a counter this function increments.
///
/// `smf_n4_associations` is the PGW-C analogue of `sgwu_pfcp_associations`, and the
/// reason it exists: in a combined SGW/PGW deployment (TS 23.401 §4.2.1 single-gateway
/// option, realised over PFCP per TS 29.244 §5.2.6) the Sxb/N4 association is what turns
/// a bound S5/S8 socket into a node that can actually answer a Create Session Request —
/// TS 29.244 §6.2.6.2 forbids session signalling without one. Container-reported health
/// cannot tell those two apart, which is why this is a metric rather than a `kill -0 1`.
fn render_metrics() -> String {
    // #1368: the families every NF serves (SBI, NRF client, process), the PDU
    // session establishment counters, then the SMF's own gauges below.
    let mut out = nextgcore_metrics::nf::render_common(&nextgcore_metrics::nf::NfIdentity {
        nf: "smf",
        version: env!("CARGO_PKG_VERSION"),
        nrf_client: true,
    });
    session_metrics::render(&mut out);
    reconcile::render(&mut out);
    out.push_str(&render_smf_families());
    n6_delay::render(&mut out);
    out
}

/// The SMF's own gauges and counters (#380 and later).
fn render_smf_families() -> String {
    let pool = pfcp_path::global_pool();
    let associations = pool.iter().filter(|c| c.is_associated_sync()).count();
    let sessions = smf_self().read().map(|ctx| ctx.sess_count()).unwrap_or(0);
    // Whether the PGW-C role is bound at all. `smf.gtpc.server` unset leaves it unbound
    // (see `s5s8_open`), and a deployment that means to anchor LTE sessions needs to be
    // able to see the difference rather than infer it from the absence of traffic.
    let s5s8 = u8::from(gtp_path::s5s8_server().is_some());
    format!(
        "# HELP smf_n4_associations Number of associated UPF/PGW-U peers on N4 (Sxb in a combined SGW/PGW)\n\
         # TYPE smf_n4_associations gauge\n\
         smf_n4_associations {associations}\n\
         # HELP smf_n4_peers Number of configured N4 peers\n\
         # TYPE smf_n4_peers gauge\n\
         smf_n4_peers {}\n\
         # HELP smf_sessions Number of sessions held by this SMF/PGW-C\n\
         # TYPE smf_sessions gauge\n\
         smf_sessions {sessions}\n\
         # HELP smf_s5s8_bound 1 when the S5/S8 (PGW-C) GTP-C socket is serving\n\
         # TYPE smf_s5s8_bound gauge\n\
         smf_s5s8_bound {s5s8}\n\
         # HELP smf_up 1 when the SMF runtime is serving\n\
         # TYPE smf_up gauge\n\
         smf_up 1\n\
         # HELP smf_pfcp_unauthorized_messages_total PFCP messages refused or dropped because their sender is no UPF of this SMF, or reported on another UPF's session\n\
         # TYPE smf_pfcp_unauthorized_messages_total counter\n\
         smf_pfcp_unauthorized_messages_total {}\n\
         # HELP smf_sm_policy_delete_failures_total SM Policy Association terminations (Npcf_SMPolicyControl_Delete) that failed after every attempt; each is parked for the release-cleanup reconciler (smf_release_cleanups_*)\n\
         # TYPE smf_sm_policy_delete_failures_total counter\n\
         smf_sm_policy_delete_failures_total {}\n\
         # HELP smf_up_path_failures_total Remote GTP-U peers a UPF reported a user plane path failure toward (PFCP Node Report, TS 29.244 §5.10A)\n\
         # TYPE smf_up_path_failures_total counter\n\
         smf_up_path_failures_total {}\n\
         # HELP smf_up_path_recoveries_total Remote GTP-U peers a UPF reported recovered\n\
         # TYPE smf_up_path_recoveries_total counter\n\
         smf_up_path_recoveries_total {}\n\
         # HELP smf_up_paths_failed Remote GTP-U peers failed now, over all UPFs\n\
         # TYPE smf_up_paths_failed gauge\n\
         smf_up_paths_failed {}\n\
         # HELP smf_up_path_sessions_deactivated_total Sessions whose user plane was deactivated toward a failed or restarted GTP-U peer, or after an Error Indication\n\
         # TYPE smf_up_path_sessions_deactivated_total counter\n\
         smf_up_path_sessions_deactivated_total {}\n\
         # HELP smf_up_path_sessions_released_total Sessions released because their path was still down after SMF_UP_PATH_FAILURE_HOLD_SECS\n\
         # TYPE smf_up_path_sessions_released_total counter\n\
         smf_up_path_sessions_released_total {}\n\
         # HELP smf_nsac_decrease_failures_total NSACF DECREASEs (Nnsacf_NSAC_NumOfPDUsUpdate) that failed or timed out, the reconciler's retries included; each failed one is parked for the release-cleanup reconciler (smf_release_cleanups_*)\n\
         # TYPE smf_nsac_decrease_failures_total counter\n\
         smf_nsac_decrease_failures_total {}\n\
         # HELP smf_ipv4_pool_stale_releases_total UE IPv4 addresses released while already free: each is a double free\n\
         # TYPE smf_ipv4_pool_stale_releases_total counter\n\
         smf_ipv4_pool_stale_releases_total {}\n\
         # HELP smf_s5s8_sgw_restart_pdn_deleted_total PDN connections deleted because their SGW-C restarted (TS 23.007 §17.1A.1)\n\
         # TYPE smf_s5s8_sgw_restart_pdn_deleted_total counter\n\
         smf_s5s8_sgw_restart_pdn_deleted_total {}\n\
         # HELP smf_s5s8_sgw_restart_deletions_running Restarted SGW-Cs whose PDN connections are still being deleted\n\
         # TYPE smf_s5s8_sgw_restart_deletions_running gauge\n\
         smf_s5s8_sgw_restart_deletions_running {}\n",
        pool.len(),
        pfcp_path::PFCP_UNAUTHORIZED.load(Ordering::Relaxed),
        SM_POLICY_DELETE_FAILURES.load(Ordering::Relaxed),
        up_path::UP_PATH_FAILURES.load(Ordering::Relaxed),
        up_path::UP_PATH_RECOVERIES.load(Ordering::Relaxed),
        up_path::failed_path_count(),
        up_path::UP_PATH_SESSIONS_DEACTIVATED.load(Ordering::Relaxed),
        up_path::UP_PATH_SESSIONS_RELEASED.load(Ordering::Relaxed),
        policy::NSAC_DECREASE_FAILURES.load(Ordering::Relaxed),
        smf_self()
            .read()
            .map(|ctx| ctx.ipv4_pool.stale_releases())
            .unwrap_or(0),
        gtp_handler::SGW_RESTART_PDN_CONNECTIONS_DELETED.load(Ordering::Relaxed),
        gtp_handler::SGW_RESTART_DELETIONS_RUNNING.load(Ordering::Relaxed),
    )
}

/// Monotonically-increasing PFCP sequence number counter.
/// Each transaction fetches-and-increments this so concurrent PDU sessions
/// never reuse the same sequence number.
static PFCP_SEQ: AtomicU32 = AtomicU32::new(1);

/// Externally-reachable base URI of this SMF's SBI server, used for the
/// callback URIs handed to the PCF (notificationUri). Set once in `main`.
static SELF_SBI_URI: std::sync::OnceLock<String> = std::sync::OnceLock::new();

// ---------------------------------------------------------------------------
// OAuth2 rollout (Wave-6 H8): opt-in producer verification + outbound consumer
// token install. Default OFF so the matched-sim E2E path is byte-unchanged;
// the docker `smf-oauth2.yaml` overlay (or NEXTGCORE_SBI_OAUTH2_REQUIRE=1) sets
// `smf.sbi.oauth2.require: true`. TS 33.501 §13.4.1, TS 29.510 §5.4.2.
// ---------------------------------------------------------------------------

/// Process-wide OAuth2 client for automatic Bearer-token acquisition on
/// outbound SBI calls (installed only when OAuth2 enforcement is enabled).
static OAUTH2_CLIENT: std::sync::OnceLock<Option<Arc<nextgcore_sbi::oauth::OAuth2Client>>> =
    std::sync::OnceLock::new();

/// The shared OAuth2 client, if SBI OAuth2 enforcement is enabled (Wave-6 H8
/// Phase A). Outbound SBI clients attach a token via [`attach_oauth2`].
fn oauth2_client() -> Option<Arc<nextgcore_sbi::oauth::OAuth2Client>> {
    #[cfg(test)]
    if let Ok(oauth2) = TEST_OAUTH2_CLIENT.try_with(Arc::clone) {
        return Some(oauth2);
    }
    OAUTH2_CLIENT.get().and_then(|opt| opt.clone())
}

