    /// #1509, TS 29.244 §5.8.3 / §8.2.1 cause 72: a heartbeat loss marks the UPF down
    /// and keeps its sessions; a Session Report from it for one of them is refused with
    /// "No established PFCP Association", the UPF's SEID (#1559, §7.2.2.4.1: the
    /// session is known, so 0 is not allowed), and nothing in it is processed (its
    /// TSC Management Information is not recorded). Once the UPF is associated again,
    /// the same report is accepted and recorded.
    ///
    /// REVERT-VERIFIED: without the association check in
    /// `handle_pfcp_session_report_from`, the report while down is accepted (cause 1)
    /// and its TSC report recorded.
    #[tokio::test]
    async fn a_session_report_from_a_upf_marked_down_is_refused_1509() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        pfcp_path::clear_tsc_reports_for_test();
        smf_context_init(64, 256, 512);
        let (client, upf) = pfcp_path::stand_in::client_with_silent_peer_timed(
            std::time::Duration::from_millis(50),
            1,
        )
        .await;
        client.set_assoc_state_for_test(true, None, None).await;
        pfcp_path::set_global_pool(vec![client.clone()]);
        let upf_addr = upf.local_addr().unwrap();
        let smf_sock = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let reference = "15090001";
        smf_self()
            .read()
            .unwrap()
            .pfcp_sessions
            .write()
            .unwrap()
            .insert(reference.to_string(), 0x1509);
        let seid = crate::context::derive_cp_n4_seid(reference);
        // Report Type TMIR plus one TSC Management Information IE (201).
        let report = |seq: u32| {
            let mut tsc = bytes::BytesMut::new();
            nextgcore_pfcp::types::TscManagementInformation::port(vec![0x15, 0x09], 7)
                .encode(&mut tsc);
            let mut body = vec![0, 39, 0, 1, 0x10, 0, 201];
            body.extend_from_slice(&(tsc.len() as u16).to_be_bytes());
            body.extend_from_slice(&tsc);
            pfcp_path::encode_wire_message(
                pfcp_path::pfcp_message_type::SESSION_REPORT_REQUEST,
                Some(seid),
                seq,
                &body,
            )
        };
        // The next Session Report Response the UPF receives, past its Heartbeat
        // Requests.
        let response = || async {
            let mut buf = vec![0u8; 2048];
            loop {
                let (n, _) = tokio::time::timeout(
                    std::time::Duration::from_secs(2),
                    upf.recv_from(&mut buf),
                )
                .await
                .expect("a Session Report Response")
                .unwrap();
                let h = pfcp_path::parse_wire_header(&buf[..n]).unwrap();
                if h.msg_type == pfcp_path::pfcp_message_type::SESSION_REPORT_RESPONSE {
                    return (h, buf[..n].to_vec());
                }
            }
        };

        // Heartbeat loss: the silent peer exhausts T1 x (N1 + 1) and the UPF is down.
        let heartbeat = client.heartbeat_once().await;
        let down = !client.is_associated().await;
        let retained = pfcp_path::holds_session_seid(seid);
        handle_pfcp_session_report_from(&smf_sock, &report(0x1509), upf_addr, Some(&client)).await;
        let (h_down, while_down) = response().await;
        let recorded_while_down = pfcp_path::tsc_reports_for(seid);

        // Associated again: the same report is the UPF's to make.
        client.set_assoc_state_for_test(true, None, None).await;
        handle_pfcp_session_report_from(&smf_sock, &report(0x150a), upf_addr, Some(&client)).await;
        let (h_up, after) = response().await;
        let recorded_after = pfcp_path::tsc_reports_for(seid);

        smf_self()
            .read()
            .unwrap()
            .pfcp_sessions
            .write()
            .unwrap()
            .remove(reference);
        pfcp_path::clear_global_upf_for_test();
        pfcp_path::clear_tsc_reports_for_test();

        assert!(heartbeat.is_err(), "the silent peer exhausts the heartbeat");
        assert!(down, "the heartbeat loss marks the UPF down");
        assert!(retained, "and the SMF keeps the UPF's session");
        assert_eq!(
            pfcp_cause_of(&while_down),
            Some(72),
            "No established PFCP Association"
        );
        assert_eq!(h_down.sequence_number, 0x1509);
        assert!(h_down.seid_present);
        assert_eq!(
            h_down.seid, 0x1509,
            "#1559: the refusal carries the UPF's SEID for the known session, not 0"
        );
        assert!(
            recorded_while_down.is_none(),
            "nothing in the refused report is processed: {recorded_while_down:?}"
        );
        assert_eq!(pfcp_cause_of(&after), Some(1), "accepted once associated");
        assert_eq!(h_up.sequence_number, 0x150a);
        assert_eq!(
            h_up.seid, 0x1509,
            "#1559: the UPF's SEID, not the SMF's {seid:#x}"
        );
        let recorded = recorded_after.expect("the accepted report is processed");
        assert_eq!(recorded.len(), 1);
        assert_eq!(recorded[0].nw_tt_port_number, Some(7));
        assert_eq!(
            recorded[0].port_management_container.as_deref(),
            Some(&[0x15, 0x09][..])
        );
    }

    /// #1559, TS 29.244 §7.2.2.4.1 (`29244-k00.txt:14142-14149`): the SEID in a PFCP
    /// header is the one "provided by the corresponding receiving entity". A Session
    /// Report Response goes to the UPF, so it carries the UP F-SEID's SEID the UPF
    /// gave at establishment, not the SMF's own SEID the request was addressed to.
    /// Both answers to a known session's report: accepted (cause 1) and missing its
    /// Report Type (cause 66, §7.2.2.4.2: the node "should look up the remote peer's
    /// SEID"). The session's SMF SEID is an inherited one (#475, `cp_n4_seids`), so
    /// the lookup follows the same resolution as the ownership check.
    ///
    /// REVERT-VERIFIED: with `Some(seid)` back in both encoders, both headers carry
    /// the SMF's SEID 0x1559_0001.
    #[tokio::test]
    async fn a_session_report_response_carries_the_upfs_seid_1559() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let (client, upf) = pfcp_path::stand_in::client_with_silent_peer_timed(
            std::time::Duration::from_millis(50),
            1,
        )
        .await;
        client.set_assoc_state_for_test(true, None, None).await;
        pfcp_path::set_global_pool(vec![client.clone()]);
        let upf_addr = upf.local_addr().unwrap();
        let smf_sock = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let reference = "15590001";
        let (smf_seid, upf_seid) = (0x1559_0001u64, 0x00AB_1559u64);
        {
            let global = smf_self();
            let ctx = global.read().unwrap();
            ctx.cp_n4_seids
                .write()
                .unwrap()
                .insert(reference.to_string(), smf_seid);
            ctx.pfcp_sessions
                .write()
                .unwrap()
                .insert(reference.to_string(), upf_seid);
        }
        let report = |seq: u32, body: &[u8]| {
            pfcp_path::encode_wire_message(
                pfcp_path::pfcp_message_type::SESSION_REPORT_REQUEST,
                Some(smf_seid),
                seq,
                body,
            )
        };
        let response = || async {
            let mut buf = vec![0u8; 2048];
            loop {
                let (n, _) = tokio::time::timeout(
                    std::time::Duration::from_secs(2),
                    upf.recv_from(&mut buf),
                )
                .await
                .expect("a Session Report Response")
                .unwrap();
                let h = pfcp_path::parse_wire_header(&buf[..n]).unwrap();
                if h.msg_type == pfcp_path::pfcp_message_type::SESSION_REPORT_RESPONSE {
                    return (h, buf[..n].to_vec());
                }
            }
        };

        // A Report Type with no report bit set: accepted, and nothing to act on.
        handle_pfcp_session_report_from(
            &smf_sock,
            &report(0x1559, &[0, 39, 0, 1, 0x00]),
            upf_addr,
            Some(&client),
        )
        .await;
        let (h_accepted, accepted) = response().await;
        // No Report Type at all.
        handle_pfcp_session_report_from(&smf_sock, &report(0x155a, &[]), upf_addr, Some(&client))
            .await;
        let (h_missing, missing) = response().await;

        {
            let global = smf_self();
            let ctx = global.read().unwrap();
            ctx.pfcp_sessions.write().unwrap().remove(reference);
            ctx.cp_n4_seids.write().unwrap().remove(reference);
        }
        pfcp_path::clear_global_upf_for_test();

        assert_eq!(pfcp_cause_of(&accepted), Some(1));
        assert_eq!(h_accepted.sequence_number, 0x1559);
        assert!(h_accepted.seid_present);
        assert_eq!(
            h_accepted.seid, upf_seid,
            "the accepted answer carries the UPF's SEID, not the SMF's {smf_seid:#x}"
        );
        assert_eq!(pfcp_cause_of(&missing), Some(66), "Mandatory IE missing");
        assert_eq!(h_missing.sequence_number, 0x155a);
        assert_eq!(
            h_missing.seid, upf_seid,
            "the cause-66 answer carries the UPF's SEID too"
        );
    }

    /// #971: a UPF reports only on its own sessions. A report for a session recorded
    /// on another UPF is refused with cause 65.
    #[tokio::test]
    async fn a_upf_cannot_report_on_another_upfs_session() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let upf_a = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        // Another node: UPFs are told apart by IP address.
        let upf_b = tokio::net::UdpSocket::bind("127.0.0.3:0").await.unwrap();
        let sock = std::sync::Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let smf = sock.local_addr().unwrap();
        let a = std::sync::Arc::new(pfcp_path::PfcpClient::new(
            sock.clone(),
            upf_a.local_addr().unwrap(),
            [127, 0, 0, 1],
        ));
        let b = std::sync::Arc::new(pfcp_path::PfcpClient::new(
            sock.clone(),
            upf_b.local_addr().unwrap(),
            [127, 0, 0, 1],
        ));
        pfcp_path::set_global_pool(vec![a.clone(), b.clone()]);
        let listener = spawn_pfcp_listener(sock, vec![a.clone(), b.clone()]);
        pfcp_path::record_session_peer(0x0973, a.peer());

        upf_b
            .send_to(&session_report(0x0973, 0x973), smf)
            .await
            .unwrap();
        let refused = recv_pfcp(&upf_b).await;
        pfcp_path::forget_session_peer(0x0973);
        listener.abort();
        pfcp_path::clear_global_upf_for_test();

        assert_eq!(pfcp_cause_of(&refused.expect("a response")), Some(65));
    }

    use std::time::Duration;

    /// The fixture of the #721/#928 receive-task tests: an AMF taking `amf_delay` per
    /// request, UPF A (a raw socket the test drives) and UPF B (answers deletions),
    /// both on one N4 socket behind the real listener, and one session on A whose
    /// release goes to that AMF.
    struct RestartFixture {
        posts: Arc<std::sync::atomic::AtomicUsize>,
        amf: nextgcore_sbi::server::SbiServer,
        upf_a: tokio::net::UdpSocket,
        smf_addr: std::net::SocketAddr,
        a: Arc<pfcp_path::PfcpClient>,
        b: Arc<pfcp_path::PfcpClient>,
        task_b: tokio::task::JoinHandle<()>,
        listener: tokio::task::JoinHandle<()>,
        reference: &'static str,
    }

    async fn restart_fixture(reference: &'static str, amf_delay: Duration) -> RestartFixture {
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let posts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let sink = posts.clone();
        let (amf, amf_addr) =
            nextgcore_sbi::test_support::sbi_server_on_free_port(move |_req: SbiRequest| {
                let sink = sink.clone();
                async move {
                    tokio::time::sleep(amf_delay).await;
                    sink.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    SbiResponse::with_status(204)
                }
            })
            .await;
        let upf_a = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let (upf_b, _seen_b, task_b) = raw_upf(None).await;
        let sock = Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let smf_addr = sock.local_addr().unwrap();
        let a = Arc::new(pfcp_path::PfcpClient::new(
            sock.clone(),
            upf_a.local_addr().unwrap(),
            [127, 0, 0, 1],
        ));
        let b = Arc::new(pfcp_path::PfcpClient::new(
            sock.clone(),
            upf_b,
            [127, 0, 0, 1],
        ));
        for c in [&a, &b] {
            c.set_assoc_state_for_test(true, None, None).await;
        }
        a.seed_peer_recovery_time_stamp(100).await;
        pfcp_path::set_global_pool(vec![a.clone(), b.clone()]);
        let listener = spawn_pfcp_listener(sock, vec![a.clone(), b.clone()]);
        seed_binding(reference, 5);
        set_status_uri(
            reference,
            &format!(
                "http://127.0.0.1:{}/namf-callback/v1/sm-status",
                amf_addr.port()
            ),
        );
        if let Ok(ctx) = smf_self().read() {
            ctx.pfcp_sessions
                .write()
                .unwrap()
                .insert(reference.to_string(), 0x928);
        }
        pfcp_path::record_session_peer(context::derive_cp_n4_seid(reference), a.peer());
        RestartFixture {
            posts,
            amf,
            upf_a,
            smf_addr,
            a,
            b,
            task_b,
            listener,
            reference,
        }
    }

    impl RestartFixture {
        fn released(&self) -> usize {
            self.posts.load(std::sync::atomic::Ordering::SeqCst)
        }
        fn session_kept(&self) -> bool {
            smf_self()
                .read()
                .unwrap()
                .pfcp_sessions
                .read()
                .unwrap()
                .contains_key(self.reference)
        }
        async fn wait_released(&self, n: usize) {
            let deadline = std::time::Instant::now() + Duration::from_secs(5);
            while self.released() < n && std::time::Instant::now() < deadline {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        }
        async fn teardown(self) {
            cancel_gsm_timer(self.reference, timer::SmfTimerId::T3592);
            if let Ok(ctx) = smf_self().read() {
                ctx.policy_bindings.write().unwrap().remove(self.reference);
                ctx.pfcp_sessions.write().unwrap().remove(self.reference);
            }
            pfcp_path::forget_session_peer(context::derive_cp_n4_seid(self.reference));
            self.listener.abort();
            self.task_b.abort();
            self.amf.stop().await.ok();
            pfcp_path::clear_global_upf_for_test();
        }
    }

    fn pfcp_body_rts(rts: u32) -> Vec<u8> {
        let mut b = 96u16.to_be_bytes().to_vec();
        b.extend_from_slice(&4u16.to_be_bytes());
        b.extend_from_slice(&rts.to_be_bytes());
        b
    }

    /// #928 review M2: a UPF's Association Release Request is answered at once, the
    /// receive task keeps serving UPF B while A's releases run (the AMF takes 2 s per
    /// request), and A's session is then released.
    #[tokio::test]
    async fn an_association_release_from_a_upf_does_not_stall_the_n4_receive_task() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92801", Duration::from_secs(2)).await;
        let mut body = 60u16.to_be_bytes().to_vec();
        body.extend_from_slice(&5u16.to_be_bytes());
        body.extend_from_slice(&[0, 127, 0, 0, 7]);
        let rel = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::ASSOCIATION_RELEASE_REQUEST,
            None,
            0x928,
            &body,
        );
        let started = std::time::Instant::now();
        fx.upf_a.send_to(&rel, fx.smf_addr).await.unwrap();
        let mut buf = vec![0u8; 512];
        let (len, _) = tokio::time::timeout(Duration::from_secs(5), fx.upf_a.recv_from(&mut buf))
            .await
            .expect("an Association Release Response")
            .unwrap();
        let answered_in = started.elapsed();
        let h = pfcp_path::parse_wire_header(&buf[..len]).unwrap();
        let b_started = std::time::Instant::now();
        let b_result =
            fx.b.request(
                pfcp_path::pfcp_message_type::SESSION_DELETION_REQUEST,
                Some(0x928b),
                &[],
            )
            .await;
        let b_in = b_started.elapsed();
        let in_flight = fx.released();
        fx.wait_released(1).await;
        let released = fx.released();
        fx.teardown().await;

        assert_eq!(
            h.msg_type,
            pfcp_path::pfcp_message_type::ASSOCIATION_RELEASE_RESPONSE
        );
        assert!(answered_in < Duration::from_millis(500), "{answered_in:?}");
        assert!(
            b_result.is_ok() && b_in < Duration::from_millis(500),
            "{b_in:?}"
        );
        assert_eq!(in_flight, 0, "A's release was still in flight");
        assert_eq!(released, 1, "and A's session is released afterwards");
    }

    /// #928 review M1: a restart detected on the SMF's own heartbeat (the path a
    /// restarted nextgcore UPF takes: it has no association, so it sends no Heartbeat
    /// Request) returns at once, so the one association/heartbeat task goes on to the
    /// next pool member.
    #[tokio::test]
    async fn a_restart_seen_on_our_heartbeat_does_not_hold_the_association_task() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92802", Duration::from_secs(2)).await;
        let a = fx.a.clone();
        let hb = tokio::spawn(async move { a.heartbeat_once().await });
        let mut buf = vec![0u8; 512];
        let (len, from) = fx.upf_a.recv_from(&mut buf).await.unwrap();
        let h = pfcp_path::parse_wire_header(&buf[..len]).unwrap();
        let started = std::time::Instant::now();
        let resp = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::HEARTBEAT_RESPONSE,
            None,
            h.sequence_number,
            &pfcp_body_rts(200),
        );
        fx.upf_a.send_to(&resp, from).await.unwrap();
        let result = hb.await.unwrap();
        let took = started.elapsed();
        let in_flight = fx.released();
        let kept = fx.session_kept();
        fx.wait_released(1).await;
        let released = fx.released();
        fx.teardown().await;

        assert!(result.is_ok());
        assert!(
            took < Duration::from_millis(500),
            "heartbeat_once returned at once: {took:?}"
        );
        assert!(!kept, "the restarted UPF's session is flushed at once");
        assert_eq!(in_flight, 0);
        assert_eq!(released, 1);
    }

    /// #928 review M3 (TS 23.007 §19A): a Heartbeat Request from an address that is
    /// not the UPF, carrying a different stamp, is answered and tears nothing down.
    /// Since #971 the listener's gate answers it; the client's own check is the
    /// second layer behind that.
    #[tokio::test]
    async fn a_heartbeat_from_a_stranger_cannot_release_a_upfs_sessions() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92803", Duration::ZERO).await;
        let stranger = tokio::net::UdpSocket::bind("127.0.0.2:0").await.unwrap();
        let hb = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::HEARTBEAT_REQUEST,
            None,
            0x9283,
            &pfcp_body_rts(9999),
        );
        stranger.send_to(&hb, fx.smf_addr).await.unwrap();
        let mut buf = vec![0u8; 512];
        let answered = tokio::time::timeout(Duration::from_secs(2), stranger.recv_from(&mut buf))
            .await
            .is_ok();
        tokio::time::sleep(Duration::from_millis(200)).await;
        let kept = fx.session_kept();
        let associated = fx.a.is_associated().await;
        fx.teardown().await;

        assert!(
            answered,
            "§19A: a Heartbeat Request from anyone is answered"
        );
        assert!(kept && associated, "and tears nothing down");
    }

    /// A Heartbeat Request from UPF A's own address carrying `rts`.
    async fn heartbeat_request_from_a(fx: &RestartFixture, rts: u32, seq: u32) {
        let hb = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::HEARTBEAT_REQUEST,
            None,
            seq,
            &pfcp_body_rts(rts),
        );
        fx.upf_a.send_to(&hb, fx.smf_addr).await.unwrap();
        let mut buf = vec![0u8; 512];
        let _ = tokio::time::timeout(Duration::from_secs(2), fx.upf_a.recv_from(&mut buf)).await;
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    /// #928 m3 / round 2 B1 (TS 23.007 §19A): an OLDER stamp in an unsolicited
    /// Heartbeat Request is a reordered message, discarded.
    #[tokio::test]
    async fn an_older_stamp_in_a_heartbeat_request_is_discarded() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92804", Duration::ZERO).await;
        // Real start times (#1004 follow-up): a stored stamp in the future is not a
        // reference for ordering, so the fixture's synthetic 100 (an era-1, 2036
        // value) cannot stand in for "the current incarnation" here.
        let now_unix = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        fx.a.seed_peer_recovery_time_stamp(nextgcore_pfcp::recovery_time::from_unix_secs(
            now_unix - 60,
        ))
        .await;
        let older = nextgcore_pfcp::recovery_time::from_unix_secs(now_unix - 86_400);
        heartbeat_request_from_a(&fx, older, 0x9284).await;
        let kept = fx.session_kept();
        fx.teardown().await;
        assert!(
            kept,
            "an older stamp in a Heartbeat Request is not a restart"
        );
    }

    /// #928 round 2 B1: in the RESPONSE to our own heartbeat any changed stamp is a
    /// restart, even a smaller one (a UPF back with its clock behind): the UPF
    /// answering is a different incarnation. Before, it stayed "associated" for good.
    #[tokio::test]
    async fn a_smaller_stamp_in_the_answer_to_our_heartbeat_is_a_restart() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92805", Duration::ZERO).await;
        let a = fx.a.clone();
        let hb = tokio::spawn(async move { a.heartbeat_once().await });
        let mut buf = vec![0u8; 512];
        let (len, from) = fx.upf_a.recv_from(&mut buf).await.unwrap();
        let h = pfcp_path::parse_wire_header(&buf[..len]).unwrap();
        let resp = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::HEARTBEAT_RESPONSE,
            None,
            h.sequence_number,
            &pfcp_body_rts(50),
        );
        fx.upf_a.send_to(&resp, from).await.unwrap();
        let _ = hb.await.unwrap();
        let kept = fx.session_kept();
        fx.teardown().await;
        assert!(
            !kept,
            "the smaller stamp in our own heartbeat's answer is a restart"
        );
    }

    /// #928 round 2 B1: past the 2036 wrap of the 32-bit NTP seconds, a stamp just
    /// after the wrap is NEWER than one just before it (RFC 1982 serial arithmetic).
    #[tokio::test]
    async fn a_stamp_past_the_2036_wrap_is_a_restart() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92806", Duration::ZERO).await;
        fx.a.seed_peer_recovery_time_stamp(0xFFFF_FF00).await;
        heartbeat_request_from_a(&fx, 0x10, 0x9286).await;
        let kept = fx.session_kept();
        fx.teardown().await;
        assert!(!kept, "0x10 after 0xFFFFFF00 is a newer incarnation");
    }

    /// #928 round 2 B2: the stamp's compare-and-set under one write guard. Two
    /// detectors of one new stamp tear down once.
    ///
    /// #1229: since #966 (review m3) the teardown clears the stored stamp with the
    /// association, after an await. So the second detector of a stamp finds one of two
    /// things, and neither may tear down again:
    /// - the new stamp, when it runs inside the first detector's teardown, before the
    ///   clear. This is driven deterministically by holding the teardown there
    ///   (`TEARDOWN_HOLD_FOR_TEST`);
    /// - no stamp, when it runs after the clear. It stores the stamp as a baseline.
    ///
    /// The test then races two detectors in 20 rounds, as before. Each round now
    /// starts from what a re-association and its first Heartbeat leave: associated,
    /// with the old incarnation's stamp (100) stored. When the rounds chained (round
    /// i's stamp was round i + 1's baseline), a round tore down only if the round
    /// before had cleared after its second detector ran. That made the count `19 != 20`
    /// in CI, depending on how the previous round's two detectors were ordered.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn concurrent_detectors_of_one_new_stamp_tear_down_once() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92807", Duration::ZERO).await;
        let teardowns = || pfcp_path::TEARDOWNS_FOR_TEST.load(Ordering::SeqCst);
        let rebaseline = || async {
            fx.a.set_assoc_state_for_test(true, None, None).await;
            fx.a.seed_peer_recovery_time_stamp(100).await;
        };

        // Inside the teardown, before the clear: the stored stamp is the new one.
        rebaseline().await;
        // #1239 review: released on every exit path, a failed assertion included.
        let hold = pfcp_path::TeardownHold::arm();
        let before = teardowns();
        let first = {
            let a = fx.a.clone();
            tokio::spawn(async move { a.check_peer_restart(900).await })
        };
        let reached = tokio::time::timeout(Duration::from_secs(5), hold.reached.notified())
            .await
            .is_ok();
        hold.disarm();
        assert!(reached, "the first detector reaches its teardown");
        fx.a.check_peer_restart(900).await;
        let inside = teardowns() - before;
        hold.release();
        first.await.unwrap();
        drop(hold);
        assert_eq!(
            inside, 1,
            "the second detector, inside the teardown, does not tear down"
        );
        assert_eq!(teardowns() - before, 1);

        // After the clear: no stamp stored; the second detector records a baseline.
        rebaseline().await;
        let before = teardowns();
        fx.a.check_peer_restart(901).await;
        assert_eq!(
            fx.a.peer_recovery_time_stamp_for_test().await,
            None,
            "cleared"
        );
        fx.a.check_peer_restart(901).await;
        assert_eq!(teardowns() - before, 1, "after the clear, a baseline");

        // Raced, round by round.
        let rounds = 20u32;
        let mut per_round = Vec::new();
        for i in 0..rounds {
            rebaseline().await;
            let before = teardowns();
            let stamp = 1000 + i;
            let barrier = Arc::new(tokio::sync::Barrier::new(2));
            let mut tasks = Vec::new();
            for _ in 0..2 {
                let a = fx.a.clone();
                let b = barrier.clone();
                tasks.push(tokio::spawn(async move {
                    b.wait().await;
                    a.check_peer_restart(stamp).await;
                }));
            }
            for t in tasks {
                t.await.unwrap();
            }
            per_round.push(teardowns() - before);
            let left = fx.a.peer_recovery_time_stamp_for_test().await;
            assert!(
                left.is_none() || left == Some(stamp),
                "round {i}: the teardown's clear, or the new stamp as a baseline: {left:?}"
            );
        }
        fx.teardown().await;
        assert_eq!(
            per_round,
            vec![1; rounds as usize],
            "one teardown per new stamp, in every round"
        );
    }

    /// #928 round 2 M2: an Association Release Request from a host that is not the
    /// association's UPF is refused with cause 72 and tears nothing down.
    #[tokio::test]
    async fn a_strangers_association_release_is_refused() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let fx = restart_fixture("92808", Duration::ZERO).await;
        // Another IP: the same host on another port is the same PFCP node.
        let stranger = tokio::net::UdpSocket::bind("127.0.0.2:0").await.unwrap();
        let mut body = 60u16.to_be_bytes().to_vec();
        body.extend_from_slice(&5u16.to_be_bytes());
        body.extend_from_slice(&[0, 127, 0, 0, 2]);
        let rel = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::ASSOCIATION_RELEASE_REQUEST,
            None,
            0x9288,
            &body,
        );
        stranger.send_to(&rel, fx.smf_addr).await.unwrap();
        let mut buf = vec![0u8; 512];
        let answer = tokio::time::timeout(Duration::from_secs(2), stranger.recv_from(&mut buf))
            .await
            .ok()
            .and_then(Result::ok)
            .map(|(n, _)| buf[..n].to_vec());
        tokio::time::sleep(Duration::from_millis(100)).await;
        let kept = fx.session_kept();
        let associated = fx.a.is_associated().await;
        fx.teardown().await;
        let answer = answer.expect("an Association Release Response");
        let h = pfcp_path::parse_wire_header(&answer).unwrap();
        assert_eq!(
            pfcp_path::find_ie(&answer[h.body_offset..], 19).and_then(|v| v.first().copied()),
            Some(72),
            "No established PFCP Association"
        );
        assert!(kept && associated, "nothing torn down");
    }

    /// #928 round 2 M3: the shutdown drain of tracked fan-outs is bounded, and waits
    /// for them when there is time.
    #[tokio::test]
    async fn the_restart_fanout_drain_is_bounded() {
        // #928 review m4: the tracked fan-outs are a process-global.
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let slow = tokio::spawn(async {
            tokio::time::sleep(Duration::from_millis(600)).await;
        });
        pfcp_path::track_restart_fanout_for_test(slow);
        let started = std::time::Instant::now();
        pfcp_path::drain_restart_fanouts(Duration::from_millis(100)).await;
        let short = started.elapsed();
        let slow = tokio::spawn(async {
            tokio::time::sleep(Duration::from_millis(300)).await;
        });
        pfcp_path::track_restart_fanout_for_test(slow);
        let started = std::time::Instant::now();
        pfcp_path::drain_restart_fanouts(Duration::from_secs(5)).await;
        let long = started.elapsed();
        assert!(short < Duration::from_millis(400), "{short:?}");
        assert!(long >= Duration::from_millis(250), "it waited: {long:?}");
    }

    /// #721: a UPF restart seen on a Heartbeat Request is answered at once, and the
    /// N4 receive task stays live while the per-session releases run. The AMF takes
    /// 2 s per N1N2MessageTransfer. Before, the receive task ran the whole release
    /// fan-out before it sent the Heartbeat Response, so no PFCP message from ANY
    /// UPF was processed meanwhile, and the restarted UPF could declare the SMF dead.
    #[tokio::test]
    async fn a_restart_on_a_heartbeat_does_not_stall_the_n4_receive_task() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let posts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let sink = posts.clone();
        let (amf, amf_addr) =
            nextgcore_sbi::test_support::sbi_server_on_free_port(move |_req: SbiRequest| {
                let sink = sink.clone();
                async move {
                    tokio::time::sleep(std::time::Duration::from_secs(2)).await;
                    sink.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    SbiResponse::with_status(204)
                }
            })
            .await;
        // UPF A restarts; UPF B is healthy and answers a deletion.
        let upf_a = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let (upf_b, _seen_b, task_b) = raw_upf(None).await;
        let sock = Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let smf_addr = sock.local_addr().unwrap();
        let a = Arc::new(pfcp_path::PfcpClient::new(
            sock.clone(),
            upf_a.local_addr().unwrap(),
            [127, 0, 0, 1],
        ));
        let b = Arc::new(pfcp_path::PfcpClient::new(
            sock.clone(),
            upf_b,
            [127, 0, 0, 1],
        ));
        for c in [&a, &b] {
            c.set_assoc_state_for_test(true, None, None).await;
        }
        a.seed_peer_recovery_time_stamp(100).await;
        pfcp_path::set_global_pool(vec![a.clone(), b.clone()]);
        let listener = spawn_pfcp_listener(sock, vec![a.clone(), b.clone()]);
        let reference = "72101";
        seed_binding(reference, 5);
        set_status_uri(
            reference,
            &format!(
                "http://127.0.0.1:{}/namf-callback/v1/sm-status",
                amf_addr.port()
            ),
        );
        let seid = context::derive_cp_n4_seid(reference);
        if let Ok(ctx) = smf_self().read() {
            ctx.pfcp_sessions
                .write()
                .unwrap()
                .insert(reference.to_string(), 0x721);
        }
        pfcp_path::record_session_peer(seid, a.peer());

        // UPF A's Heartbeat Request, carrying its NEW Recovery Time Stamp.
        let mut rts = 96u16.to_be_bytes().to_vec();
        rts.extend_from_slice(&4u16.to_be_bytes());
        rts.extend_from_slice(&200u32.to_be_bytes());
        let hb = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::HEARTBEAT_REQUEST,
            None,
            0x721,
            &rts,
        );
        let started = std::time::Instant::now();
        upf_a.send_to(&hb, smf_addr).await.unwrap();
        let mut buf = vec![0u8; 512];
        let (len, _) =
            tokio::time::timeout(std::time::Duration::from_secs(5), upf_a.recv_from(&mut buf))
                .await
                .expect("a Heartbeat Response")
                .unwrap();
        let answered_in = started.elapsed();
        let h = pfcp_path::parse_wire_header(&buf[..len]).unwrap();
        // And the receive task still serves UPF B while A's release is in flight.
        let b_started = std::time::Instant::now();
        let b_result = b
            .request(
                pfcp_path::pfcp_message_type::SESSION_DELETION_REQUEST,
                Some(0x721b),
                &[],
            )
            .await;
        let b_in = b_started.elapsed();
        let in_flight = posts.load(std::sync::atomic::Ordering::SeqCst);
        // Let the release finish before tearing the fixture down.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while posts.load(std::sync::atomic::Ordering::SeqCst) == 0
            && std::time::Instant::now() < deadline
        {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        let released = posts.load(std::sync::atomic::Ordering::SeqCst);
        cancel_gsm_timer(reference, timer::SmfTimerId::T3592);
        if let Ok(ctx) = smf_self().read() {
            ctx.policy_bindings.write().unwrap().remove(reference);
        }
        pfcp_path::forget_session_peer(seid);
        listener.abort();
        task_b.abort();
        amf.stop().await.ok();
        pfcp_path::clear_global_upf_for_test();

        assert_eq!(h.msg_type, pfcp_path::pfcp_message_type::HEARTBEAT_RESPONSE);
        assert!(
            answered_in < std::time::Duration::from_millis(500),
            "the heartbeat is answered before the releases: {answered_in:?}"
        );
        assert!(
            b_result.is_ok(),
            "UPF B's transaction completes: {b_result:?}"
        );
        assert!(
            b_in < std::time::Duration::from_millis(500),
            "while A's release is in flight: {b_in:?}"
        );
        assert_eq!(in_flight, 0, "A's release was still in flight then");
        assert_eq!(released, 1, "and A's session is released (#39) after all");
    }

    /// #941 review MINOR 1: the EPC deletion count is exact when the deadline fires
    /// while the fan-out waits for a permit. Of 40 EPC sessions the PGW-U answers the
    /// first 16 deletions and none after, so the next 16 hold every permit when the
    /// deadline fires; the 16 that were answered are counted. Before, the join loop
    /// that counted them never ran, and the count was 0.
    #[tokio::test]
    async fn the_epc_shutdown_counts_what_was_deleted_when_out_of_time() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let upf = std::sync::Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let upf_addr = upf.local_addr().unwrap();
        let u = upf.clone();
        let upf_task = tokio::spawn(async move {
            let mut buf = vec![0u8; 4096];
            let mut answered = 0;
            while let Ok((len, from)) = u.recv_from(&mut buf).await {
                let Some(h) = pfcp_path::parse_wire_header(&buf[..len]) else {
                    continue;
                };
                if h.msg_type == pfcp_path::pfcp_message_type::SESSION_DELETION_REQUEST
                    && answered < 16
                {
                    answered += 1;
                    let reply = pfcp_path::encode_wire_message(
                        pfcp_path::pfcp_message_type::SESSION_DELETION_RESPONSE,
                        Some(h.seid),
                        h.sequence_number,
                        &[0, 19, 0, 1, 1],
                    );
                    let _ = u.send_to(&reply, from).await;
                }
            }
        });
        let (client, listener) = client_behind_the_real_listener(upf_addr).await;
        let mut ids = Vec::new();
        if let Ok(ctx) = smf_self().read() {
            for sess in ctx.sess_find_all_by(|s| s.epc) {
                ctx.sess_remove(sess.id);
            }
            for i in 0..40u64 {
                let imsi = format!("0010100000941{i:02}");
                let ue = ctx.ue_add_by_imsi(imsi.as_bytes()).expect("ue");
                let sess = ctx.sess_add_by_apn(ue.id, "internet", 6).expect("sess");
                let mut sess = ctx.sess_find_by_seid(sess.smf_n4_seid).expect("sess");
                sess.upf_n4_seid = 0x9410 + i;
                ctx.sess_update(&sess);
                pfcp_path::record_session_peer(sess.smf_n4_seid, client.peer());
                ids.push(sess.id);
            }
        }

        let (deleted, told) = shutdown_epc_pdn_connections_via(
            None,
            0,
            tokio::time::Instant::now() + std::time::Duration::from_millis(1500),
        )
        .await;
        listener.abort();
        upf_task.abort();
        if let Ok(ctx) = smf_self().read() {
            for id in &ids {
                if let Some(sess) = ctx.sess_find_by_id(*id) {
                    pfcp_path::forget_session_peer(sess.smf_n4_seid);
                    ctx.sess_remove(*id);
                }
            }
        }
        pfcp_path::clear_global_upf_for_test();

        assert_eq!(told, 0);
        assert_eq!(deleted, 16, "the answered deletions are counted");
    }

    /// #718 review M4: a shutdown that keeps the N4 association for durable state
    /// still deletes every EPC PFCP session at the PGW-U. EPC PDN connections are not
    /// in the snapshot, so the next incarnation could not ask for them, and its
    /// retention request would keep them in the PGW-U with nobody owning them.
    #[tokio::test]
    async fn a_shutdown_that_keeps_the_association_deletes_the_epc_sessions() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        smf_context_init(64, 256, 512);
        let upf = pfcp_path::stand_in::associated_upf().await;
        let sess_id = {
            let ctx = smf_self();
            let ctx = ctx.read().unwrap();
            // Leftovers of earlier tests; the state lock is held, so they belong to
            // nobody running now.
            for sess in ctx.sess_find_all_by(|s| s.epc && s.upf_n4_seid != 0) {
                ctx.sess_remove(sess.id);
            }
            let ue = ctx.ue_add_by_imsi(b"001010000071804").expect("ue");
            let mut sess = ctx.sess_add_by_apn(ue.id, "internet", 6).expect("sess");
            sess.upf_n4_seid = 0x7184;
            ctx.sess_update(&sess);
            sess.id
        };
        let (deleted, _told) = shutdown_epc_pdn_connections(
            tokio::time::Instant::now() + std::time::Duration::from_secs(30),
        )
        .await;
        let seen = upf.seen();
        if let Ok(ctx) = smf_self().read() {
            ctx.sess_remove(sess_id);
        }
        assert_eq!(deleted, 1, "the EPC session was deleted at the PGW-U");
        assert!(
            seen.contains(&pfcp_path::pfcp_message_type::SESSION_DELETION_REQUEST),
            "a Session Deletion Request reached the PGW-U: {seen:?}"
        );
    }

    // ------------------------------------------------------------------
    // #525: AN-initiated modification (PDU_RES_MOD_IND -> PDU_RES_MOD_CFM)
    // ------------------------------------------------------------------

    fn seed_session(sm_context_ref: &str, upf_seid: Option<u64>, ul: Option<(u32, [u8; 4])>) {
        let smf = smf_self();
        let ctx = smf.read().expect("smf context");
        if let Some(seid) = upf_seid {
            ctx.pfcp_sessions
                .write()
                .expect("pfcp sessions")
                .insert(sm_context_ref.to_string(), seid);
        }
        if let Some(ep) = ul {
            ctx.upf_ul_endpoints
                .write()
                .expect("ul endpoints")
                .insert(sm_context_ref.to_string(), ep);
        }
    }

    fn unseed_session(sm_context_ref: &str) {
        let smf = smf_self();
        let ctx = smf.read().expect("smf context");
        ctx.pfcp_sessions
            .write()
            .expect("pfcp")
            .remove(sm_context_ref);
        ctx.upf_ul_endpoints
            .write()
            .expect("ul")
            .remove(sm_context_ref);
    }

    fn indication(dl: [u8; 4], teid: u32, qfis: &[u8]) -> Vec<u8> {
        use nextgcore_ngap::transfer::{
            AssociatedQosFlowItem, GtpTunnel, PduSessionResourceModifyIndicationTransfer,
            QosFlowPerTnlInformation, TransportLayerAddress, UpTransportLayerInformation,
        };
        PduSessionResourceModifyIndicationTransfer {
            dl_qos_flow_per_tnl_information: QosFlowPerTnlInformation {
                up_transport_layer_information: UpTransportLayerInformation::GtpTunnel(GtpTunnel {
                    transport_layer_address: TransportLayerAddress::from_ipv4(dl),
                    gtp_teid: teid.to_be_bytes(),
                }),
                associated_qos_flow_list: qfis
                    .iter()
                    .map(|&q| AssociatedQosFlowItem {
                        qos_flow_identifier: q,
                        qos_flow_mapping_indication: None,
                    })
                    .collect(),
            },
            additional_dl_qos_flow_per_tnl_information: Vec::new(),
        }
        .encode()
        .expect("encode Modify Indication Transfer")
    }

    fn answer(resp: &SbiResponse) -> (String, Vec<u8>) {
        assert_eq!(resp.status, 200);
        let body: serde_json::Value =
            serde_json::from_str(resp.http.content.as_deref().expect("body")).expect("json");
        let part = resp
            .http
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n2SmInfo"))
            .expect("n2SmInfo part");
        (
            body["n2SmInfoType"]
                .as_str()
                .expect("n2SmInfoType")
                .to_string(),
            part.data.to_vec(),
        )
    }

    /// TS 23.502 §4.3.3.2: the SMF switches the UPF's DL FAR to the endpoint the
    /// NG-RAN reports and answers PDU_RES_MOD_CFM with a Modify Confirm Transfer
    /// confirming the reported flows and re-stating the UPF's UL N3 endpoint.
    #[tokio::test]
    async fn an_initiated_modification_switches_the_dl_far_and_confirms() {
        use nextgcore_ngap::transfer::{
            PduSessionResourceModifyConfirmTransfer, UpTransportLayerInformation,
        };
        // #779 review m1: process-wide SMF context state, ambient lock first.
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let upf = pfcp_path::stand_in::install_stand_in_upf().await;
        upf.client.associate().await.expect("association");
        upf.clear_seen();
        let r = "525-mod-ind-ok";
        seed_session(r, Some(upf.upf_seid), Some((upf.upf_teid, upf.upf_ip)));

        let resp = an_initiated_modification(r, &indication([10, 1, 2, 3], 0xabcd, &[1, 2])).await;
        unseed_session(r);
        let (ty, n2) = answer(&resp);
        assert_eq!(ty, "PDU_RES_MOD_CFM");
        let confirm = PduSessionResourceModifyConfirmTransfer::decode(&n2).expect("decode");
        assert_eq!(confirm.qos_flow_modify_confirm_list, vec![1, 2]);
        let UpTransportLayerInformation::GtpTunnel(ul) = confirm.ul_ngu_up_tnl_information;
        assert_eq!(u32::from_be_bytes(ul.gtp_teid), upf.upf_teid);
        assert_eq!(ul.transport_layer_address.octets, upf.upf_ip.to_vec());

        let bodies = upf.modification_bodies();
        assert_eq!(bodies.len(), 1, "exactly one Session Modification");
        let body = &bodies[0];
        let has = |needle: &[u8]| body.windows(needle.len()).any(|w| w == needle);
        assert!(
            has(&[0x00, 0x00, 0xab, 0xcd, 10, 1, 2, 3]),
            "the DL FAR's Outer Header Creation carries the reported endpoint: {body:02x?}"
        );
    }

    /// #1230 review 2: a Modify Indication for a context without its uplink endpoint
    /// recovers it (Remove, then Create PDR 1), and the Modify Confirm Transfer names
    /// the F-TEID the UPF chose.
    #[tokio::test]
    async fn an_initiated_modification_recovers_a_missing_endpoint() {
        use nextgcore_ngap::transfer::{
            PduSessionResourceModifyConfirmTransfer, UpTransportLayerInformation,
        };
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let upf = pfcp_path::stand_in::install_stand_in_upf().await;
        upf.client.associate().await.expect("association");
        upf.clear_seen();
        let r = "1230-mod-ind";
        seed_session(r, Some(upf.upf_seid), None);
        {
            let ctx = smf_self();
            let ctx = ctx.read().unwrap();
            let mut b = context::PolicyBinding::snapshot_default();
            b.qfi = 1;
            b.five_qi = 9;
            b.ue_ip = [10, 45, 123, 5];
            ctx.policy_bindings
                .write()
                .unwrap()
                .insert(r.to_string(), b);
        }
        let resp = an_initiated_modification(r, &indication([10, 1, 2, 3], 0xabcd, &[1])).await;
        let recovered = lookup_upf_ul_endpoint(r);
        let mods = upf.modification_bodies();
        unseed_session(r);
        smf_self()
            .read()
            .unwrap()
            .policy_bindings
            .write()
            .unwrap()
            .remove(r);
        let (ty, n2) = answer(&resp);
        assert_eq!(ty, "PDU_RES_MOD_CFM");
        assert_recovery_mods(&mods);
        let (teid, _) = recovered.expect("recorded");
        let confirm = PduSessionResourceModifyConfirmTransfer::decode(&n2).expect("decode");
        let UpTransportLayerInformation::GtpTunnel(ul) = confirm.ul_ngu_up_tnl_information;
        assert_eq!(u32::from_be_bytes(ul.gtp_teid), teid);
    }

    /// No N4 session, or an undecodable transfer: the SMF answers
    /// PDU_RES_MOD_IND_FAIL with a Modify Indication Unsuccessful Transfer naming
    /// why, and sends nothing to the UPF.
    #[tokio::test]
    async fn an_initiated_modification_it_cannot_carry_out_is_answered_ind_fail() {
        use nextgcore_asn1c::ngap::cause::{Cause, CauseMisc, CauseProtocol};
        use nextgcore_ngap::transfer::PduSessionResourceModifyIndicationUnsuccessfulTransfer as Unsuccessful;
        // #779 review m1: process-wide SMF context state, ambient lock first.
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let upf = pfcp_path::stand_in::install_stand_in_upf().await;
        upf.client.associate().await.expect("association");
        upf.clear_seen();

        let resp = an_initiated_modification(
            "525-no-n4-session",
            &indication([10, 1, 2, 3], 0xabcd, &[1]),
        )
        .await;
        let (ty, n2) = answer(&resp);
        assert_eq!(ty, "PDU_RES_MOD_IND_FAIL");
        assert_eq!(
            Unsuccessful::decode(&n2).expect("decode").cause,
            Cause::Misc(CauseMisc::Unspecified)
        );

        let resp = an_initiated_modification("525-garbage", &[0xff]).await;
        let (ty, n2) = answer(&resp);
        assert_eq!(ty, "PDU_RES_MOD_IND_FAIL");
        assert_eq!(
            Unsuccessful::decode(&n2).expect("decode").cause,
            Cause::Protocol(CauseProtocol::AbstractSyntaxErrorFalselyConstructedMessage)
        );
        assert!(
            upf.modification_bodies().is_empty(),
            "nothing reaches the UPF"
        );
    }

    // ------------------------------------------------------------------
    // #380: the Prometheus endpoint the EPC readiness gate polls
    // ------------------------------------------------------------------

    /// The render emits the families the gate and the PGW-C healthcheck grep for, and
    /// `smf_n4_associations` counts the pool's LIVE association state rather than its
    /// size.
    ///
    /// The pool-of-one-un-associated case is the one that matters: it is exactly the
    /// deployment shape the gate has to reject — a PGW-C container that started, bound its
    /// S5/S8 socket, and never established Sxb with its PGW-U, which cannot legally answer
    /// a Create Session Request (TS 29.244 §6.2.6.2) yet reports `kill -0 1` healthy.
    #[tokio::test]
    async fn the_metrics_render_counts_live_n4_associations_not_configured_peers() {
        let upf = pfcp_path::stand_in::install_stand_in_upf().await;

        // Installed but NOT associated: one configured peer, zero associations.
        let body = render_metrics();
        for expected in [
            "# TYPE smf_n4_associations gauge",
            "smf_n4_associations 0",
            "smf_n4_peers 1",
            "smf_up 1",
        ] {
            assert!(body.contains(expected), "missing {expected} in:\n{body}");
        }

        upf.client
            .associate()
            .await
            .expect("the stand-in UPF accepts the association");
        assert!(
            render_metrics().contains("smf_n4_associations 1"),
            "a real Association Setup must move the gauge the gate polls"
        );

        // And back down. The setter rather than the wire teardown, deliberately: what is
        // under test HERE is that the render re-reads live state on every scrape. That the
        // gauge itself follows the real Association Setup and the real teardown is proven
        // over the socket in `pfcp_path`'s
        // `the_sync_association_gauge_follows_the_wire_association`, and duplicating that
        // here would not make either claim stronger.
        upf.client.set_assoc_state_for_test(false, None, None).await;
        assert!(
            render_metrics().contains("smf_n4_associations 0"),
            "the render must re-read live state on every scrape; a gauge that only \
             counts up would pass the assertion above and still be wrong"
        );
    }

    #[test]
    fn the_metrics_port_is_9090_unless_overridden() {
        // The port `sgwud` uses, the port `configs/observability/prometheus.yml` already
        // scrapes 172.23.0.4 on, and the port the healthcheck curls. A default that
        // drifted from those would leave the gate polling a closed socket.
        assert_eq!(metrics_addr().port(), 9090);
        // #837: unauthenticated, so loopback unless the deployment opts in.
        if std::env::var_os(nextgcore_metrics::nes_energy::METRICS_BIND_ENV).is_none() {
            assert!(metrics_addr().ip().is_loopback(), "{}", metrics_addr());
        }
    }

    // ------------------------------------------------------------------
    // NRF profile: one registration, the whole routed surface (#392)
    // ------------------------------------------------------------------

    /// #392: the registered NFProfile advertises `nsmf-event-exposure` as well as
    /// `nsmf-pdusession`.
    ///
    /// Positive on both names. `nsmf-event-exposure` is routed by
    /// `smf_sbi_request_handler` against a real subscription store, but was absent
    /// from the profile — and the NRF filters discovery strictly on
    /// `nfServices[].serviceName`, so no consumer could find it. The DCCF selects
    /// an event-exposure producer by matching `serviceName` against
    /// `eventexposure`/`evts` (`dccfd`'s `coordination.rs`), so this SMF was
    /// invisible to data collection.
    /// #1112 (TS 29.510 Table 6.1.6.3.7-1): an SMF with no N4 association registers
    /// UNDISCOVERABLE, so discovery does not return it, and REGISTERED once one is up.
    #[test]
    fn the_registered_nf_status_follows_the_n4_association() {
        use nextgcore_sbi::context::NfStatus;
        assert_eq!(nf_status_for_n4(false), NfStatus::Undiscoverable);
        assert_eq!(nf_status_for_n4(true), NfStatus::Registered);
        let profile = build_smf_nf_profile(
            "smf-1112",
            "10.45.0.6",
            7777,
            nextgcore_sbi::types::UriScheme::Http,
        );
        assert_eq!(profile["nfStatus"], "REGISTERED");
        let undiscoverable = with_nf_status(profile, NfStatus::Undiscoverable);
        assert_eq!(undiscoverable["nfStatus"], "UNDISCOVERABLE");
        assert_eq!(
            undiscoverable["nfServices"][0]["nfServiceStatus"], "REGISTERED",
            "the services keep their own status; the NF-level one gates discovery"
        );
    }

    /// #1112: the watcher's step. It adopts the status the N4 state calls for once,
    /// so the heartbeat PATCHes carry it, and rewrites the profile a 404 heartbeat
    /// re-registers, so a re-registration does not undo it.
    ///
    /// REVERT-VERIFIED: with the profile rewrite removed, the recorded profile
    /// stays REGISTERED while the SMF is UNDISCOVERABLE.
    #[test]
    fn reconciling_the_n4_status_changes_the_advertised_status_once() {
        use nextgcore_sbi::context::NfStatus;
        use nextgcore_sbi::heartbeat as hb;
        // The heartbeat globals' own lock, declared beside them in nextgcore-sbi.
        let _registration = hb::lock_registration_state_for_test();
        let before = (hb::self_nf_status(), hb::registered_profile());
        hb::set_self_nf_status(NfStatus::Registered);
        hb::set_registered_profile(&build_smf_nf_profile(
            "smf-1112",
            "10.45.0.6",
            7777,
            nextgcore_sbi::types::UriScheme::Http,
        ));

        assert_eq!(
            reconcile_n4_nf_status(false),
            Some(NfStatus::Undiscoverable)
        );
        assert_eq!(hb::self_nf_status(), NfStatus::Undiscoverable);
        assert_eq!(
            hb::registered_profile().unwrap()["nfStatus"],
            "UNDISCOVERABLE"
        );
        assert_eq!(
            hb::build_load_patch(0)[0]["value"],
            "UNDISCOVERABLE",
            "the heartbeat says so too"
        );
        assert_eq!(reconcile_n4_nf_status(false), None, "no PATCH per tick");

        assert_eq!(reconcile_n4_nf_status(true), Some(NfStatus::Registered));
        assert_eq!(hb::registered_profile().unwrap()["nfStatus"], "REGISTERED");
        assert_eq!(reconcile_n4_nf_status(true), None);

        hb::set_self_nf_status(before.0);
        match before.1 {
            Some(p) => hb::set_registered_profile(&p),
            None => hb::clear_registered_profile(),
        }
    }

    /// #1112 (#1115 review M2), against a stand-in NRF: with no N4 association the
    /// registration PUT says UNDISCOVERABLE, and the watcher it starts then PATCHes
    /// the NRF exactly once per association change -- REGISTERED when the UPF
    /// associates, UNDISCOVERABLE when it goes -- and not on every tick.
    ///
    /// REVERT-VERIFIED: registering REGISTERED fails the PUT assertion, and without
    /// the watcher spawn no PATCH arrives.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[allow(clippy::await_holding_lock)] // the heartbeat globals' std lock, see below
    async fn the_nrf_is_told_the_n4_state_once_per_change() {
        use nextgcore_sbi::context::NfStatus;
        use nextgcore_sbi::heartbeat as hb;
        use nextgcore_sbi::message::{SbiRequest as SReq, SbiResponse as SResp};
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        // The heartbeat globals' own (std) lock, beside them in nextgcore-sbi. Held
        // across this test's awaits on purpose: it serialises the globals, and no
        // other task of this test takes it.
        let _registration = hb::lock_registration_state_for_test();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        // Installed, not associated, before the registration: the N4 lock is held for
        // the whole test, so no sibling's UPF is what the watcher sees.
        let upf = pfcp_path::stand_in::unassociated_upf().await;
        // Everything this test sets process-wide is restored when it ends, whether it
        // passes or panics (#1115 review n4).
        let _restore = N4StatusTestRestore {
            status: hb::self_nf_status(),
            profile: hb::registered_profile(),
        };

        let seen: Arc<std::sync::Mutex<Vec<(String, serde_json::Value)>>> = Arc::default();
        let recorded = Arc::clone(&seen);
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let nrf = nextgcore_sbi::server::SbiServer::on_listener(
            nextgcore_sbi::server::SbiServerConfig::new(addr),
            listener,
        );
        nrf.start(move |req: SReq| {
            let recorded = Arc::clone(&recorded);
            async move {
                let body = req
                    .http
                    .content
                    .as_deref()
                    .and_then(|c| serde_json::from_str(c).ok())
                    .unwrap_or(serde_json::Value::Null);
                recorded
                    .lock()
                    .unwrap()
                    .push((req.header.method.clone(), body));
                if req.header.method == "PUT" {
                    SResp::with_status(201)
                } else {
                    SResp::with_status(204)
                }
            }
        })
        .await
        .expect("stand-in NRF");
        global_context().set_nrf_uri(format!("http://{addr}")).await;
        hb::set_self_nf_status(NfStatus::Registered);

        let registered =
            smf_nrf_register("127.0.0.1", 7777, nextgcore_sbi::types::UriScheme::Http).await;
        let patches = |seen: &std::sync::Mutex<Vec<(String, serde_json::Value)>>| -> Vec<String> {
            seen.lock()
                .unwrap()
                .iter()
                .filter(|(m, _)| m == "PATCH")
                .map(|(_, b)| b[0]["value"].as_str().unwrap_or("").to_string())
                .collect()
        };
        let wait_for = |n: usize| {
            let seen = Arc::clone(&seen);
            async move {
                let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(3);
                while patches(&seen).len() < n && tokio::time::Instant::now() < deadline {
                    tokio::time::sleep(std::time::Duration::from_millis(20)).await;
                }
            }
        };
        let put = seen
            .lock()
            .unwrap()
            .iter()
            .find(|(m, _)| m == "PUT")
            .map(|(_, b)| b["nfStatus"].clone());

        upf.client.associate().await.expect("association");
        wait_for(1).await;
        let after_association = patches(&seen);
        upf.client.set_assoc_state_for_test(false, None, None).await;
        wait_for(2).await;
        // Several more ticks: no further PATCH.
        tokio::time::sleep(N4_NF_STATUS_POLL * 3).await;
        let all = patches(&seen);
        // An NF that paused its own heartbeats (NES) is not PATCHed behind them.
        hb::set_heartbeat_paused(true);
        upf.client.associate().await.expect("association");
        tokio::time::sleep(N4_NF_STATUS_POLL * 3).await;
        let while_paused = patches(&seen);
        hb::set_heartbeat_paused(false);
        nrf.stop().await.ok();

        assert!(registered.is_ok(), "{registered:?}");
        assert_eq!(put, Some(serde_json::json!("UNDISCOVERABLE")));
        assert_eq!(after_association, vec!["REGISTERED"]);
        assert_eq!(
            all,
            vec!["REGISTERED", "UNDISCOVERABLE"],
            "one PATCH per change"
        );
        assert_eq!(
            while_paused, all,
            "no PATCH while the heartbeats are paused"
        );
    }

    /// Restores what `the_nrf_is_told_the_n4_state_once_per_change` set process-wide:
    /// the watcher, the NRF URI, the pause flag, the advertised status and profile.
    struct N4StatusTestRestore {
        status: nextgcore_sbi::context::NfStatus,
        profile: Option<serde_json::Value>,
    }

    impl Drop for N4StatusTestRestore {
        fn drop(&mut self) {
            use nextgcore_sbi::heartbeat as hb;
            abort_n4_nf_status_watcher();
            hb::set_heartbeat_paused(false);
            hb::set_self_nf_status(self.status);
            match self.profile.take() {
                Some(p) => hb::set_registered_profile(&p),
                None => hb::clear_registered_profile(),
            }
            // The URI is behind an async lock; cleared on a runtime of its own, on a
            // scoped thread, since this may run while the test's runtime unwinds.
            std::thread::scope(|s| {
                s.spawn(|| {
                    tokio::runtime::Builder::new_current_thread()
                        .build()
                        .expect("cleanup runtime")
                        .block_on(global_context().clear_nrf_uri());
                });
            });
        }
    }

    /// #1115 review n1: the shutdown stops the N4 status watcher before it
    /// deregisters, so the association release that follows PATCHes no instance the
    /// NRF has dropped.
    ///
    /// REVERT-VERIFIED: without `abort_n4_nf_status_watcher` in `graceful_shutdown`,
    /// the watcher is still running when the deregistration starts.
    #[tokio::test]
    async fn the_shutdown_stops_the_n4_status_watcher_before_it_deregisters() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        spawn_n4_nf_status_watcher("smf-1115-shutdown".to_string());
        let running_at_deregister = std::sync::Arc::new(AtomicBool::new(true));
        let probe = running_at_deregister.clone();
        let listener = tokio::spawn(async {});
        graceful_shutdown(
            async move {
                let running = N4_NF_STATUS_WATCHER
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .as_ref()
                    .is_some_and(|w| !w.is_finished());
                probe.store(running, Ordering::SeqCst);
            },
            &[],
            false,
            listener,
            tokio::time::Instant::now() + std::time::Duration::from_secs(30),
        )
        .await;
        abort_n4_nf_status_watcher();
        assert!(
            !running_at_deregister.load(Ordering::SeqCst),
            "the watcher is stopped before the deregistration"
        );
    }

    /// #1112: what the watcher polls, read off the association of the UPF a new
    /// session would use.
    #[tokio::test]
    async fn session_upf_associated_follows_the_n4_association() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let upf = pfcp_path::stand_in::unassociated_upf().await;
        assert!(!pfcp_path::session_upf_associated());
        upf.client.associate().await.expect("association");
        assert!(pfcp_path::session_upf_associated());
        upf.client.set_assoc_state_for_test(false, None, None).await;
        assert!(!pfcp_path::session_upf_associated());
    }

    #[test]
    fn the_smf_profile_advertises_both_routed_nsmf_services() {
        let profile = build_smf_nf_profile(
            "smf-test-instance",
            "10.45.0.6",
            7777,
            nextgcore_sbi::types::UriScheme::Http,
        );
        let names: Vec<&str> = profile["nfServices"]
            .as_array()
            .expect("nfServices")
            .iter()
            .map(|s| s["serviceName"].as_str().expect("serviceName"))
            .collect();

        assert!(names.contains(&"nsmf-pdusession"), "advertised: {names:?}");
        assert!(
            names.contains(&"nsmf-event-exposure"),
            "the SMF routes nsmf-event-exposure but does not advertise it, so the NRF drops \
             this SMF from any SearchResult filtered on that service. Advertised: {names:?}"
        );

        // A callback is dialled at the absolute notificationUri this SMF handed a
        // peer, never discovered; TS 23.501 Table 7.2.3-1 does not list it.
        assert!(
            !names.contains(&"nsmf-callback"),
            "nsmf-callback is not a discoverable service"
        );

        for svc in profile["nfServices"].as_array().expect("nfServices") {
            let name = svc["serviceName"].as_str().unwrap_or_default();
            let eps = svc["ipEndPoints"]
                .as_array()
                .unwrap_or_else(|| panic!("{name} carries no ipEndPoints"));
            assert_eq!(eps[0]["port"].as_u64(), Some(7777), "{name} port");
            assert!(
                svc["allowedNfTypes"]
                    .as_array()
                    .is_some_and(|a| !a.is_empty()),
                "{name} must state its allowedNfTypes (TS 29.510 §6.1.6.2.3)"
            );
        }

        // DCCF consumes the event feed, so it cannot be barred at NF level.
        let nf_level: Vec<&str> = profile["allowedNfTypes"]
            .as_array()
            .expect("allowedNfTypes")
            .iter()
            .map(|v| v.as_str().unwrap_or_default())
            .collect();
        assert!(nf_level.contains(&"AMF"), "{nf_level:?}");
        assert!(nf_level.contains(&"DCCF"), "{nf_level:?}");
    }

    /// #392: the typed self instance and the registered profile advertise the SAME
    /// surface, because both render `SMF_SERVICES`.
    #[test]
    fn the_smf_self_instance_matches_the_registered_profile() {
        let instance = build_smf_nf_instance("smf-test-instance", "10.45.0.6", 7777);
        let profile = build_smf_nf_profile(
            "smf-test-instance",
            "10.45.0.6",
            7777,
            nextgcore_sbi::types::UriScheme::Http,
        );

        let mut from_instance: Vec<String> =
            instance.services.iter().map(|s| s.name.clone()).collect();
        let mut from_profile: Vec<String> = profile["nfServices"]
            .as_array()
            .expect("nfServices")
            .iter()
            .map(|s| s["serviceName"].as_str().unwrap_or_default().to_string())
            .collect();
        from_instance.sort();
        from_profile.sort();

        assert_eq!(
            from_instance, from_profile,
            "the self instance carried nsmf-pdusession alone while the profile is table-driven"
        );
        assert_eq!(from_instance.len(), SMF_SERVICES.len());
    }

    // ------------------------------------------------------------------
    // 5GS TSC container carriage (#321)
    // ------------------------------------------------------------------
    //
    // Every one of these drives the REAL wire path: the SMF's own
    // `pfcp_send_tsc_containers` against a stand-in UPF that records the bodies it
    // received. Asserting on the recorded body rather than on a log line is what
    // makes "the gate held" distinguishable from "the gate is not implemented".

    /// A PMIC/UMIC pair, as a PCF decision would deliver them.
    #[cfg(test)]
    fn tsc_fixture() -> policy::TscContainers {
        policy::TscContainers {
            bridge_man_cont: Some(vec![0xE1, 0xE2]),
            port_man_cont_dstt: Some((vec![0xD1], 1)),
            port_man_cont_nwtts: vec![(vec![0xF1, 0xF2, 0xF3], 7)],
        }
    }

    /// Every TSC Management Information IE (199) in a recorded request body.
    #[cfg(test)]
    fn tsc_ies_in(body: &[u8]) -> Vec<nextgcore_pfcp::types::TscManagementInformation> {
        decode_tsc_ies(body, 199)
    }

    /// Criterion 2 (SMF half): a Session Modification actually carries the
    /// containers, under IE 199, with the octets the PCF authorised.
    #[tokio::test]
    async fn test_tsc_containers_are_carried_on_a_session_modification() {
        let upf = pfcp_path::stand_in::associated_upf_with_features(
            nextgcore_pfcp::types::UpFunctionFeatures {
                ftup: true,
                tscu: true,
                ..Default::default()
            },
        )
        .await;
        pfcp_path::record_session_peer(0xABCD, upf.client.peer());

        let sent = pfcp_send_tsc_containers(0xABCD, upf.upf_seid, &tsc_fixture())
            .await
            .expect("a TSC-capable UPF must accept the modification");

        // Two IEs: one NW-TT port PMIC, one bridge-level UMIC. The DS-TT container
        // is deliberately NOT among them -- see `TscContainers::to_n4_ies`.
        assert_eq!(sent, 2, "one NW-TT PMIC IE plus one UMIC IE");

        let bodies = upf.modification_bodies();
        assert_eq!(bodies.len(), 1, "exactly one Session Modification was sent");
        let ies = tsc_ies_in(&bodies[0]);
        assert_eq!(
            ies.len(),
            2,
            "both TSC IEs must be on the wire under IE 199"
        );

        let pmic = ies
            .iter()
            .find(|ie| ie.port_management_container.is_some())
            .expect("a PMIC IE must be present");
        assert_eq!(
            pmic.port_management_container.as_deref(),
            Some(&[0xF1, 0xF2, 0xF3][..]),
            "the PMIC octets must reach the UPF byte-exact: they are an opaque \
             TS 24.539 payload the SMF only relays"
        );
        assert_eq!(
            pmic.nw_tt_port_number,
            Some(7),
            "the NW-TT port number the PCF named must travel with its container"
        );

        let umic = ies
            .iter()
            .find(|ie| ie.user_plane_node_management_container.is_some())
            .expect("a UMIC IE must be present");
        assert_eq!(
            umic.user_plane_node_management_container.as_deref(),
            Some(&[0xE1, 0xE2][..])
        );
        assert!(
            umic.nw_tt_port_number.is_none(),
            "a UMIC is bridge-level and must carry no port identity"
        );

        // `SESSION_PEERS` is process-global and outlives this test's N4 guard, so the
        // mapping is removed rather than left pointing at a stand-in that is about to
        // be dropped. A leaked entry makes `client_for_session` fall back to the
        // default client for that SEID, which is the kind of cross-test coupling that
        // only shows up as an order-dependent failure.
        pfcp_path::forget_session_peer(0xABCD);
    }

    /// Criterion 3: a UPF that did not advertise TSCU is NOT sent TSC containers.
    ///
    /// The default stand-in advertises `ftup` only, so this is the ordinary case.
    #[tokio::test]
    async fn test_tsc_containers_withheld_from_a_upf_without_tscu() {
        let upf = pfcp_path::stand_in::associated_upf().await;
        assert!(
            !upf.client
                .association()
                .await
                .up_function_features
                .unwrap()
                .tscu,
            "precondition: the default stand-in must NOT advertise TSCU"
        );
        pfcp_path::record_session_peer(0xABCE, upf.client.peer());

        let sent = pfcp_send_tsc_containers(0xABCE, upf.upf_seid, &tsc_fixture())
            .await
            .expect("withholding is a successful no-op, not an error");

        assert_eq!(sent, 0, "nothing may be sent to a UPF without TSCU");
        assert!(
            upf.modification_bodies().is_empty(),
            "NO Session Modification at all may be sent: the message exists only to \
             carry the TSC IEs, so sending an empty one would be traffic that asks \
             the UPF for nothing"
        );

        pfcp_path::forget_session_peer(0xABCE);
    }

    /// An authorisation carrying nothing sends nothing, even to a capable UPF.
    #[tokio::test]
    async fn test_empty_tsc_authorisation_sends_no_modification() {
        let upf = pfcp_path::stand_in::associated_upf_with_features(
            nextgcore_pfcp::types::UpFunctionFeatures {
                ftup: true,
                tscu: true,
                ..Default::default()
            },
        )
        .await;
        pfcp_path::record_session_peer(0xABCF, upf.client.peer());

        let sent =
            pfcp_send_tsc_containers(0xABCF, upf.upf_seid, &policy::TscContainers::default())
                .await
                .expect("no containers is a no-op");
        assert_eq!(sent, 0);
        assert!(upf.modification_bodies().is_empty());

        pfcp_path::forget_session_peer(0xABCF);
    }

    /// Criterion 4: a Session Report carrying IE 201 reaches the SMF, is decoded,
    /// and is observable from the SMF's own state rather than from a log line.
    #[tokio::test]
    async fn test_session_report_tsc_management_information_is_decoded() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _guard = pfcp_path::N4_TEST_LOCK.lock().await;
        pfcp_path::clear_tsc_reports_for_test();
        smf_context_init(64, 256, 512);

        let sock = std::sync::Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let peer = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer.local_addr().unwrap();
        // #974: a session this SMF holds, reported on by the UPF serving it.
        let reference = "9740201";
        smf_self()
            .read()
            .unwrap()
            .pfcp_sessions
            .write()
            .unwrap()
            .insert(reference.to_string(), 0x0BAD_F00D);
        let seid = crate::context::derive_cp_n4_seid(reference);
        pfcp_path::set_global_pool(vec![
            pfcp_path::PfcpClient::associated_for_test(sock.clone(), peer_addr).await,
        ]);

        // Body: Report Type with TMIR (bit 5 => 0x10) plus one IE 201 carrying a
        // PMIC and its NW-TT port. Hand-built, so the test does not depend on the
        // SMF's own encoder agreeing with itself.
        let mut tsc_buf = bytes::BytesMut::new();
        nextgcore_pfcp::types::TscManagementInformation::port(vec![0xAA, 0xBB], 9)
            .encode(&mut tsc_buf);
        let mut body = Vec::new();
        body.extend_from_slice(&[0x00, 39, 0x00, 0x01, 0x10]); // Report Type = TMIR
        body.extend_from_slice(&[0x00, 201]);
        body.extend_from_slice(&(tsc_buf.len() as u16).to_be_bytes());
        body.extend_from_slice(&tsc_buf);

        let pkt = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::SESSION_REPORT_REQUEST,
            Some(seid),
            42,
            &body,
        );

        handle_pfcp_session_report(&sock, &pkt, peer_addr).await;
        pfcp_path::clear_global_upf_for_test();
        smf_self()
            .read()
            .unwrap()
            .pfcp_sessions
            .write()
            .unwrap()
            .remove(reference);

        let reports = pfcp_path::tsc_reports_for(seid)
            .expect("the decoded TSC report must be recorded against the SEID");
        assert_eq!(reports.len(), 1);
        assert_eq!(
            reports[0].port_management_container.as_deref(),
            Some(&[0xAA, 0xBB][..])
        );
        assert_eq!(reports[0].nw_tt_port_number, Some(9));

        // And the SMF still answers the report, rather than treating an IE it now
        // understands as a reason to stop.
        let mut rbuf = vec![0u8; 512];
        let (len, _) =
            tokio::time::timeout(std::time::Duration::from_secs(2), peer.recv_from(&mut rbuf))
                .await
                .expect("a Session Report Response must be sent")
                .unwrap();
        let h = pfcp_path::parse_wire_header(&rbuf[..len]).unwrap();
        assert_eq!(
            h.msg_type,
            pfcp_path::pfcp_message_type::SESSION_REPORT_RESPONSE
        );

        pfcp_path::clear_tsc_reports_for_test();
    }

    /// A TMIR bit with no IE 201 records nothing, and does not invent an empty
    /// report. The peer contradicted itself; storing `Some(vec![])` would make
    /// "reported nothing" indistinguishable from "reported an empty container set".
    #[tokio::test]
    async fn test_session_report_tmir_without_ie_records_nothing() {
        let _guard = pfcp_path::N4_TEST_LOCK.lock().await;
        pfcp_path::clear_tsc_reports_for_test();

        let sock = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let peer = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer.local_addr().unwrap();
        let seid = 0x0000_0000_0BAD_BEEFu64;

        let body = vec![0x00, 39, 0x00, 0x01, 0x10]; // TMIR set, no IE 201
        let pkt = pfcp_path::encode_wire_message(
            pfcp_path::pfcp_message_type::SESSION_REPORT_REQUEST,
            Some(seid),
            43,
            &body,
        );
        handle_pfcp_session_report(&sock, &pkt, peer_addr).await;

        assert!(
            pfcp_path::tsc_reports_for(seid).is_none(),
            "TMIR with no TSC IE must record nothing"
        );
        pfcp_path::clear_tsc_reports_for_test();
    }

    #[test]
    fn test_smf_config_default() {
        let config = SmfConfig::default();
        assert_eq!(config.sbi_port, 7777);
        assert_eq!(config.max_ue, 1024);
        assert!(config.nrf_uri.is_none());
    }

    #[test]
    fn test_load_config_extracts_sbi_and_nrf_in_one_parse() {
        use std::io::Write;
        let yaml = "smf:\n  sbi:\n    server:\n      - address: 127.0.0.1\n        \
                    port: 8888\n    client:\n      nrf:\n        - uri: http://nrf.example:7777\n";
        let path = std::env::temp_dir().join(format!("smf-cfg-test-{}.yaml", std::process::id()));
        std::fs::File::create(&path)
            .and_then(|mut f| f.write_all(yaml.as_bytes()))
            .expect("write temp config");

        let config = load_config(path.to_str().unwrap()).unwrap();
        let _ = std::fs::remove_file(&path);

        assert_eq!(config.sbi_addr, "127.0.0.1");
        assert_eq!(config.sbi_port, 8888);
        // NRF URI now comes from the single load_config parse (no second read).
        assert_eq!(config.nrf_uri.as_deref(), Some("http://nrf.example:7777"));
    }

    // ------------------------------------------------------------------
    // N2 SM transfer cross-codec guards (PDU-session data-plane)
    // ------------------------------------------------------------------
    //
    // The smfd builds the N2 SM PDUSessionResourceSetupRequestTransfer with the
    // real-APER nextgcore-ngap codec and decodes the gNB's SetupResponseTransfer with
    // it. These pin the wire bytes against the independent nextgsim-ngap codec
    // (the gNB), mirroring the NG-Setup/ICS reconciliation: the request
    // bytes are byte-identical to the gNB's decoder vector, and the gNB's
    // response bytes decode here.

    /// smfd's emitted SetupRequestTransfer for UPF F-TEID 0x00010001 /
    /// 10.45.0.1 / QFI 1 / 5QI 9 / ARP 8 — must equal the vector the gNB
    /// (nextgsim-ngap) decodes (capture_tests.rs::SMFD_SETUP_REQUEST_TRANSFER).
    /// Leading 0x00 = the outer extensible SEQUENCE's APER extension bit
    /// (ngap-04, TS 38.413 §9.3.4.1 + §9.5); the remaining 32 octets are the
    /// ProtocolIE-Container.
    const GNB_EXPECTED_SETUP_REQUEST: [u8; 33] = [
        0x00, 0x00, 0x03, 0x00, 0x8b, 0x00, 0x0a, 0x01, 0xf0, 0x0a, 0x2d, 0x00, 0x01, 0x00, 0x01,
        0x00, 0x01, 0x00, 0x86, 0x00, 0x01, 0x00, 0x00, 0x88, 0x00, 0x07, 0x00, 0x01, 0x00, 0x00,
        0x09, 0x1c, 0x00,
    ];

    #[test]
    fn setup_request_transfer_matches_gnb_wire_bytes() {
        let bytes =
            build_setup_request_transfer(0x0001_0001, [10, 45, 0, 1], default_flow(1, 9, 8), 0, 0)
                .unwrap();
        assert_eq!(
            bytes,
            GNB_EXPECTED_SETUP_REQUEST.to_vec(),
            "smfd SetupRequestTransfer must be byte-identical to the gNB decoder vector"
        );
    }

    #[test]
    fn setup_request_transfer_self_roundtrips() {
        use nextgcore_ngap::transfer::{
            PduSessionResourceSetupRequestTransfer, UpTransportLayerInformation,
        };
        let bytes =
            build_setup_request_transfer(0x0001_0001, [10, 45, 0, 1], default_flow(1, 9, 8), 0, 0)
                .unwrap();
        let t = PduSessionResourceSetupRequestTransfer::decode(&bytes).expect("decode");
        let UpTransportLayerInformation::GtpTunnel(tun) = &t.ul_ngu_up_tnl_information;
        assert_eq!(u32::from_be_bytes(tun.gtp_teid), 0x0001_0001);
        assert_eq!(tun.transport_layer_address.octets, vec![10, 45, 0, 1]);
        assert_eq!(t.qos_flow_setup_request_list.len(), 1);
        assert_eq!(t.qos_flow_setup_request_list[0].qos_flow_identifier, 1);
    }

    #[test]
    fn modify_request_transfer_self_roundtrips() {
        use nextgcore_ngap::transfer::PduSessionResourceModifyRequestTransfer;
        let bytes = build_modify_request_transfer(1, 200_000_000, 100_000_000).unwrap();
        let t = PduSessionResourceModifyRequestTransfer::decode(&bytes).expect("decode");
        assert_eq!(
            t.pdu_session_aggregate_maximum_bit_rate
                .map(|a| (a.dl, a.ul)),
            Some((200_000_000, 100_000_000))
        );
        assert_eq!(t.qos_flow_add_or_modify_request_list.len(), 1);
        assert_eq!(
            t.qos_flow_add_or_modify_request_list[0].qos_flow_identifier,
            1
        );
    }

    // ------------------------------------------------------------------
    // H5 golden vectors: PDUSessionResourceModifyRequestTransfer
    // (TS 38.413 §9.3.4.3, APER per ITU-T X.691, ALIGNED variant)
    // ------------------------------------------------------------------
    //
    // Hand-derived from the ASN.1 in specs/38413-j30.txt — NOT captured from
    // our own encoder — per the dual-derivation method in
    // .context/GOLDEN-VECTOR-METHOD.md. Derivation A is the bit table below;
    // derivation B is an independent from-scratch X.691 recompute (Python
    // script, full text in the method doc's Appendix B) written without
    // reading derivation A. Both derivations agree byte-for-byte; the vector
    // was frozen only after that agreement (this cross-check is what caught
    // the TUAK set-3 scramble precedent).
    //
    // ASN.1 anchors (specs/38413-j30.txt):
    //   PDUSessionResourceModifyRequestTransfer  line 53689 (extensible SEQUENCE
    //     of one mandatory ProtocolIE-Container)
    //   ProtocolIE-Container ::= SEQUENCE (SIZE (0..65535)) OF ProtocolIE-Field
    //     (line 60634; maxProtocolIEs = 65535, line 59201)
    //   ProtocolIE-Field ::= SEQUENCE { id INTEGER (0..65535),
    //     criticality ENUMERATED {reject,ignore,notify}, value <open type> }
    //   id-PDUSessionAggregateMaximumBitRate = 130, criticality reject (59691)
    //   id-QosFlowAddOrModifyRequestList     = 135, criticality reject (59701)
    //   PDUSessionAggregateMaximumBitRate ::= SEQUENCE { DL BitRate, UL BitRate,
    //     iE-Extensions OPTIONAL, ... } (53236)
    //   BitRate ::= INTEGER (0..4000000000000, ...) (45660)
    //   QosFlowAddOrModifyRequestList ::= SEQUENCE (SIZE(1..64)) OF ... (55098;
    //     maxnoofQosFlows = 64, line 59309)
    //   QosFlowAddOrModifyRequestItem ::= SEQUENCE { qosFlowIdentifier
    //     INTEGER (0..63,...), qosFlowLevelQosParameters OPTIONAL,
    //     e-RAB-ID OPTIONAL, iE-Extensions OPTIONAL, ... } (55101)

    /// Golden vector A — AMBR-only transfer (DL 1 Gbps, UL 250 kbps).
    ///
    /// Derivation A bit table (X.691 ALIGNED; bits listed in emission order):
    /// ```text
    /// byte 0     0x00  [0]        outer SEQUENCE extension bit = 0 (X.691 §19.7)
    ///                  [0000000]  pad: container count is a range-65536
    ///                             constrained int -> 2 octets, octet-aligned
    ///                             (§13.2.5.4 via §11.9.4.1)
    /// bytes 1-2  0x0001           protocolIEs count = 1
    /// bytes 3-4  0x0082           ProtocolIE-ID 130 (range 65536 -> 2 aligned octets)
    /// byte 5     0x00  [00]       criticality reject = 0 (ENUMERATED root,
    ///                             range 3 -> 2-bit field, §14.3/§13.2.5.2)
    ///                  [000000]   pad: open-type length determinant aligns (§11.2/§11.9)
    /// byte 6     0x09             open-type length = 9 octets (short form, §11.9.3.6)
    /// --- open-type content: PDUSessionAggregateMaximumBitRate ---
    /// byte 7     0x0C  [0]        AMBR SEQUENCE extension bit = 0
    ///                  [0]        iE-Extensions absent (1-bit optional bitmap, §19.2)
    ///                  [0]        DL BitRate extension bit = 0 (root, §13.1)
    ///                  [011]      DL length-of-length: range 4e12+1 > 64K ->
    ///                             §13.2.6: octet count n=4 as constrained int
    ///                             (1..6) -> 3-bit field, offset 4-1=3
    ///                  [00]       pad: §13.2.6 value octets are octet-aligned
    /// bytes 8-11 0x3B9ACA00       DL = 1_000_000_000 in minimal 4 octets
    /// byte 12    0x20  [0]        UL BitRate extension bit = 0
    ///                  [010]      UL octet count n=3, offset 3-1=2
    ///                  [0000]     pad to octet boundary
    /// bytes13-15 0x03D090         UL = 250_000 in minimal 3 octets
    /// ```
    const GOLDEN_MODIFY_REQUEST_AMBR_ONLY: [u8; 16] = [
        0x00, 0x00, 0x01, 0x00, 0x82, 0x00, 0x09, 0x0C, 0x3B, 0x9A, 0xCA, 0x00, 0x20, 0x03, 0xD0,
        0x90,
    ];

    /// Golden vector B — AMBR (DL 200 Mbps, UL 100 Mbps) + one QoS-flow-add
    /// item (QFI 1, no level parameters, no E-RAB ID) — exactly the shape
    /// `build_modify_request_transfer(1, 200_000_000, 100_000_000)` emits on
    /// the live PDU_RES_MOD_REQ path.
    ///
    /// Derivation A bit table (deltas from vector A annotated):
    /// ```text
    /// byte 0     0x00             ext bit 0 + 7 pad bits (as vector A)
    /// bytes 1-2  0x0002           protocolIEs count = 2
    /// bytes 3-4  0x0082           IE 1: ProtocolIE-ID 130 (AMBR)
    /// byte 5     0x00             criticality reject (2 bits) + 6 pad bits
    /// byte 6     0x0A             open-type length = 10 octets
    /// byte 7     0x0C             [0 ext][0 iE-Ext absent][0 DL ext][011 n=4][00 pad]
    /// bytes 8-11 0x0BEBC200       DL = 200_000_000 in minimal 4 octets
    /// byte 12    0x30             [0 UL ext][011 n=4][0000 pad]
    /// bytes13-16 0x05F5E100       UL = 100_000_000 in minimal 4 octets
    /// bytes17-18 0x0087           IE 2: ProtocolIE-ID 135 (QosFlowAddOrModifyRequestList)
    /// byte 19    0x00             criticality reject (2 bits) + 6 pad bits
    /// byte 20    0x03             open-type length = 3 octets
    /// --- open-type content: QosFlowAddOrModifyRequestList, 17 bits + 7 pad ---
    /// byte 21    0x00  [000000]   SEQUENCE-OF count = 1 as constrained int
    ///                             (1..64) -> 6-bit field, offset 0 (§20.6)
    ///                  [0]        item SEQUENCE extension bit = 0
    ///                  [0]        qosFlowLevelQosParameters absent
    /// byte 22    0x00  [0]        e-RAB-ID absent
    ///                  [0]        iE-Extensions absent
    ///                  [0]        QosFlowIdentifier extension bit = 0
    ///                  [00000]    QFI high 5 bits of 6-bit root value 1 (0..63)
    /// byte 23    0x80  [1]        QFI low bit (value = 0b000001 = 1)
    ///                  [0000000]  pad to octet boundary (§11.2.1)
    /// ```
    const GOLDEN_MODIFY_REQUEST_AMBR_PLUS_QOS_FLOW_ADD: [u8; 24] = [
        0x00, 0x00, 0x02, 0x00, 0x82, 0x00, 0x0A, 0x0C, 0x0B, 0xEB, 0xC2, 0x00, 0x30, 0x05, 0xF5,
        0xE1, 0x00, 0x00, 0x87, 0x00, 0x03, 0x00, 0x00, 0x80,
    ];

    /// Encoder golden A: an AMBR-only ModifyRequestTransfer (the transfer
    /// codec `build_modify_request_transfer` drives; the builder itself always
    /// adds the QoS-flow list, so the AMBR-only shape is pinned through the
    /// same encoder directly) must produce the spec-derived bytes exactly.
    #[test]
    fn golden_modify_request_transfer_ambr_only_encodes_ts38413_bytes() {
        assert_eq!(
            n2_transfer::modify_request_transfer(Some((1_000_000_000, 250_000)), &[])
                .expect("encode"),
            GOLDEN_MODIFY_REQUEST_AMBR_ONLY.to_vec(),
            "AMBR-only ModifyRequestTransfer must match the hand-derived TS 38.413 APER vector"
        );
    }

    /// Encoder golden B: the live builder's exact output (AMBR + one
    /// QoS-flow-add item) must equal the spec-derived bytes. This replaces the
    /// roundtrip-only oracle for encode-side drift: any bit change in the
    /// encoder output fails here even if the matched decoder still accepts it.
    #[test]
    fn golden_modify_request_transfer_builder_encodes_ts38413_bytes() {
        let bytes = build_modify_request_transfer(1, 200_000_000, 100_000_000).unwrap();
        assert_eq!(
            bytes,
            GOLDEN_MODIFY_REQUEST_AMBR_PLUS_QOS_FLOW_ADD.to_vec(),
            "build_modify_request_transfer must match the hand-derived TS 38.413 APER vector"
        );
    }

    /// Decoder golden: the frozen spec-derived bytes must decode into exactly
    /// the expected structs (guards decoder drift independently of encoder
    /// drift — a symmetric codec bug passes the roundtrip but fails here).
    #[test]
    fn golden_modify_request_transfer_decodes_from_frozen_bytes() {
        use g::PDUSessionResourceModifyRequestTransferProtocolIEs_EntryValue as Ie;
        use nextgcore_ngap_gen::generated as g;
        let decode = |bytes: &[u8]| {
            nextgcore_ngap_gen::decode_contained::<g::PDUSessionResourceModifyRequestTransfer>(
                bytes,
            )
            .expect("decode golden")
            .protocol_i_es
            .0
            .into_iter()
            .map(|ie| (ie.id.0, ie.criticality.0, ie.value))
            .collect::<Vec<_>>()
        };
        let ambr = |dl, ul| g::PDUSessionAggregateMaximumBitRate {
            pdu_session_aggregate_maximum_bit_rate_dl: g::BitRate(dl),
            pdu_session_aggregate_maximum_bit_rate_ul: g::BitRate(ul),
            ie_extensions: None,
        };
        let reject = g::Criticality::REJECT;

        assert_eq!(
            decode(&GOLDEN_MODIFY_REQUEST_AMBR_ONLY),
            vec![(
                130,
                reject,
                Ie::Id_PDUSessionAggregateMaximumBitRate(ambr(1_000_000_000, 250_000))
            )]
        );
        assert_eq!(
            decode(&GOLDEN_MODIFY_REQUEST_AMBR_PLUS_QOS_FLOW_ADD),
            vec![
                (
                    130,
                    reject,
                    Ie::Id_PDUSessionAggregateMaximumBitRate(ambr(200_000_000, 100_000_000))
                ),
                (
                    135,
                    reject,
                    Ie::Id_QosFlowAddOrModifyRequestList(g::QosFlowAddOrModifyRequestList(vec![
                        g::QosFlowAddOrModifyRequestItem {
                            qos_flow_identifier: g::QosFlowIdentifier(1),
                            qos_flow_level_qos_parameters: None,
                            e_rab_id: None,
                            ie_extensions: None,
                        }
                    ]))
                ),
            ]
        );
    }

    /// The gNB (nextgsim-ngap) produces this SetupResponseTransfer for gNB DL
    /// F-TEID 0x00020002 / 10.46.0.1 / QFI 1 (pinned in the gNB test
    /// capture_tests.rs::gnb_setup_response_transfer_roundtrips). smfd must
    /// decode it to extract the gNB DL F-TEID for the PFCP DL FAR.
    const GNB_SETUP_RESPONSE_TRANSFER: [u8; 13] = [
        0x00, 0x03, 0xe0, 0x0a, 0x2e, 0x00, 0x01, 0x00, 0x02, 0x00, 0x02, 0x00, 0x01,
    ];

    #[test]
    fn gnb_setup_response_transfer_decodes_in_smfd() {
        let (teid, addr, qfi) =
            decode_setup_response_dl_endpoint(&GNB_SETUP_RESPONSE_TRANSFER).expect("smfd decodes");
        assert_eq!(teid, 0x0002_0002);
        assert_eq!(addr, [10, 46, 0, 1]);
        assert_eq!(qfi, 1);
    }

    // ------------------------------------------------------------------
    // smfd-01 / smfd-02: multipart/related N1/N2 carriage
    // (TS 29.502 §6.1.2.2.2 / §6.1.2.4)
    // ------------------------------------------------------------------

    use nextgcore_sbi::constants::content_type;
    use nextgcore_sbi::message::SbiPart;

    /// A valid PDU Session Establishment Request N1 container (PSI=5, PTI=2,
    /// IPv4v6, SSC mode 2) — the vector parsed in the policy unit tests.
    const N1_ESTABLISHMENT_REQUEST: [u8; 14] = [
        0x2E, 0x05, 0x02, 0xC1, 0xFF, 0xFF, 0x93, 0xA2, 0x28, 0x01, 0x00, 0x55, 0x00, 0x10,
    ];

    /// The 201 SmContextCreatedData response is multipart/related: the JSON
    /// root references N1/N2 via RefToBinaryData, and the two binary parts carry
    /// the exact bytes produced by smfd's N1-accept and N2-transfer builders,
    /// with the conformant 5gnas / ngap content types.
    #[test]
    fn sm_context_created_response_is_multipart_with_binary_refs() {
        let n1 = policy::build_establishment_accept(
            5,
            2,
            policy::pdu_session_type::IPV4,
            1,
            1,
            1,
            1_000_000,
            1_000_000,
            [10, 45, 0, 2],
            [0u8; 8],
            1,
            None,
            "internet",
            None,
            &[],
            None,
            None,
        );
        let n2 =
            build_setup_request_transfer(0x0001_0001, [10, 45, 0, 1], default_flow(1, 9, 8), 0, 0)
                .unwrap();

        let resp = sbi_response_with_n1_n2(
            201,
            serde_json::json!({
                "smContextRef": "7",
                "pduSessionId": 5,
                "upCnxState": "ACTIVATING",
                "n2SmInfoType": "PDU_RES_SETUP_REQ"
            }),
            &n1,
            &n2,
        )
        .with_header("Location", "/nsmf-pdusession/v1/sm-contexts/7");

        assert_eq!(resp.status, 201);
        // Serialize exactly as the SBI client serializes parts (multipart/
        // related), then decode it back to prove the wire shape.
        let boundary = nextgcore_sbi::multipart::generate_boundary();
        let body = nextgcore_sbi::multipart::encode(
            resp.http.content.as_deref(),
            &resp.http.parts,
            &boundary,
        );
        let ct = nextgcore_sbi::multipart::content_type_with_boundary(&boundary);
        let decoded = nextgcore_sbi::multipart::decode(&ct, &body).expect("decode multipart");

        // JSON root: N1/N2 are RefToBinaryData pointers; n2SmInfoType preserved.
        let root: serde_json::Value =
            serde_json::from_str(decoded.json.as_deref().unwrap()).unwrap();
        assert_eq!(root["n1SmMsg"]["contentId"].as_str(), Some("n1SmMsg"));
        assert_eq!(root["n2SmInfo"]["contentId"].as_str(), Some("n2SmInfo"));
        assert_eq!(root["n2SmInfoType"].as_str(), Some("PDU_RES_SETUP_REQ"));
        assert_eq!(root["smContextRef"].as_str(), Some("7"));

        // Binary parts: exact builder bytes + conformant content types.
        let n1_part = decoded
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n1SmMsg"))
            .expect("n1 part");
        let n2_part = decoded
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n2SmInfo"))
            .expect("n2 part");
        assert_eq!(n1_part.data.as_ref(), n1.as_slice());
        assert_eq!(n2_part.data.as_ref(), n2.as_slice());
        assert_eq!(
            n1_part.content_type.as_deref(),
            Some(content_type::APPLICATION_5GNAS)
        );
        assert_eq!(
            n2_part.content_type.as_deref(),
            Some(content_type::APPLICATION_NGAP)
        );
    }

    /// The N1-bearing reject (SmContextCreateError) carries the PDU Session
    /// Establishment Reject as a 5gnas binary part referenced by RefToBinaryData.
    #[test]
    fn sm_context_create_error_carries_n1_reject_part() {
        let resp = sm_context_create_error(
            403,
            "PDUTYPE_NOT_SUPPORTED",
            5,
            2,
            50,
            policy::RejectTo::default(),
        );
        assert_eq!(resp.status, 403);
        let root: serde_json::Value =
            serde_json::from_str(resp.http.content.as_deref().unwrap()).unwrap();
        assert_eq!(root["n1SmMsg"]["contentId"].as_str(), Some("n1SmMsg"));
        let part = resp
            .http
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n1SmMsg"))
            .expect("n1 reject part");
        assert_eq!(
            part.content_type.as_deref(),
            Some(content_type::APPLICATION_5GNAS)
        );
        assert_eq!(
            part.data.as_ref(),
            policy::build_establishment_reject(5, 2, 50).as_slice()
        );
    }

    /// smfd resolves the N1 container identically from a multipart 5gnas part
    /// and from the legacy base64-in-JSON form (backward compatibility).
    #[test]
    fn smfd_resolves_n1_multipart_same_as_base64() {
        // Multipart form: JSON root holds a RefToBinaryData pointer; bytes in a part.
        let mut multipart_req = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts");
        multipart_req
            .http
            .set_content(serde_json::json!({ "n1SmMsg": { "contentId": "n1SmMsg" } }).to_string());
        multipart_req.http.add_part(SbiPart::with_content(
            "n1SmMsg",
            content_type::APPLICATION_5GNAS,
            bytes::Bytes::copy_from_slice(&N1_ESTABLISHMENT_REQUEST),
        ));
        let mp_body: serde_json::Value =
            serde_json::from_str(multipart_req.http.content.as_deref().unwrap()).unwrap();
        let from_multipart = resolve_binary_ref(&multipart_req, &mp_body["n1SmMsg"]).unwrap();

        // Legacy form: base64 string, no parts.
        use base64::Engine;
        let b64 = base64::engine::general_purpose::STANDARD.encode(N1_ESTABLISHMENT_REQUEST);
        let legacy_req = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts");
        let legacy_body = serde_json::json!({ "n1SmMsg": b64 });
        let from_base64 = resolve_binary_ref(&legacy_req, &legacy_body["n1SmMsg"]).unwrap();

        assert_eq!(from_multipart, from_base64);
        assert_eq!(from_multipart, N1_ESTABLISHMENT_REQUEST.to_vec());
        // ...and the decoded internal result is identical.
        let a = policy::parse_establishment_request(&from_multipart).unwrap();
        let b = policy::parse_establishment_request(&from_base64).unwrap();
        assert_eq!(a.pti, b.pti);
        assert_eq!(a.requested_pdu_session_type, b.requested_pdu_session_type);
        assert_eq!(a.requested_ssc_mode, b.requested_ssc_mode);
    }

    /// Cross-decode: bytes shaped exactly as amfd emits a multipart
    /// CreateSmContext request (JSON root + N1 5gnas part) are decoded by the
    /// shared multipart codec and resolved by smfd to the exact N1 container.
    #[test]
    fn smfd_parses_amfd_multipart_create_request() {
        // Reproduce amfd's wire emission via the shared multipart encoder.
        let root = serde_json::json!({
            "pduSessionId": 5,
            "sNssai": { "sst": 1 },
            "dnn": "internet",
            "n1SmMsg": { "contentId": "n1SmMsg" },
            "redcapIndication": false
        });
        let part = SbiPart::with_content(
            "n1SmMsg",
            content_type::APPLICATION_5GNAS,
            bytes::Bytes::copy_from_slice(&N1_ESTABLISHMENT_REQUEST),
        );
        let boundary = nextgcore_sbi::multipart::generate_boundary();
        let body = nextgcore_sbi::multipart::encode(
            Some(&root.to_string()),
            std::slice::from_ref(&part),
            &boundary,
        );
        let ct = nextgcore_sbi::multipart::content_type_with_boundary(&boundary);

        // Server-side: decode into the request the smfd handler would see.
        let decoded = nextgcore_sbi::multipart::decode(&ct, &body).unwrap();
        let mut request = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts");
        request.http.content = decoded.json.clone();
        request.http.parts = decoded.parts;
        let req_body: serde_json::Value =
            serde_json::from_str(decoded.json.as_deref().unwrap()).unwrap();

        let n1 = resolve_binary_ref(&request, &req_body["n1SmMsg"]).unwrap();
        assert_eq!(n1, N1_ESTABLISHMENT_REQUEST.to_vec());
        assert!(policy::parse_establishment_request(&n1).is_some());
    }

    // ------------------------- issue #73 --------------------------------

    /// **Issue #73, criterion 3.** A non-emergency `CreateSMContext` with no
    /// `supi` is REJECTED, not served with a fabricated subscriber.
    ///
    /// This used to warn and substitute `"imsi-unknown"`, and the phantom identity
    /// then flowed into NSAC counters, policy association and session lookup — so
    /// every subscriber in the network collapsed onto ONE identity. Charging and
    /// slice admission were computed over a subscriber that does not exist, and
    /// because the session still came up, nothing surfaced the loss.
    ///
    /// Asserted on BEHAVIOUR (the 400 and its cause), not by grepping the source
    /// for `imsi-unknown`: the explanation of this fix contains that literal, and
    /// a source-grepping guard would match its own justification.
    #[tokio::test]
    async fn create_sm_context_without_supi_is_rejected() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let body = serde_json::json!({
            "pduSessionId": 5,
            "sNssai": { "sst": 1, "sd": "010203" },
            "dnn": "internet",
            "n1SmMsg": { "contentId": "n1SmMsg" },
        });
        let mut request = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts");
        request.http.content = Some(body.to_string());

        let resp = handle_sm_context_create(&request).await;
        assert_eq!(
            resp.status, 400,
            "a session the SMF cannot attribute must be refused"
        );
        // #1097, TS 29.502 Table 6.1.3.2.3.1-3: an SmContextCreateError, with the
        // ProblemDetails in "error", as application/json.
        assert_eq!(
            resp.http.get_header("Content-Type").map(String::as_str),
            Some(nextgcore_sbi::constants::content_type::APPLICATION_JSON)
        );
        let body: serde_json::Value =
            serde_json::from_str(resp.http.content.as_deref().unwrap()).unwrap();
        let problem = &body["error"];
        assert_eq!(problem["cause"], "MANDATORY_IE_MISSING");
        assert_eq!(problem["status"], 400);
        assert!(
            problem["detail"]
                .as_str()
                .unwrap_or_default()
                .contains("supi"),
            "the rejection must name the missing IE, got {problem}"
        );

        // An empty string is not an identity either.
        let mut empty = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts");
        let mut with_empty = body.clone();
        with_empty["supi"] = serde_json::json!("");
        empty.http.content = Some(with_empty.to_string());
        assert_eq!(handle_sm_context_create(&empty).await.status, 400);
    }

    // ----------------------------- smfd-06 ------------------------------

    /// The exact SmContextCreateData body the matched-sim AMF sends (no supi /
    /// anType / smContextStatusUri) MUST still pass the strict validator, while
    /// genuinely-missing mandatory IEs are rejected with the correct cause.
    #[test]
    fn validate_sm_context_create_data_table() {
        // Matched-sim AMF body shape (see amfd build_create_sm_context_request).
        let matched_sim = serde_json::json!({
            "pduSessionId": 5,
            "sNssai": { "sst": 1, "sd": "010203" },
            "dnn": "internet",
            "n1SmMsg": { "contentId": "n1SmMsg" },
            "redcapIndication": false,
            "servingNetwork": { "mcc": "001", "mnc": "01" }
        });
        assert_eq!(validate_sm_context_create_data(&matched_sim), None);

        // supi / anType absent but otherwise complete → still permitted.
        assert_eq!(
            validate_sm_context_create_data(&serde_json::json!({
                "pduSessionId": 1,
                "sNssai": { "sst": 2 },
                "dnn": "ims",
                "n1SmMsg": "BASE64DATA"
            })),
            None
        );

        // Each genuinely-missing mandatory IE → its expected cause.
        let mut no_psi = matched_sim.clone();
        no_psi["pduSessionId"] = serde_json::json!(0); // out of 1..=15
        assert_eq!(
            validate_sm_context_create_data(&no_psi),
            Some("MANDATORY_IE_INCORRECT")
        );

        // #204: `dnn` is OPTIONAL (TS 29.502 Table 6.1.6.2.2-1), so its absence is
        // NOT a validator failure — the handler resolves the subscribed default
        // instead (TS 23.501 §5.6.1). Rejecting here would make that unreachable.
        let mut no_dnn = matched_sim.clone();
        no_dnn["dnn"] = serde_json::Value::Null;
        assert_eq!(
            validate_sm_context_create_data(&no_dnn),
            None,
            "an absent dnn must reach the handler, which resolves the subscribed default"
        );
        let mut absent_dnn = matched_sim.clone();
        absent_dnn.as_object_mut().unwrap().remove("dnn");
        assert_eq!(validate_sm_context_create_data(&absent_dnn), None);

        let mut no_sst = matched_sim.clone();
        no_sst["sNssai"] = serde_json::json!({});
        assert_eq!(
            validate_sm_context_create_data(&no_sst),
            Some("MANDATORY_IE_MISSING")
        );

        let mut no_n1 = matched_sim.clone();
        no_n1["n1SmMsg"] = serde_json::Value::Null;
        assert_eq!(
            validate_sm_context_create_data(&no_n1),
            Some("MANDATORY_IE_MISSING")
        );
    }

    // ------------------------------- #204 -------------------------------

    /// **Issue #204.** The subscribed default DNN is selected from
    /// `SmfSelectionSubscriptionData`'s `dnnInfos`, and nothing is invented when
    /// the subscription does not say which DNN is the default.
    ///
    /// Note where the flag lives: `DnnInfo.defaultDnnIndicator` in `smf-sel-data`.
    /// The issue's suggested approach said to read `sm-data`'s `dnnConfigurations`,
    /// which has **no** default flag at all (TS 29.503 Table 5.5.2.4-1) — see the
    /// `select_default_dnn` doc comment.
    #[test]
    fn select_default_dnn_uses_the_indicator_and_refuses_to_guess() {
        // 1. The flagged entry wins, even when it is not first.
        let flagged = serde_json::json!({
            "subscribedSnssaiInfos": {
                "01": { "dnnInfos": [
                    { "dnn": "ims" },
                    { "dnn": "operator-default", "defaultDnnIndicator": true },
                    { "dnn": "internet" },
                ]}
            }
        });
        assert_eq!(
            select_default_dnn(&flagged, 1, None),
            Ok("operator-default".to_string()),
            "the flagged DNN wins over position"
        );
        // Specifically NOT the literal the AMF used to substitute, which is the
        // whole point of #204.
        assert_ne!(select_default_dnn(&flagged, 1, None), Ok("internet".into()));

        // 2. A single subscribed DNN with no flag is unambiguous.
        let single = serde_json::json!({
            "subscribedSnssaiInfos": { "01": { "dnnInfos": [{ "dnn": "corp" }] } }
        });
        assert_eq!(select_default_dnn(&single, 1, None), Ok("corp".to_string()));

        // 3. Several DNNs and no flag: the subscription does not say, so the SMF
        //    does not either. Guessing is the fabrication this issue removes.
        let ambiguous = serde_json::json!({
            "subscribedSnssaiInfos": {
                "01": { "dnnInfos": [{ "dnn": "internet" }, { "dnn": "ims" }] }
            }
        });
        match select_default_dnn(&ambiguous, 1, None) {
            Err(DefaultDnnError::AmbiguousDefault(dnns)) => {
                assert_eq!(dnns, vec!["internet".to_string(), "ims".to_string()]);
            }
            other => panic!("expected AmbiguousDefault, got {other:?}"),
        }

        // 4. No DNN at all for the S-NSSAI, and an S-NSSAI that is not subscribed.
        for empty in [
            serde_json::json!({}),
            serde_json::json!({ "subscribedSnssaiInfos": {} }),
            serde_json::json!({ "subscribedSnssaiInfos": { "01": {} } }),
            serde_json::json!({ "subscribedSnssaiInfos": { "01": { "dnnInfos": [] } } }),
            // A dnnInfos entry with no `dnn` member names nothing.
            serde_json::json!({ "subscribedSnssaiInfos": { "01": { "dnnInfos": [{}] } } }),
        ] {
            assert_eq!(
                select_default_dnn(&empty, 1, None),
                Err(DefaultDnnError::NoSubscribedDnn),
                "body {empty} must not yield a DNN"
            );
        }
        assert_eq!(
            select_default_dnn(&single, 9, None),
            Err(DefaultDnnError::NoSubscribedDnn),
            "SST 9 is not subscribed"
        );

        // 5. The key form is the TS 29.571 S-NSSAI string `{sst:02x}[-{sd}]`, and a
        //    subscription provisioned without an SD still applies to a request that
        //    carries one.
        let with_sd = serde_json::json!({
            "subscribedSnssaiInfos": {
                "01-000001": { "dnnInfos": [{ "dnn": "slice-a" }] },
                "01": { "dnnInfos": [{ "dnn": "no-sd" }] }
            }
        });
        assert_eq!(
            select_default_dnn(&with_sd, 1, Some("000001")),
            Ok("slice-a".to_string()),
            "the exact sst-sd key wins"
        );
        assert_eq!(
            select_default_dnn(&with_sd, 1, Some("999999")),
            Ok("no-sd".to_string()),
            "an unmatched SD widens to the no-SD entry"
        );
    }

    /// **Issue #204.** Every `DefaultDnnError` maps to a cause that distinguishes
    /// "the consumer named no DNN and the subscription supplies none" from "the SMF
    /// could not reach the subscription".
    ///
    /// Collapsing them would leave an operator unable to tell a provisioning gap
    /// from an unreachable UDM, which are opposite remedies.
    #[test]
    fn default_dnn_error_causes_are_distinct_and_never_silent() {
        assert_eq!(
            DefaultDnnError::NoSubscribedDnn.cause(),
            "MANDATORY_IE_MISSING"
        );
        assert_eq!(
            DefaultDnnError::AmbiguousDefault(vec!["a".into(), "b".into()]).cause(),
            "MANDATORY_IE_MISSING"
        );
        assert_eq!(
            (
                DefaultDnnError::NoUdmEndpoint.cause(),
                DefaultDnnError::NoUdmEndpoint.status()
            ),
            ("SYSTEM_FAILURE", 500)
        );
        let failed = DefaultDnnError::SdmRequestFailed("boom".into());
        assert_eq!(
            (failed.cause(), failed.status()),
            ("PEER_NOT_RESPONDING", 504)
        );
        let refused = DefaultDnnError::SdmAnswerUnusable("status 503".into());
        assert_eq!((refused.cause(), refused.status()), ("SYSTEM_FAILURE", 500));
        assert_eq!(DefaultDnnError::NoSubscribedDnn.status(), 400);

        // Every detail says which failure it was, and none of them says "internet".
        for e in [
            DefaultDnnError::NoUdmEndpoint,
            DefaultDnnError::SdmRequestFailed("status 503".into()),
            DefaultDnnError::NoSubscribedDnn,
            DefaultDnnError::AmbiguousDefault(vec!["internet".into(), "ims".into()]),
        ] {
            let detail = e.detail();
            assert!(!detail.is_empty());
            assert!(
                detail.contains("dnn") || detail.contains("DNN"),
                "detail must name the DNN problem: {detail}"
            );
        }
        assert!(
            DefaultDnnError::AmbiguousDefault(vec!["internet".into(), "ims".into()])
                .detail()
                .contains("internet, ims")
        );
    }

    /// **Issue #204.** A `nudm-sdm` endpoint is taken from the NRF `SearchResult`,
    /// preferring the service's own `ipEndPoints` over the instance address.
    #[test]
    fn udm_sdm_endpoint_is_read_from_the_search_result() {
        let result = serde_json::json!({
            "nfInstances": [
                // A UDM that does not serve nudm-sdm must be skipped, not used.
                { "nfType": "UDM", "ipv4Addresses": ["10.0.0.1"],
                  "nfServices": [{ "serviceName": "nudm-uecm",
                                   "ipEndPoints": [{ "ipv4Address": "10.0.0.1", "port": 7777 }] }] },
                { "nfType": "UDM", "ipv4Addresses": ["10.0.0.2"],
                  "nfServices": [{ "serviceName": "nudm-sdm",
                                   "ipEndPoints": [{ "ipv4Address": "10.0.0.9", "port": 8080 }] }] },
            ]
        });
        assert_eq!(
            udm_service_endpoint_from_search_result(&result, "nudm-sdm"),
            Some(("10.0.0.9".to_string(), 8080)),
            "the nudm-sdm service's own endpoint wins over the instance address"
        );

        // No ipEndPoints: fall back to the instance address and the default port.
        let no_endpoints = serde_json::json!({
            "nfInstances": [{ "nfType": "UDM", "ipv4Addresses": ["10.0.0.3"],
                              "nfServices": [{ "serviceName": "nudm-sdm" }] }]
        });
        assert_eq!(
            udm_service_endpoint_from_search_result(&no_endpoints, "nudm-sdm"),
            Some(("10.0.0.3".to_string(), 7777))
        );

        // Nothing usable yields None rather than a guessed localhost.
        for empty in [
            serde_json::json!({}),
            serde_json::json!({ "nfInstances": [] }),
            serde_json::json!({ "nfInstances": [{ "nfType": "UDM" }] }),
            serde_json::json!({ "nfInstances": [{ "nfType": "UDM",
                "nfServices": [{ "serviceName": "nudm-uecm" }] }] }),
        ] {
            assert_eq!(
                udm_service_endpoint_from_search_result(&empty, "nudm-sdm"),
                None,
                "body {empty} must not yield an endpoint"
            );
        }
    }

    /// **Issue #204, end to end.** `fetch_subscribed_default_dnn` really reaches a
    /// UDM, sends a conformant `Nudm_SDM_Get smf-select-data` with a
    /// percent-encoded `single-nssai`, and returns the flagged DNN.
    ///
    /// The pure-function test above proves the SELECTION; this proves the request
    /// and the plumbing around it, which is the half a unit test cannot see.
    /// #749: the 409 `HIGHER_PRIORITY_REQUEST_ONGOING` an AMF answers while it is
    /// paging the UE for another transfer is recognised with its `retryAfter`
    /// (capped), and nothing else is.
    #[test]
    fn a_paging_conflict_is_recognised_with_its_retry_after() {
        let refusal = |status: u16, body: serde_json::Value| {
            SbiResponse::with_status(status)
                .with_json_body(&body)
                .unwrap()
        };
        let conflict = serde_json::json!({
            "error": { "status": 409, "cause": "HIGHER_PRIORITY_REQUEST_ONGOING" },
            "errInfo": { "retryAfter": 3 },
        });
        assert_eq!(
            n1n2_paging_conflict_retry_after(&refusal(409, conflict)),
            Some(std::time::Duration::from_secs(3))
        );
        let unnamed = serde_json::json!({
            "error": { "status": 409, "cause": "HIGHER_PRIORITY_REQUEST_ONGOING" },
        });
        assert_eq!(
            n1n2_paging_conflict_retry_after(&refusal(409, unnamed)),
            Some(std::time::Duration::from_secs(N1N2_RETRY_AFTER_DEFAULT_S))
        );
        let huge = serde_json::json!({
            "error": { "cause": "HIGHER_PRIORITY_REQUEST_ONGOING" },
            "errInfo": { "retryAfter": 3600 },
        });
        // #1079 review m2: the value is taken in full, never capped to a shorter
        // wait; whether it is waited out is the retry loop's decision.
        assert_eq!(
            n1n2_paging_conflict_retry_after(&refusal(409, huge)),
            Some(std::time::Duration::from_secs(3600))
        );
        let other = serde_json::json!({
            "error": { "cause": "TEMPORARY_REJECT_HANDOVER_ONGOING" },
        });
        assert_eq!(n1n2_paging_conflict_retry_after(&refusal(409, other)), None);
        assert_eq!(
            n1n2_paging_conflict_retry_after(&refusal(202, serde_json::json!({}))),
            None
        );
    }

    /// #749: a downlink-data N1N2MessageTransfer the AMF refuses because it is
    /// paging the UE for another session is sent again after the `retryAfter`,
    /// so this session's re-activation is not lost (TS 29.518 §5.2.2.3.1).
    #[tokio::test]
    async fn a_paging_request_refused_while_the_amf_pages_is_retried() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sm_ref = held_session_for_retry("imsi-001010007490031", 1);
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let (port_listener, port_addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let seen = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let seen_in_handler = Arc::clone(&seen);
        let server = nextgcore_sbi::server::SbiServer::on_listener(
            nextgcore_sbi::server::SbiServerConfig::new(port_addr),
            port_listener,
        );
        server
            .start(move |_req: SbiRequest| {
                let seen = Arc::clone(&seen_in_handler);
                async move {
                    // The first answer is the conflict, then the AMF accepts.
                    if seen.fetch_add(1, std::sync::atomic::Ordering::SeqCst) == 0 {
                        SbiResponse::with_status(409)
                            .with_json_body(&serde_json::json!({
                                "error": { "status": 409, "cause": "HIGHER_PRIORITY_REQUEST_ONGOING" },
                                "errInfo": { "retryAfter": 1 },
                            }))
                            .unwrap()
                    } else {
                        SbiResponse::with_status(202)
                            .with_json_body(&serde_json::json!({ "cause": "ATTEMPTING_TO_REACH_UE" }))
                            .unwrap()
                    }
                }
            })
            .await
            .expect("stand-in AMF starts");
        let started = std::time::Instant::now();
        send_n1_n2_paging_request(
            &format!("http://127.0.0.1:{}", port_addr.port()),
            "imsi-001010007490031",
            1,
            None,
            &sm_ref,
            PagingStart::Report,
        )
        .await;
        // #1079 review: the caller (the N4 loop) is not held for the retry.
        assert_eq!(seen.load(std::sync::atomic::Ordering::SeqCst), 1);
        assert!(started.elapsed() < std::time::Duration::from_secs(1));
        for _ in 0..200 {
            if seen.load(std::sync::atomic::Ordering::SeqCst) == 2 {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        assert_eq!(
            seen.load(std::sync::atomic::Ordering::SeqCst),
            2,
            "refused once, sent again off the caller's task"
        );
        drop_session_for_retry(&sm_ref);
    }

    /// A session held at the SMF for the #749 retry tests; returns its SM context ref.
    fn held_session_for_retry(supi: &str, psi: u8) -> String {
        smf_context_init(64, 256, 512);
        let ctx = smf_self();
        let context = ctx.read().expect("context");
        let ue = context.ue_add_by_supi(supi).expect("ue");
        let sm_ref = context
            .sess_add_by_psi(ue.id, psi)
            .and_then(|s| s.sm_context_ref)
            .expect("session");
        // #1162 review M1: a session with no transfer to send is not paged at all.
        context
            .upf_ul_endpoints
            .write()
            .expect("w")
            .insert(sm_ref.clone(), (0x0074_9000, [10, 45, 74, 90]));
        let mut b = context::PolicyBinding::snapshot_default();
        b.supi = supi.to_string();
        b.qfi = 1;
        b.five_qi = 9;
        b.arp_priority_level = 8;
        b.ambr_dl_bps = 1_000_000;
        b.ambr_ul_bps = 1_000_000;
        context
            .policy_bindings
            .write()
            .expect("w")
            .insert(sm_ref.clone(), b);
        sm_ref
    }

    fn drop_session_for_retry(sm_ref: &str) {
        let ctx = smf_self();
        let context = ctx.read().expect("context");
        if let Some(sess) = context.sess_find_by_sm_context_ref(sm_ref) {
            context.sess_remove(sess.id);
            // The UE goes too: the context holds a bounded number of UEs, which
            // other tests share.
            context.ue_remove(sess.smf_ue_id);
        }
        context.upf_ul_endpoints.write().expect("w").remove(sm_ref);
        context.policy_bindings.write().expect("w").remove(sm_ref);
    }

    /// A stand-in AMF that refuses every N1N2MessageTransfer with 409
    /// `HIGHER_PRIORITY_REQUEST_ONGOING` and `retryAfter` = `retry_after` s, counting
    /// the requests.
    async fn always_paging_amf(
        retry_after: u64,
    ) -> (
        nextgcore_sbi::server::SbiServer,
        u16,
        Arc<std::sync::atomic::AtomicUsize>,
    ) {
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let seen = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let counter = Arc::clone(&seen);
        let server = nextgcore_sbi::server::SbiServer::on_listener(
            nextgcore_sbi::server::SbiServerConfig::new(addr),
            listener,
        );
        server
            .start(move |_req: SbiRequest| {
                let seen = Arc::clone(&counter);
                async move {
                    seen.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    SbiResponse::with_status(409)
                        .with_json_body(&serde_json::json!({
                            "error": { "status": 409, "cause": "HIGHER_PRIORITY_REQUEST_ONGOING" },
                            "errInfo": { "retryAfter": retry_after },
                        }))
                        .unwrap()
                }
            })
            .await
            .expect("stand-in AMF starts");
        (server, addr.port(), seen)
    }

    fn n1n2_request_to(port: u16) -> (nextgcore_sbi::client::SbiClientConfig, SbiRequest) {
        let config = nextgcore_sbi::security::sbi_peer_client_config("127.0.0.1", port)
            .with_connect_timeout(std::time::Duration::from_secs(2))
            .with_request_timeout(std::time::Duration::from_secs(3));
        let request =
            SbiRequest::post("/namf-comm/v1/ue-contexts/imsi-001010007490041/n1-n2-messages")
                .with_body("{}".to_string(), "application/json");
        (config, request)
    }

    /// #1079 review m1: a refused transfer is not resent once its session is
    /// released. The retry re-checks the session before each resend.
    #[tokio::test]
    async fn a_refused_transfer_is_not_resent_after_its_session_is_released() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sm_ref = held_session_for_retry("imsi-001010007490041", 1);
        let (_amf, port, seen) = always_paging_amf(1).await;
        let (config, request) = n1n2_request_to(port);
        let retry = tokio::spawn(retry_n1n2_after_paging_conflict(
            config,
            request,
            sm_ref.clone(),
            std::time::Duration::from_secs(1),
            None,
        ));
        drop_session_for_retry(&sm_ref);
        let end = tokio::time::timeout(std::time::Duration::from_secs(3), retry)
            .await
            .expect("the retry ends")
            .expect("joined");
        assert_eq!(end, N1n2RetryEnd::SessionGone);
        assert_eq!(
            seen.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "nothing is resent for a released session"
        );
    }

    /// #1079 review m2: a `retryAfter` past [`N1N2_RETRY_AFTER_MAX_S`] is not
    /// shortened into an early resend (TS 29.518 §5.2.2.3.1): the transfer is given
    /// up at once, and nothing is resent. One within it is waited out in full.
    #[tokio::test]
    async fn a_retry_after_past_the_maximum_is_given_up_not_shortened() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sm_ref = held_session_for_retry("imsi-001010007490051", 1);
        let (_amf, port, seen) = always_paging_amf(N1N2_RETRY_AFTER_MAX_S + 1).await;
        let (config, request) = n1n2_request_to(port);
        let end = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            retry_n1n2_after_paging_conflict(
                config.clone(),
                request.clone(),
                sm_ref.clone(),
                std::time::Duration::from_secs(N1N2_RETRY_AFTER_MAX_S + 1),
                None,
            ),
        )
        .await
        .expect("given up at once, not waited out or shortened");
        assert_eq!(
            end,
            N1n2RetryEnd::WaitTooLong(std::time::Duration::from_secs(N1N2_RETRY_AFTER_MAX_S + 1))
        );
        assert_eq!(seen.load(std::sync::atomic::Ordering::SeqCst), 0);

        // Within the maximum: the resend comes only after the full retryAfter, and
        // the AMF's next 409 (past the maximum) ends it.
        let started = std::time::Instant::now();
        let end = retry_n1n2_after_paging_conflict(
            config,
            request,
            sm_ref.clone(),
            std::time::Duration::from_secs(2),
            None,
        )
        .await;
        assert!(started.elapsed() >= std::time::Duration::from_secs(2));
        assert_eq!(seen.load(std::sync::atomic::Ordering::SeqCst), 1);
        assert_eq!(
            end,
            N1n2RetryEnd::WaitTooLong(std::time::Duration::from_secs(N1N2_RETRY_AFTER_MAX_S + 1))
        );
        drop_session_for_retry(&sm_ref);
    }

    // ------------------------------------------------------------------
    // #1648: outbound service requests carry the NRF-issued token
    // ------------------------------------------------------------------

    /// The `(method, path, Authorization)` of each request an OAuth2 stand-in saw.
    type SeenAuth1648 = Arc<std::sync::Mutex<Vec<(String, String, Option<String>)>>>;

    /// #1648: a stand-in NRF token endpoint. It mints an ES256 access token, signed
    /// by `sk`, whose `aud` is the request's `targetNfType` and whose `scope` is the
    /// request's `scope` (TS 29.510 §6.3.5.2.2 AccessTokenReq), so a producer that
    /// verifies `aud` and `scope` (as nextgcore-sbi's does) accepts it. It answers
    /// both the bespoke and the TS 29.510 standard token path.
    async fn token_nrf_1648(sk: p256::ecdsa::SigningKey) -> (SbiServer, u16) {
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let server =
            SbiServer::on_listener(nextgcore_sbi::server::SbiServerConfig::new(addr), listener);
        server
            .start(move |req: SbiRequest| {
                let sk = sk.clone();
                async move {
                    let path = req.header.uri.split('?').next().unwrap_or_default();
                    if path != nextgcore_sbi::oauth::OAuth2Client::TOKEN_PATH_BESPOKE
                        && path != nextgcore_sbi::oauth::OAuth2Client::TOKEN_PATH_STANDARD
                    {
                        return SbiResponse::with_status(404);
                    }
                    let form = req.http.content.clone().unwrap_or_default();
                    let field = |name: &str| {
                        form.split('&')
                            .find_map(|kv| kv.strip_prefix(&format!("{name}=")))
                            .unwrap_or_default()
                            .replace("%20", " ")
                            .replace('+', " ")
                    };
                    let token = super::oauth2_h8_tests::build_es256_token(
                        &sk,
                        "nrf-1648",
                        &field("targetNfType"),
                        &field("scope"),
                    );
                    SbiResponse::with_status(200)
                        .with_json_body(&serde_json::json!({
                            "access_token": token,
                            "token_type": "Bearer",
                            "expires_in": 3600,
                        }))
                        .unwrap()
                }
            })
            .await
            .expect("token NRF starts");
        (server, addr.port())
    }

    /// #1648: a producer of NF type `nf_type` that, with `gated`, REQUIRES OAuth2
    /// the way an OAuth2-required amfd/udmd/easdfd listens: nextgcore-sbi verifies
    /// the bearer against the NRF's JWKS (`sk`'s public half) and checks that its
    /// `aud` names `nf_type`, answering 401 before the handler runs otherwise.
    ///
    /// The handler records each request it serves with its Authorization header,
    /// so on a gated producer a recorded request is one that PASSED the gate: a
    /// test asserts that the request it expects is recorded, which a token-less or
    /// wrong-audience send cannot satisfy. Ungated, it records what was sent, for
    /// asserting that a notification carries no token.
    async fn oauth2_producer_1648(
        sk: &p256::ecdsa::SigningKey,
        nf_type: nextgcore_sbi::types::NfType,
        gated: bool,
        respond: impl Fn(&SbiRequest) -> SbiResponse + Clone + Send + Sync + 'static,
    ) -> (SbiServer, u16, SeenAuth1648) {
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let seen: SeenAuth1648 = Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = Arc::clone(&seen);
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let mut cfg = nextgcore_sbi::server::SbiServerConfig::new(addr);
        if gated {
            cfg = cfg.with_expected_audience_nf_type(nf_type);
            cfg.require_oauth2 = true;
            cfg.oauth2_jwks = Some(super::oauth2_h8_tests::jwks_for(sk, "nrf-1648"));
        }
        let server = SbiServer::on_listener(cfg, listener);
        server
            .start(move |req: SbiRequest| {
                let sink = Arc::clone(&sink);
                let respond = respond.clone();
                async move {
                    sink.lock().unwrap_or_else(|e| e.into_inner()).push((
                        req.header.method.clone(),
                        req.header
                            .uri
                            .split('?')
                            .next()
                            .unwrap_or_default()
                            .to_string(),
                        req.http.get_header("authorization").cloned(),
                    ));
                    respond(&req)
                }
            })
            .await
            .expect("producer starts");
        (server, addr.port(), seen)
    }

    /// How many requests `seen` holds for `method` on a path containing `fragment`,
    /// each with a bearer.
    fn bearer_requests_1648(seen: &SeenAuth1648, method: &str, fragment: &str) -> usize {
        seen.lock()
            .unwrap_or_else(|e| e.into_inner())
            .iter()
            .filter(|(m, p, auth)| {
                m == method
                    && p.contains(fragment)
                    && auth.as_deref().is_some_and(|a| a.starts_with("Bearer "))
            })
            .count()
    }

    /// The OAuth2 client the SMF installs under enforcement, pointed at `nrf_port`.
    fn smf_oauth2_client_1648(nrf_port: u16) -> Arc<nextgcore_sbi::oauth::OAuth2Client> {
        Arc::new(nextgcore_sbi::oauth::OAuth2Client::new(
            format!("http://127.0.0.1:{nrf_port}"),
            "smf-1648",
            nextgcore_sbi::types::NfType::Smf,
        ))
    }

    /// #1648 review M1: a loopback TCP proxy to `upstream` that counts the
    /// connections it accepts, so a test can tell one reused connection from one
    /// per request.
    async fn counting_proxy_1648(upstream: u16) -> (u16, Arc<std::sync::atomic::AtomicUsize>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("proxy binds");
        let port = listener.local_addr().expect("addr").port();
        let accepted = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let counter = Arc::clone(&accepted);
        tokio::spawn(async move {
            while let Ok((mut inbound, _)) = listener.accept().await {
                counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                tokio::spawn(async move {
                    if let Ok(mut outbound) =
                        tokio::net::TcpStream::connect(("127.0.0.1", upstream)).await
                    {
                        let _ = tokio::io::copy_bidirectional(&mut inbound, &mut outbound).await;
                    }
                });
            }
        });
        (port, accepted)
    }

    /// A stand-in UDM's answers for the Nudm calls the reuse tests make.
    fn udm_answer_1648(req: &SbiRequest) -> SbiResponse {
        let path = req.header.uri.split('?').next().unwrap_or_default();
        if path.ends_with("/sm-data") {
            SbiResponse::with_status(200)
                .with_json_body(&serde_json::json!([]))
                .unwrap()
        } else {
            SbiResponse::with_status(201)
        }
    }

    /// How many calls the reuse tests make to one peer: twice the client's pool,
    /// so a client per call opens this many connections while a reused client
    /// opens at most [`pool_slots_1648`].
    const REUSE_CALLS_1648: usize = 8;

    /// The connection slots of one SBI client (its HTTP/2 pool, round-robin).
    fn pool_slots_1648() -> usize {
        nextgcore_sbi::security::sbi_peer_client_config("127.0.0.1", 1).pool_size
    }

    /// [`REUSE_CALLS_1648`] Nudm calls: sm-data reads, then a UECM registration.
    async fn nudm_calls_1648(supi: &str) {
        for _ in 1..REUSE_CALLS_1648 {
            let _ = udm::fetch_sm_data(supi, "internet", 1, Some("010203")).await;
        }
        udm::register_as_serving_smf(
            supi,
            1,
            "internet",
            1,
            Some("010203"),
            Some(("001", "01")),
            udm::EpsInterworkingInd::None,
        )
        .await;
    }

    /// #1648 review M1: with OAuth2 off, successive Nudm calls to one UDM share one
    /// connection, as they did through the shared `get_client` cache before #1648.
    #[tokio::test]
    async fn nudm_calls_reuse_pooled_connections_without_oauth2_1648() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sk = p256::ecdsa::SigningKey::from_slice(&[19u8; 32]).expect("key");
        let (_udm, udm_port, seen) = oauth2_producer_1648(
            &sk,
            nextgcore_sbi::types::NfType::Udm,
            false,
            udm_answer_1648,
        )
        .await;
        let (port, accepted) = counting_proxy_1648(udm_port).await;
        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", port.to_string());
        udm::set_for_test(true);
        nudm_calls_1648("imsi-001010016480004").await;
        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        assert_eq!(
            seen.lock().unwrap_or_else(|e| e.into_inner()).len(),
            REUSE_CALLS_1648
        );
        let connections = accepted.load(std::sync::atomic::Ordering::SeqCst);
        assert!(
            connections <= pool_slots_1648(),
            "{REUSE_CALLS_1648} Nudm calls opened {connections} connections, past the \
             {} of one reused client",
            pool_slots_1648()
        );
    }

    /// #1648 review M1: with OAuth2 on, the tokened Nudm client is cached per peer,
    /// so successive calls share its pooled connections (and, under `production`,
    /// their mTLS sessions) while each still carries the token.
    ///
    /// Review M2: the Namf client is NOT cached, because its authority is the one
    /// the AMF supplied in `smContextStatusUri`: after tokened Namf calls the cache
    /// holds no AMF entry, and each call still passes the OAuth2 gate.
    #[tokio::test]
    async fn tokened_udm_calls_reuse_pooled_connections_and_namf_is_not_cached_1648() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _cache = TOKENED_PEER_CLIENTS_TEST_LOCK.lock().await;
        let sk = p256::ecdsa::SigningKey::from_slice(&[20u8; 32]).expect("key");
        let (_nrf, nrf_port) = token_nrf_1648(sk.clone()).await;
        let (_udm, udm_port, udm_seen) = oauth2_producer_1648(
            &sk,
            nextgcore_sbi::types::NfType::Udm,
            true,
            udm_answer_1648,
        )
        .await;
        let (_amf, amf_port, amf_seen) =
            oauth2_producer_1648(&sk, nextgcore_sbi::types::NfType::Amf, true, |_| {
                SbiResponse::with_status(200)
            })
            .await;
        let (udm_proxy, udm_accepted) = counting_proxy_1648(udm_port).await;
        // Two distinct authorities for the same AMF, as two sessions'
        // `smContextStatusUri`s may name: neither may leave a cached client.
        let (amf_proxy, _) = counting_proxy_1648(amf_port).await;
        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", udm_proxy.to_string());
        udm::set_for_test(true);
        let supi = "imsi-001010016480005";
        let amf_uris = [
            format!("http://127.0.0.1:{amf_port}"),
            format!("http://127.0.0.1:{amf_proxy}"),
        ];
        TEST_OAUTH2_CLIENT
            .scope(smf_oauth2_client_1648(nrf_port), async {
                nudm_calls_1648(supi).await;
                for amf_uri in &amf_uris {
                    send_n2_release_transfer(amf_uri, supi, 1, &[0x00]).await;
                    send_n1_n2_release_transfer(amf_uri, supi, 1, &[0x2e], &[0x00]).await;
                }
            })
            .await;
        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        assert_eq!(
            bearer_requests_1648(&udm_seen, "GET", "/sm-data"),
            REUSE_CALLS_1648 - 1
        );
        assert_eq!(
            bearer_requests_1648(&udm_seen, "PUT", "/smf-registrations/1"),
            1
        );
        let connections = udm_accepted.load(std::sync::atomic::Ordering::SeqCst);
        assert!(
            connections <= pool_slots_1648(),
            "{REUSE_CALLS_1648} tokened Nudm calls opened {connections} connections, past \
             the {} of one reused client",
            pool_slots_1648()
        );
        assert_eq!(
            bearer_requests_1648(&amf_seen, "POST", "/n1-n2-messages"),
            4,
            "the Namf calls still carry the token"
        );
        assert!(
            !TOKENED_PEER_CLIENTS
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .keys()
                .any(|key| key.0 == nextgcore_sbi::types::NfType::Amf),
            "no Namf client is cached: its authority is peer-supplied"
        );
    }

    /// #1669 review M2: the tokened-client cache stops growing at
    /// [`TOKENED_PEER_CLIENTS_MAX`]. A client for one more peer is still returned,
    /// tokened, but not cached; a cached peer is still served from the cache.
    #[tokio::test]
    async fn the_tokened_client_cache_is_capped_1648() {
        let _cache = TOKENED_PEER_CLIENTS_TEST_LOCK.lock().await;
        let oauth2 = smf_oauth2_client_1648(nextgcore_sbi::test_support::refused_port());
        let mine = Arc::as_ptr(&oauth2) as usize;
        let held = || {
            TOKENED_PEER_CLIENTS
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .len()
        };
        TEST_OAUTH2_CLIENT
            .scope(oauth2, async {
                // Fill to the cap with distinct authorities (lazy clients: nothing
                // is dialled).
                let mut port = 20_000u16;
                let first = tokened_peer_client(
                    nextgcore_sbi::security::sbi_peer_client_config("127.0.0.1", port),
                    nextgcore_sbi::types::NfType::Udm,
                )
                .expect("enforcement on");
                while held() < TOKENED_PEER_CLIENTS_MAX {
                    port += 1;
                    let _ = tokened_peer_client(
                        nextgcore_sbi::security::sbi_peer_client_config("127.0.0.1", port),
                        nextgcore_sbi::types::NfType::Udm,
                    );
                }
                let past = tokened_peer_client(
                    nextgcore_sbi::security::sbi_peer_client_config("127.0.0.1", port + 1),
                    nextgcore_sbi::types::NfType::Udm,
                );
                assert!(
                    past.is_some(),
                    "a peer past the cap still gets a tokened client"
                );
                assert_eq!(
                    held(),
                    TOKENED_PEER_CLIENTS_MAX,
                    "the cache stops at its cap"
                );
                let again = tokened_peer_client(
                    nextgcore_sbi::security::sbi_peer_client_config("127.0.0.1", 20_000),
                    nextgcore_sbi::types::NfType::Udm,
                )
                .expect("enforcement on");
                assert!(Arc::ptr_eq(&first, &again), "a cached peer is still reused");
            })
            .await;
        TOKENED_PEER_CLIENTS
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .retain(|key, _| key.6 != mine);
    }

    /// #1648, found by the D443A `oauth2` arm: every Namf_Communication service
    /// request this SMF sends (N1N2MessageTransfer on the UP deactivation, release,
    /// paging-conflict and retry paths, and EBIAssignment) passes an OAuth2-required
    /// AMF's gate. They are service operations (TS 29.518 §5.2.2.3.1, §5.2.2.6), so
    /// the consumer presents its NRF-issued token (TS 33.501 §13.4.1.1.2, TS 29.500
    /// §6.7.3). Before the fix each one got 401 and never reached the AMF.
    ///
    /// The SmContextStatusNotify to the same AMF is a notification and carries no
    /// token (TS 33.501 §13.4.1, TS 29.500 §6.10.7 NOTE): it stays token-less.
    #[tokio::test]
    async fn namf_service_requests_pass_an_oauth2_required_amf_1648() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sk = p256::ecdsa::SigningKey::from_slice(&[16u8; 32]).expect("key");
        let (_nrf, nrf_port) = token_nrf_1648(sk.clone()).await;
        let (_amf, port, seen) =
            oauth2_producer_1648(&sk, nextgcore_sbi::types::NfType::Amf, true, |_| {
                SbiResponse::with_status(200)
            })
            .await;
        let (_plain_amf, plain_port, plain_seen) =
            oauth2_producer_1648(&sk, nextgcore_sbi::types::NfType::Amf, false, |_| {
                SbiResponse::with_status(204)
            })
            .await;
        let amf_uri = format!("http://127.0.0.1:{port}");
        let supi = "imsi-001010016480001";
        let sm_ref = held_session_for_retry(supi, 1);

        // The control: without enforcement the same transfer carries no token, and
        // the OAuth2-required AMF refuses it before its handler.
        send_n2_release_transfer(&amf_uri, supi, 1, &[0x00]).await;
        assert_eq!(seen.lock().unwrap_or_else(|e| e.into_inner()).len(), 0);

        eps_iwk::set_for_test(true);
        TEST_OAUTH2_CLIENT
            .scope(smf_oauth2_client_1648(nrf_port), async {
                send_n2_release_transfer(&amf_uri, supi, 1, &[0x00]).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/n1-n2-messages"),
                    1,
                    "the UP deactivation transfer carries the token"
                );
                send_n1_n2_release_transfer(&amf_uri, supi, 1, &[0x2e], &[0x00]).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/n1-n2-messages"),
                    2,
                    "the release transfer carries the token"
                );
                let (config, request) = n1n2_request_to(port);
                let resp = send_n1n2_honouring_paging_conflict(
                    config.clone(),
                    request.clone(),
                    sm_ref.clone(),
                    PagingRetries::Awaited(None),
                )
                .await
                .expect("answered");
                assert_eq!(resp.status, 200, "the AMF accepted the transfer");
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/n1-n2-messages"),
                    3,
                    "the paging-conflict-aware transfer carries the token"
                );
                let end = retry_n1n2_after_paging_conflict(
                    config,
                    request,
                    sm_ref.clone(),
                    std::time::Duration::ZERO,
                    None,
                )
                .await;
                assert_eq!(end, N1n2RetryEnd::Sent(200));
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/n1-n2-messages"),
                    4,
                    "the paging-conflict retry carries the token"
                );
                let _ = eps_iwk::request_ebi(Some(&amf_uri), supi, 1, 8).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/assign-ebi"),
                    1,
                    "the EBI assignment carries the token"
                );
                send_sm_context_status_notification(
                    Some(&format!(
                        "http://127.0.0.1:{plain_port}/namf-callback/v1/{supi}/1/sm-context-status"
                    )),
                    "RELEASED",
                    None,
                )
                .await;
            })
            .await;
        eps_iwk::set_for_test(false);
        drop_session_for_retry(&sm_ref);

        let notified = plain_seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        assert_eq!(notified.len(), 1, "the status notification was sent");
        assert_eq!(
            notified[0].2, None,
            "a notification carries no access token (TS 33.501 §13.4.1)"
        );
    }

    /// #1648: every Nudm service request (SDM get of smf-select-data and sm-data,
    /// UECM registration and its removal, SDM subscribe and unsubscribe) passes an
    /// OAuth2-required UDM's gate. They used the shared `get_client` cache, whose
    /// clients carry no token.
    #[tokio::test]
    async fn nudm_service_requests_pass_an_oauth2_required_udm_1648() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sk = p256::ecdsa::SigningKey::from_slice(&[17u8; 32]).expect("key");
        let (_nrf, nrf_port) = token_nrf_1648(sk.clone()).await;
        let sm_data = sm_data_with("40 Mbps", "80 Mbps", 6);
        let (_udm, port, seen) =
            oauth2_producer_1648(&sk, nextgcore_sbi::types::NfType::Udm, true, move |req| {
                let path = req.header.uri.split('?').next().unwrap_or_default();
                if req.header.method == "DELETE" {
                    SbiResponse::with_status(204)
                } else if path.ends_with("/sdm-subscriptions") {
                    SbiResponse::with_status(201)
                        .with_header("Location", format!("{path}/sub-1648"))
                        .with_json_body(&serde_json::json!({ "subscriptionId": "sub-1648" }))
                        .unwrap()
                } else if path.ends_with("/sm-data") {
                    SbiResponse::with_status(200)
                        .with_json_body(&sm_data)
                        .unwrap()
                } else if path.ends_with("/smf-select-data") {
                    SbiResponse::with_status(200)
                        .with_json_body(&serde_json::json!({}))
                        .unwrap()
                } else {
                    SbiResponse::with_status(201)
                }
            })
            .await;
        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", port.to_string());
        udm::set_for_test(true);
        let supi = "imsi-001010016480002";
        TEST_OAUTH2_CLIENT
            .scope(smf_oauth2_client_1648(nrf_port), async {
                let _ = fetch_subscribed_default_dnn(supi, 1, Some("010203")).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "GET", "/smf-select-data"),
                    1,
                    "Nudm_SDM_Get smf-select-data carries the token"
                );
                let _ = udm::fetch_sm_data(supi, "internet", 1, Some("010203")).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "GET", "/sm-data"),
                    1,
                    "Nudm_SDM_Get sm-data carries the token"
                );
                udm::register_as_serving_smf(
                    supi,
                    1,
                    "internet",
                    1,
                    Some("010203"),
                    Some(("001", "01")),
                    udm::EpsInterworkingInd::None,
                )
                .await;
                assert_eq!(
                    bearer_requests_1648(&seen, "PUT", "/smf-registrations/1"),
                    1,
                    "Nudm_UECM_Registration carries the token"
                );
                udm::deregister_serving_smf(supi, 1).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "DELETE", "/smf-registrations/1"),
                    1,
                    "Nudm_UECM_Deregistration carries the token"
                );
                let id = udm::subscribe_sm_data(
                    supi,
                    "http://127.0.0.1:9/nsmf-callback/v1/1/sdm-notify/0123456789abcdef",
                    "internet",
                    1,
                    Some("010203"),
                )
                .await
                .expect("subscribed past the gate");
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/sdm-subscriptions"),
                    1,
                    "Nudm_SDM_Subscribe carries the token"
                );
                udm::unsubscribe_sm_data(supi, &id).await;
                assert_eq!(
                    bearer_requests_1648(&seen, "DELETE", "/sdm-subscriptions/sub-1648"),
                    1,
                    "Nudm_SDM_Unsubscribe carries the token"
                );
            })
            .await;
        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
    }

    /// #1648: both Neasdf_DNSContext service requests (create and delete) pass an
    /// OAuth2-required EASDF's gate (TS 29.556 §5.2.2). The EASDF client was a
    /// cleartext `with_host_port` client with no token.
    #[tokio::test]
    async fn neasdf_service_requests_pass_an_oauth2_required_easdf_1648() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let sk = p256::ecdsa::SigningKey::from_slice(&[18u8; 32]).expect("key");
        let (_nrf, nrf_port) = token_nrf_1648(sk.clone()).await;
        let (_easdf, easdf_port, seen) =
            oauth2_producer_1648(&sk, nextgcore_sbi::types::NfType::Easdf, true, |req| {
                if req.header.method == "POST" {
                    SbiResponse::with_status(201)
                        .with_json_body(&serde_json::json!({ "dnsContextId": "ctx-1648" }))
                        .unwrap()
                } else {
                    SbiResponse::with_status(204)
                }
            })
            .await;
        // The discovery NRF (nnrf-disc is not OAuth2-gated by default).
        let (_disc, disc_port, _) =
            oauth2_producer_1648(&sk, nextgcore_sbi::types::NfType::Nrf, false, move |_| {
                SbiResponse::with_status(200)
                    .with_json_body(&serde_json::json!({
                        "validityPeriod": 3600,
                        "nfInstances": [{
                            "nfInstanceId": "easdf-1648",
                            "nfType": "EASDF",
                            "nfStatus": "REGISTERED",
                            "ipv4Addresses": ["127.0.0.1"],
                            "nfServices": [{
                                "serviceName": "neasdf-dnscontext",
                                "ipEndPoints": [{ "ipv4Address": "127.0.0.1", "port": easdf_port }]
                            }]
                        }]
                    }))
                    .unwrap()
            })
            .await;
        easdf::set_for_test(Some(easdf::EasdfConfig {
            nrf_uri: format!("http://127.0.0.1:{disc_port}"),
            edge_fqdn_patterns: vec!["*.edge.example.com".to_string()],
        }));
        let supi = "imsi-001010016480003";
        TEST_OAUTH2_CLIENT
            .scope(smf_oauth2_client_1648(nrf_port), async {
                let id = easdf::create_dns_context(
                    supi,
                    5,
                    "internet",
                    std::net::Ipv4Addr::new(10, 45, 0, 2),
                    "http://127.0.0.1:9/nsmf-callback/v1/1/easdf-dns-report/0123456789abcdef",
                )
                .await
                .expect("created past the gate");
                assert_eq!(
                    bearer_requests_1648(&seen, "POST", "/neasdf-dnscontext/v1/dns-contexts"),
                    1,
                    "the DNS context create carries the token"
                );
                easdf::delete_dns_context(supi, &id).await;
                assert_eq!(
                    bearer_requests_1648(
                        &seen,
                        "DELETE",
                        "/neasdf-dnscontext/v1/dns-contexts/ctx-1648"
                    ),
                    1,
                    "the DNS context delete carries the token"
                );
            })
            .await;
        easdf::set_for_test(None);
    }

    #[tokio::test]
    async fn fetch_subscribed_default_dnn_queries_the_udm_and_returns_the_flagged_dnn() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        // The stub UDM is a loopback PLAINTEXT peer, which describes a dev-profile
        // deployment; the default profile is Production and would require client
        // TLS material this test has no business inventing.
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let (port_listener, port_addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let port = port_addr.port();
        type Seen = (Vec<String>, Vec<std::collections::HashMap<String, String>>);
        let seen: Arc<std::sync::Mutex<Seen>> =
            Arc::new(std::sync::Mutex::new((Vec::new(), Vec::new())));
        let seen_in_handler = Arc::clone(&seen);

        let server = nextgcore_sbi::server::SbiServer::on_listener(
            nextgcore_sbi::server::SbiServerConfig::new(std::net::SocketAddr::from((
                [127, 0, 0, 1],
                port,
            ))),
            port_listener,
        );
        server
            .start(move |req: SbiRequest| {
                let seen = Arc::clone(&seen_in_handler);
                async move {
                    let uri = req.header.uri.clone();
                    {
                        let mut s = seen.lock().unwrap();
                        s.0.push(uri.clone());
                        s.1.push(req.http.params.clone().into_iter().collect());
                    }
                    if uri.contains("/nudm-sdm/") && uri.contains("smf-select-data") {
                        SbiResponse::with_status(200)
                            .with_json_body(&serde_json::json!({
                                "subscribedSnssaiInfos": {
                                    "01": { "dnnInfos": [
                                        { "dnn": "internet" },
                                        { "dnn": "operator-default", "defaultDnnIndicator": true },
                                    ]}
                                }
                            }))
                            .unwrap()
                    } else {
                        SbiResponse::with_status(404)
                    }
                }
            })
            .await
            .expect("stub UDM start");

        // Point the fallback at the stub. NRF discovery is tried first and will
        // fail (nothing answers nnrf-disc here), which also exercises that the
        // fallback really is reached rather than the discovery failure being fatal.
        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", port.to_string());
        std::env::remove_var("NRF_URI");

        let dnn = fetch_subscribed_default_dnn("imsi-262011234567890", 1, None).await;
        assert_eq!(
            dnn,
            Ok("operator-default".to_string()),
            "the flagged subscribed default must be used, not the first entry \
             and certainly not the old \"internet\" literal"
        );

        // The resource the UDM saw is the conformant one: v2 (Nudm_SDM is at v2 per
        // TS 29.503 §6.1.1, unlike the other Nudm services) and `smf-select-data`.
        // The server decodes the query into params, so the recorded URI carries no
        // query string -- the ENCODING is pinned by
        // `smf_select_data_path_percent_encodes_single_nssai` instead, and what is
        // asserted here is that the value ARRIVED and decoded back to the S-NSSAI.
        let (uris, params) = {
            let s = seen.lock().unwrap();
            (s.0.clone(), s.1.clone())
        };
        assert!(
            uris.iter()
                .any(|u| u == "/nudm-sdm/v2/imsi-262011234567890/smf-select-data"),
            "the UDM must have been queried at the v2 smf-select-data resource, saw {uris:?}"
        );
        // And NO `single-nssai` is sent: the shared SBI server does not
        // percent-decode query values (#65), so a JSON-valued parameter cannot
        // round-trip to the in-tree UDM. Asserted rather than left implicit,
        // because re-adding it would silently send an unparseable value.
        assert!(
            params.iter().all(|p| !p.contains_key("single-nssai")),
            "no single-nssai until #65 makes query decoding work, saw {params:?}"
        );

        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        // Deliberately NOT reset_sbi_profile_override(): the override is
        // process-wide, and resetting it here flipped `policy.rs`'s
        // `sm_policy_lifecycle_http_round_trip` back to Production mid-flight and
        // made it fail. Every other loopback-plaintext test in this crate sets the
        // Dev override and leaves it set; matching that is what keeps them
        // compatible.
        server.stop().await.expect("stop");
    }

    /// **Issue #204, criterion 4.** A DNN-less create with no reachable UDM is
    /// REFUSED with a cause that says so — never a silent `"internet"`.
    #[tokio::test]
    async fn dnn_less_create_with_no_udm_is_refused_not_defaulted() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        std::env::remove_var("NRF_URI");
        smf_context_init(64, 256, 512);

        let body = serde_json::json!({
            "pduSessionId": 5,
            "supi": "imsi-262011234567890",
            "sNssai": { "sst": 1 },
            "n1SmMsg": { "contentId": "n1SmMsg" },
        });
        let request = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts")
            .with_body(body.to_string(), "application/json");
        let resp = handle_sm_context_create(&request).await;

        // #1097 review m2: no UDM to ask is the SMF's failure, not a bad request.
        assert_eq!(resp.status, 500, "an unresolvable DNN refuses the session");
        let content = resp.http.content.as_deref().unwrap_or("");
        assert!(
            content.contains("SYSTEM_FAILURE"),
            "the cause must name the real problem, got {content}"
        );
        assert!(
            !content.contains("internet"),
            "the refusal must not mention a fabricated default, got {content}"
        );
    }

