    /// #1518: the EASDF's DNS message report is acted on only for the session its
    /// tokened URI names, with that session's token and its own DNS context:
    /// - the right token and context: 204, recorded;
    /// - a forged or another session's token, or another session's context under the
    ///   right token: 404, nothing recorded;
    /// - the token-less route of before #1518: only for a DNS context created before
    ///   then (no report token); for one created since it records nothing.
    /// On an OAuth2-required listener the tokened report is admitted on its token
    /// alone (easdfd sends no bearer and no client certificate); a forged token and the
    /// token-less route are 401.
    ///
    /// REVERT-VERIFIED: with the tokened arm not scoped to `{ref}`, the other
    /// session's context is recorded; with the legacy arm not limited to token-less
    /// contexts, the tokened session takes the token-less report; with the exemption
    /// dropped, the listener answers 401 to the right token.
    #[tokio::test]
    async fn an_easdf_report_names_one_session_on_its_token_1518() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let (a, b, legacy) = ("151831", "151832", "151833");
        for (r, psi) in [(a, 5), (b, 6), (legacy, 7)] {
            seed_binding(r, psi);
        }
        if let Ok(ctx) = smf_self().read() {
            let mut bindings = ctx.policy_bindings.write().unwrap();
            for r in [a, b, legacy] {
                bindings.get_mut(r).unwrap().easdf_dns_context_id = Some(format!("ctx-{r}"));
            }
            // A binding from before #1518: its DNS context holds the token-less URI.
            let l = bindings.get_mut(legacy).unwrap();
            l.callback_tokens = false;
            l.easdf_report_token = None;
        }
        let report = |ctx_id: &str| {
            serde_json::json!({
                "dnsContextId": ctx_id,
                "fqdn": "vr.edge.example.com",
                "action": "RESOLVE",
                "easIpAddresses": [format!("10.80.{}.8", ctx_id.len())],
            })
            .to_string()
        };
        let post = |path: String, body: String| async move {
            smf_sbi_request_handler(SbiRequest::post(path).with_body(body, "application/json"))
                .await
                .status
        };
        let recorded = |r: &str| {
            lookup_policy_binding(r)
                .map(|b| b.easdf_reported_eas)
                .unwrap_or_default()
        };
        let legacy_path = "/nsmf-pdusession/v1/easdf-dns-reports".to_string();

        assert_eq!(
            post(
                format!("/nsmf-callback/v1/{a}/easdf-dns-report/eas-forged"),
                report(&format!("ctx-{a}"))
            )
            .await,
            404
        );
        assert_eq!(
            post(
                format!("/nsmf-callback/v1/{a}/easdf-dns-report/eas-{b}"),
                report(&format!("ctx-{a}"))
            )
            .await,
            404,
            "another session's token"
        );
        assert_eq!(
            post(easdf_report_path(a), report(&format!("ctx-{b}"))).await,
            404,
            "another session's context under a's token"
        );
        assert!(recorded(a).is_empty() && recorded(b).is_empty());
        assert_eq!(
            post(legacy_path.clone(), report(&format!("ctx-{a}"))).await,
            204
        );
        assert!(
            recorded(a).is_empty(),
            "a context created since is not reported through the token-less route"
        );
        assert_eq!(
            post(easdf_report_path(a), report(&format!("ctx-{a}"))).await,
            204
        );
        assert_eq!(recorded(a).len(), 1, "a's own report, recorded");
        assert!(recorded(b).is_empty());
        assert_eq!(
            post(legacy_path.clone(), report(&format!("ctx-{legacy}"))).await,
            204
        );
        assert_eq!(recorded(legacy).len(), 1, "the pre-#1518 context's report");

        // Through an OAuth2-required listener.
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let mut cfg = with_callback_exemptions(NextgcoreSbiServerConfig::new(addr));
        cfg.require_oauth2 = true;
        cfg.oauth2_jwks = Some(serde_json::json!({"keys": []}));
        let server = SbiServer::on_listener(cfg, listener);
        server.start(smf_sbi_request_handler).await.expect("start");
        let client = nextgcore_sbi::client::SbiClient::with_host_port("127.0.0.1", addr.port());
        let mut statuses = Vec::new();
        for (path, ctx_id) in [
            (easdf_report_path(b), format!("ctx-{b}")),
            (
                format!("/nsmf-callback/v1/{b}/easdf-dns-report/eas-forged"),
                format!("ctx-{b}"),
            ),
            (legacy_path.clone(), format!("ctx-{legacy}")),
        ] {
            let req = SbiRequest::post(path.clone()).with_body(report(&ctx_id), "application/json");
            let status = tokio::time::timeout(Duration::from_secs(5), client.send_request(req))
                .await
                .expect("bounded")
                .expect("response")
                .status;
            statuses.push((path, status));
        }
        server.stop().await.expect("stop");
        assert_eq!(statuses[0].1, 204, "{:?}", statuses[0]);
        assert_eq!(recorded(b).len(), 1, "admitted on its token and recorded");
        for (path, status) in &statuses[1..] {
            assert_eq!(*status, 401, "{path}");
        }
        if let Ok(ctx) = smf_self().read() {
            let mut bindings = ctx.policy_bindings.write().unwrap();
            for r in [a, b, legacy] {
                bindings.remove(r);
            }
        }
    }

    /// #1631 review (R1 Y2): a paging past its guard does not hold a new one back
    /// when the report reaches `begin_network_paging` without the expiry pass
    /// `network_paging_pending` runs: the guard is part of "in progress" itself.
    ///
    /// REVERT-VERIFIED: with the guard check removed from
    /// `network_paging_in_progress`, the aged paging refuses the same priority.
    #[tokio::test]
    async fn an_aged_paging_does_not_hold_back_a_new_one_1631() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let (reference, _seid) = seed_paged_session_1631("imsi-001010000016319", 5, 9);
        let _first = begin_network_paging(&reference, Some(8)).expect("pages");
        if let Ok(ctx) = smf_self().read() {
            let mut bindings = ctx.policy_bindings.write().unwrap();
            let paging = bindings
                .get_mut(&reference)
                .and_then(|b| b.network_paging.as_mut())
                .expect("the paging");
            paging.started = std::time::Instant::now()
                .checked_sub(network_paging_guard() + std::time::Duration::from_secs(1))
                .expect("the clock is past the guard");
        }
        assert_eq!(up_state_1631(&reference), context::UpCnxState::Deactivated);
        assert!(
            begin_network_paging(&reference, Some(8)).is_ok(),
            "the aged paging is not in progress"
        );
        drop_session_for_retry(&reference);
    }

    /// #1631: on an OAuth2-required listener (empty JWKS), the AMF's token-less
    /// failure notification is admitted on the paging's token alone (only that AMF
    /// holds it), and acted on. A forged token, the token-less stub route and a
    /// service request are 401.
    ///
    /// REVERT-VERIFIED: with the exemption dropped, the right token is 401 too.
    #[tokio::test]
    async fn an_oauth2_listener_admits_the_paging_failure_on_its_token_1631() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let reference = "916311";
        if let Ok(ctx) = smf_self().read() {
            ctx.policy_bindings.write().unwrap().insert(
                reference.to_string(),
                context::PolicyBinding::snapshot_default(),
            );
        }
        let token = begin_network_paging(reference, Some(8)).expect("pages");
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let mut cfg = with_callback_exemptions(NextgcoreSbiServerConfig::new(addr));
        cfg.require_oauth2 = true;
        cfg.oauth2_jwks = Some(serde_json::json!({"keys": []}));
        let server = SbiServer::on_listener(cfg, listener);
        server.start(smf_sbi_request_handler).await.expect("start");
        let client = nextgcore_sbi::client::SbiClient::with_host_port("127.0.0.1", addr.port());
        let body = serde_json::json!({ "cause": "UE_NOT_RESPONDING", "n1n2MsgDataUri": "http:" });
        let mut statuses = Vec::new();
        for path in [
            format!("/nsmf-callback/v1/{reference}/n1-n2-failure/0123456789abcdef0123456789abcdef"),
            format!("/nsmf-callback/v1/n1-n2-failure/{reference}"),
            "/nsmf-pdusession/v1/sm-contexts".to_string(),
            format!(
                "/nsmf-callback/v1/{reference}/n1-n2-failure/{}",
                token.as_str()
            ),
        ] {
            let req =
                SbiRequest::post(path.clone()).with_body(body.to_string(), "application/json");
            let status = tokio::time::timeout(Duration::from_secs(5), client.send_request(req))
                .await
                .expect("bounded")
                .expect("response")
                .status;
            statuses.push((path, status));
        }
        server.stop().await.expect("stop");
        let pending = network_paging_pending(reference);
        if let Ok(ctx) = smf_self().read() {
            ctx.policy_bindings.write().unwrap().remove(reference);
        }
        let (last, refused) = statuses.split_last().expect("four");
        for (path, status) in refused {
            assert_eq!(*status, 401, "{path}");
        }
        assert_eq!(last.1, 204, "the paging's own token");
        assert!(!pending, "and the paging ended");
    }

    /// #1230: an SM context restored from the snapshot keeps its UPF N3 uplink endpoint,
    /// so after a restart its user plane can still be activated and the UE paged.
    ///
    /// A snapshot with `upfUlEndpoints` is restored into the SMF context (`set_state_file`, the boot
    /// path). It holds one SM context: its PFCP session, its binding and its uplink
    /// endpoint, with no in-memory session, as after a restart. Then:
    /// - the AMF's ACTIVATING is answered 200 with a PDU Session Resource Setup Request
    ///   Transfer naming the restored UL F-TEID (it was 500, "No user plane recorded");
    /// - a Downlink Data Report for the restored session's CP SEID pages the UE through
    ///   the AMF (it "matched no SM context").
    #[tokio::test]
    async fn a_restored_session_is_activated_and_paged_on_its_uplink_endpoint() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        use nextgcore_sbi::message::SbiResponse;
        use nextgcore_sbi::server::{SbiServer, SbiServerConfig};
        let seen: std::sync::Arc<std::sync::Mutex<Vec<(String, Vec<u8>)>>> =
            std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let amf = SbiServer::on_listener(SbiServerConfig::new(addr), listener);
        amf.start(move |req: SbiRequest| {
            let sink = sink.clone();
            async move {
                let mut bytes = req.http.content.clone().unwrap_or_default().into_bytes();
                for p in &req.http.parts {
                    bytes.extend_from_slice(&p.data);
                }
                sink.lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .push((req.header.uri.clone(), bytes));
                SbiResponse::with_status(200)
            }
        })
        .await
        .expect("amf start");

        const REF: &str = "91230";
        const SUPI: &str = "imsi-001010000091230";
        const UL_TEID: u32 = 0x1230_0123;
        let mut b = crate::context::PolicyBinding::snapshot_default();
        b.supi = SUPI.into();
        b.psi = 6;
        b.ue_ip = [10, 45, 123, 0];
        b.dnn = "internet".into();
        b.qfi = 1;
        b.five_qi = 9;
        b.arp_priority_level = 8;
        b.sm_context_status_uri = Some(format!(
            "http://127.0.0.1:{}/namf-callback/v1/smContextStatus/{REF}",
            addr.port()
        ));
        let doc = serde_json::json!({
            "version": 2,
            "pfcpSessions": { REF: 0x0123_0000u64 },
            "policyBindings": { REF: b },
            "upfUlEndpoints": { REF: { "teid": UL_TEID, "addr": "10.45.0.123" } },
        });
        let path = std::env::temp_dir().join(format!(
            "nextgcore-smf-1230-{}-{:?}.json",
            std::process::id(),
            std::time::SystemTime::now()
        ));
        std::fs::write(&path, serde_json::to_string(&doc).unwrap()).unwrap();
        {
            let handle = smf_self();
            let mut ctx = handle.write().unwrap();
            ctx.set_state_file(path.clone()).expect("restore");
            ctx.clear_state_file_for_test();
        }
        let _ = std::fs::remove_file(&path);
        let cleanup = || {
            if let Ok(ctx) = smf_self().read() {
                ctx.pfcp_sessions.write().unwrap().remove(REF);
                ctx.policy_bindings.write().unwrap().remove(REF);
                ctx.upf_ul_endpoints.write().unwrap().remove(REF);
            }
        };
        assert!(
            smf_self()
                .read()
                .unwrap()
                .sess_find_by_sm_context_ref(REF)
                .is_none_or(|s| s.sm_context_ref.as_deref() != Some(REF)),
            "no in-memory session: only what the snapshot holds"
        );

        // The UE's Service Request: the user plane is activated on the restored F-TEID.
        let activate = SbiRequest::post(format!("/nsmf-pdusession/v1/sm-contexts/{REF}/modify"))
            .with_body(
                serde_json::json!({ "upCnxState": "ACTIVATING" }).to_string(),
                "application/json",
            );
        let resp = handle_sm_context_update(REF, &activate).await;
        let teid = UL_TEID.to_be_bytes();
        let n2 = resp
            .http
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n2SmInfo"))
            .map(|p| p.data.to_vec());
        let activated = (resp.status, n2.clone());

        // Downlink data for the idle UE: paged.
        let upf = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let smf_sock =
            std::sync::Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let upf_addr = upf.local_addr().unwrap();
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        pfcp_path::set_global_pool(vec![
            pfcp_path::PfcpClient::associated_for_test(smf_sock.clone(), upf_addr).await,
        ]);
        let seid = context::derive_cp_n4_seid(REF);
        handle_pfcp_session_report(&smf_sock, &dldr_report_packet(seid, 1), upf_addr).await;
        pfcp_path::clear_global_upf_for_test();
        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        cleanup();
        amf.stop().await.expect("stop");

        assert_eq!(
            activated.0, 200,
            "the restored session's user plane is activated"
        );
        let n2 = activated.1.expect("the Setup Request Transfer");
        assert!(
            n2.windows(4).any(|w| w == teid),
            "the transfer names the restored UL F-TEID {UL_TEID:#x}: {n2:02x?}"
        );
        let paging = requests
            .iter()
            .find(|(uri, _)| uri.contains(&format!("/ue-contexts/{SUPI}/n1-n2-messages")))
            .unwrap_or_else(|| panic!("the restored session's UE is paged: {requests:?}"));
        let _ = paging;
    }

    /// #1230 review: a native 5G SM context restored from a snapshot without its uplink
    /// endpoint (written before #1230, or by a rolled-back 0.1.x) is kept, not released.
    /// The endpoint is recovered from the UPF on first need.
    ///
    /// A version-2 snapshot with no `upfUlEndpoints` is restored. The AMF's
    /// ACTIVATING then makes the SMF remove PDR 1 at the UPF and create it again with
    /// a TEID of 0, which is this tree's CHOOSE (the UPF allocates the TEID). Two
    /// modifications go out, in that order. The answer is 200 with a Setup Request
    /// Transfer naming the F-TEID the UPF chose, and that F-TEID is recorded. A
    /// second ACTIVATING sends nothing more to the UPF. A Downlink Data Report for the
    /// session pages the UE.
    #[tokio::test]
    async fn a_restored_session_without_its_endpoint_recovers_it_from_the_upf() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        use nextgcore_sbi::message::SbiResponse;
        use nextgcore_sbi::server::{SbiServer, SbiServerConfig};
        let upf = pfcp_path::stand_in::associated_upf().await;
        let pages = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let sink = pages.clone();
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let amf = SbiServer::on_listener(SbiServerConfig::new(addr), listener);
        amf.start(move |req: SbiRequest| {
            let sink = sink.clone();
            async move {
                if req.header.uri.contains("/n1-n2-messages") {
                    sink.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                }
                SbiResponse::with_status(200)
            }
        })
        .await
        .expect("amf start");

        const REF: &str = "91231";
        let mut b = crate::context::PolicyBinding::snapshot_default();
        b.supi = "imsi-001010000091231".into();
        b.psi = 7;
        b.ue_ip = [10, 45, 123, 1];
        b.dnn = "internet".into();
        b.qfi = 1;
        b.five_qi = 9;
        b.arp_priority_level = 8;
        b.sm_context_status_uri = Some(format!(
            "http://127.0.0.1:{}/namf-callback/v1/smContextStatus/{REF}",
            addr.port()
        ));
        let doc = serde_json::json!({
            "version": 2,
            "pfcpSessions": { REF: upf.upf_seid },
            "policyBindings": { REF: b },
        });
        let path = std::env::temp_dir().join(format!(
            "nextgcore-smf-1230b-{}-{:?}.json",
            std::process::id(),
            std::time::SystemTime::now()
        ));
        std::fs::write(&path, serde_json::to_string(&doc).unwrap()).unwrap();
        {
            let handle = smf_self();
            let mut ctx = handle.write().unwrap();
            ctx.set_state_file(path.clone()).expect("restore");
            ctx.clear_state_file_for_test();
        }
        let _ = std::fs::remove_file(&path);
        assert!(
            smf_self()
                .read()
                .unwrap()
                .unrestorable_sessions
                .read()
                .unwrap()
                .is_empty(),
            "nothing is released"
        );
        assert_eq!(lookup_upf_ul_endpoint(REF), None);
        upf.clear_seen();

        let activate = || {
            SbiRequest::post(format!("/nsmf-pdusession/v1/sm-contexts/{REF}/modify")).with_body(
                serde_json::json!({ "upCnxState": "ACTIVATING" }).to_string(),
                "application/json",
            )
        };
        let resp = handle_sm_context_update(REF, &activate()).await;
        let mods = upf.modification_bodies();
        let n2 = resp
            .http
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n2SmInfo"))
            .map(|p| p.data.to_vec());
        let recovered = lookup_upf_ul_endpoint(REF);
        let again = handle_sm_context_update(REF, &activate()).await;
        let mods_after = upf.modification_bodies().len();

        // Downlink data for the idle UE: paged, from the UPF serving it.
        let smf_sock = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        handle_pfcp_session_report(
            &smf_sock,
            &dldr_report_packet(context::derive_cp_n4_seid(REF), 1),
            upf.client.peer(),
        )
        .await;
        let paged = pages.load(std::sync::atomic::Ordering::SeqCst);
        amf.stop().await.expect("stop");

        let pdr_1 = [0x00, 0x38, 0x00, 0x02, 0x00, 0x01];
        assert_eq!(mods.len(), 2, "remove, then create: {mods:02x?}");
        assert!(
            mods[0].windows(4).any(|w| w == [0x00, 0x0f, 0x00, 0x06])
                && mods[0].windows(6).any(|w| w == pdr_1),
            "Remove PDR 1 first"
        );
        assert!(
            mods[1].windows(2).any(|w| w == [0x00, 0x01])
                && mods[1].windows(6).any(|w| w == pdr_1)
                && !mods[1].windows(4).any(|w| w == [0x00, 0x0f, 0x00, 0x06]),
            "then Create PDR 1 alone"
        );
        let (teid, addr) = recovered.expect("recorded");
        assert!(teid != 0 && addr == upf.upf_ip, "the F-TEID the UPF chose");
        assert_eq!(resp.status, 200);
        let n2 = n2.expect("the Setup Request Transfer");
        assert!(
            n2.windows(4).any(|w| w == teid.to_be_bytes()),
            "the transfer names the UPF's new F-TEID {teid:#x}"
        );
        assert_eq!(again.status, 200);
        assert_eq!(mods_after, 2, "a known endpoint is not recovered again");
        assert_eq!(paged, 1, "and the idle UE is paged for downlink data");
    }

    /// #1230 review 2: restore, from a snapshot without `upfUlEndpoints`, one SM context
    /// on the stand-in UPF, with its AMF callback at `amf_port`.
    fn restore_without_endpoint(reference: &str, supi: &str, upf_seid: u64, amf_port: u16) {
        let mut b = crate::context::PolicyBinding::snapshot_default();
        b.supi = supi.into();
        b.psi = 7;
        b.ue_ip = [10, 45, 123, 2];
        b.dnn = "internet".into();
        b.qfi = 1;
        b.five_qi = 9;
        b.arp_priority_level = 8;
        b.sm_context_status_uri = Some(format!(
            "http://127.0.0.1:{amf_port}/namf-callback/v1/smContextStatus/{reference}"
        ));
        let doc = serde_json::json!({
            "version": 2,
            "pfcpSessions": { reference: upf_seid },
            "policyBindings": { reference: b },
        });
        let path = std::env::temp_dir().join(format!(
            "nextgcore-smf-1230-{reference}-{}-{:?}.json",
            std::process::id(),
            std::time::SystemTime::now()
        ));
        std::fs::write(&path, serde_json::to_string(&doc).unwrap()).unwrap();
        {
            let handle = smf_self();
            let mut ctx = handle.write().unwrap();
            ctx.set_state_file(path.clone()).expect("restore");
            ctx.clear_state_file_for_test();
        }
        let _ = std::fs::remove_file(&path);
        assert_eq!(
            lookup_upf_ul_endpoint(reference),
            None,
            "restored without it"
        );
    }

    /// A stand-in AMF that counts N1N2MessageTransfers; returns the server, its port
    /// and the count.
    async fn counting_amf() -> (
        nextgcore_sbi::server::SbiServer,
        u16,
        std::sync::Arc<std::sync::atomic::AtomicUsize>,
    ) {
        use nextgcore_sbi::message::SbiResponse;
        use nextgcore_sbi::server::{SbiServer, SbiServerConfig};
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let pages = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let sink = pages.clone();
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let amf = SbiServer::on_listener(SbiServerConfig::new(addr), listener);
        amf.start(move |req: SbiRequest| {
            let sink = sink.clone();
            async move {
                if req.header.uri.contains("/n1-n2-messages") {
                    sink.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                }
                SbiResponse::with_status(200)
            }
        })
        .await
        .expect("amf start");
        (amf, addr.port(), pages)
    }

    /// The recovery's two Session Modifications: Remove PDR 1, then Create PDR 1 alone.
    fn assert_recovery_mods(mods: &[Vec<u8>]) {
        let pdr_1 = [0x00, 0x38, 0x00, 0x02, 0x00, 0x01];
        let remove = [0x00, 0x0f, 0x00, 0x06];
        assert!(mods.len() >= 2, "remove, then create: {mods:02x?}");
        assert!(
            mods[0].windows(4).any(|w| w == remove) && mods[0].windows(6).any(|w| w == pdr_1),
            "Remove PDR 1 first: {:02x?}",
            mods[0]
        );
        assert!(
            mods[1].windows(2).any(|w| w == [0x00, 0x01])
                && mods[1].windows(6).any(|w| w == pdr_1)
                && !mods[1].windows(4).any(|w| w == remove),
            "then Create PDR 1 alone: {:02x?}",
            mods[1]
        );
    }

    /// #1230 review 2: the most common path after a restart, an idle UE with downlink
    /// data first. The Downlink Data Report recovers the endpoint (Remove, then Create
    /// PDR 1) before it pages, and the page goes out.
    #[tokio::test]
    async fn a_restored_session_paged_first_recovers_its_endpoint() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let upf = pfcp_path::stand_in::associated_upf().await;
        let (amf, port, pages) = counting_amf().await;
        const REF: &str = "91232";
        restore_without_endpoint(REF, "imsi-001010000091232", upf.upf_seid, port);
        upf.clear_seen();
        let smf_sock = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        handle_pfcp_session_report(
            &smf_sock,
            &dldr_report_packet(context::derive_cp_n4_seid(REF), 1),
            upf.client.peer(),
        )
        .await;
        let mods = upf.modification_bodies();
        let recovered = lookup_upf_ul_endpoint(REF);
        let paged = pages.load(std::sync::atomic::Ordering::SeqCst);
        amf.stop().await.expect("stop");
        assert_recovery_mods(&mods);
        assert_eq!(mods.len(), 2);
        assert!(
            recovered.is_some_and(|(t, _)| t != 0),
            "recorded: {recovered:?}"
        );
        assert_eq!(paged, 1, "paged");
    }

    /// #1230 review 2: recovery is single-flight. A paging and an ACTIVATING for the
    /// same restored context, at once against a slow UPF: one Remove and one Create, and
    /// the ACTIVATING answer names the F-TEID the one recovery recorded. The second
    /// caller waits for that recovery and does not remove the TEID it chose.
    #[tokio::test]
    async fn concurrent_recoveries_of_one_endpoint_run_once() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let upf = pfcp_path::stand_in::associated_upf().await;
        let (amf, port, pages) = counting_amf().await;
        const REF: &str = "91233";
        restore_without_endpoint(REF, "imsi-001010000091233", upf.upf_seid, port);
        upf.clear_seen();
        upf.delay_modifications(150);
        let smf_sock = tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap();
        let report = dldr_report_packet(context::derive_cp_n4_seid(REF), 1);
        let activate = SbiRequest::post(format!("/nsmf-pdusession/v1/sm-contexts/{REF}/modify"))
            .with_body(
                serde_json::json!({ "upCnxState": "ACTIVATING" }).to_string(),
                "application/json",
            );
        let ((), resp) = tokio::join!(
            handle_pfcp_session_report(&smf_sock, &report, upf.client.peer()),
            handle_sm_context_update(REF, &activate),
        );
        upf.delay_modifications(0);
        let mods = upf.modification_bodies();
        let recovered = lookup_upf_ul_endpoint(REF).expect("recorded");
        let _ = pages.load(std::sync::atomic::Ordering::SeqCst);
        amf.stop().await.expect("stop");
        assert_recovery_mods(&mods);
        assert_eq!(mods.len(), 2, "one recovery: {mods:02x?}");
        assert_eq!(resp.status, 200);
        let n2 = resp
            .http
            .parts
            .iter()
            .find(|p| p.content_id.as_deref() == Some("n2SmInfo"))
            .map(|p| p.data.to_vec())
            .expect("the transfer");
        assert!(
            n2.windows(4).any(|w| w == recovered.0.to_be_bytes()),
            "the ACTIVATING answer names the recorded F-TEID {:#x}",
            recovered.0
        );
    }

    /// #1230 review 2: a handover preparation of a context without its endpoint
    /// recovers it, and the target's Handover Request Transfer names it.
    #[tokio::test]
    async fn a_handover_preparation_recovers_a_missing_endpoint() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let upf = pfcp_path::stand_in::associated_upf().await;
        let reference = seed_registered_session("imsi-001010000091234", 5, "internet");
        {
            let ctx = smf_self();
            let ctx = ctx.read().unwrap();
            ctx.pfcp_sessions
                .write()
                .unwrap()
                .insert(reference.clone(), upf.upf_seid);
            ctx.upf_ul_endpoints.write().unwrap().remove(&reference);
            let mut b = context::PolicyBinding::snapshot_default();
            b.qfi = 1;
            b.five_qi = 9;
            b.arp_priority_level = 8;
            b.ue_ip = [10, 45, 123, 4];
            ctx.policy_bindings
                .write()
                .unwrap()
                .insert(reference.clone(), b);
        }
        upf.clear_seen();
        let resp = handle_sm_context_update(
            &reference,
            &ho_update(
                &reference,
                serde_json::json!({
                    "hoState": "PREPARING",
                    "n2SmInfoType": "HANDOVER_REQUIRED",
                    "n2SmInfo": { "contentId": "n2SmInfo" },
                }),
                None,
            ),
        )
        .await;
        let mods = upf.modification_bodies();
        let recovered = lookup_upf_ul_endpoint(&reference).expect("recorded");
        assert_recovery_mods(&mods);
        assert_eq!(resp.status, 200, "PREPARING");
        let (root, n2) = ho_answer(&resp);
        assert_eq!(root["hoState"], "PREPARING");
        let n2 = n2.expect("the Handover Request Transfer");
        assert!(n2.windows(4).any(|w| w == recovered.0.to_be_bytes()));
    }

    /// #1162 review M1: with no recorded uplink endpoint or binding there is no
    /// transfer, so no N1N2MessageTransfer: one without `ngapData` (M, TS 29.518 Table
    /// 6.1.6.2.27-1) is malformed, and the ACTIVATING it would lead to fails for the
    /// same missing endpoint. Paging would only wake the UE for nothing, at every
    /// buffered packet. A stand-in AMF sees no request.
    #[tokio::test]
    async fn a_session_with_no_recorded_user_plane_is_not_paged() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let (amf, port, seen) = always_paging_amf(1).await;
        let supi = "imsi-001010000011621";
        let reference = seed_registered_session(supi, 9, "internet");
        assert!(paging_n1n2_body(9, Some(5), &reference).is_none());
        send_n1_n2_paging_request(
            &format!("http://127.0.0.1:{port}"),
            supi,
            9,
            Some(5),
            &reference,
            PagingStart::Report,
        )
        .await;
        // A request, had one been sent, is answered before this returns.
        let sent = seen.load(std::sync::atomic::Ordering::SeqCst);
        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");
        assert_eq!(sent, 0, "no N1N2MessageTransfer reaches the AMF");
    }

    /// The other half: a DLDR for a session whose user plane is UP must NOT page.
    /// TS 29.244 §7.5.8.2 scopes the report to a *deactivated* connection, and
    /// paging a connected UE is a spurious service request. Without this, "a DLDR
    /// pages" would be satisfied by a version that pages unconditionally.
    #[tokio::test]
    async fn a_downlink_data_report_for_an_active_connection_does_not_page() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        // Drives production peer-call code against a loopback PLAINTEXT peer, i.e. a
        // dev-profile deployment. Declared rather than inherited: the default
        // `SbiProfile` is Production, which would refuse the plaintext connection and
        // make this test fail for a reason unrelated to what it asserts.
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        use nextgcore_sbi::message::SbiResponse;
        use nextgcore_sbi::server::{SbiServer, SbiServerConfig};

        let seen: std::sync::Arc<std::sync::Mutex<Vec<String>>> =
            std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let (port_listener, port_addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let port = port_addr.port();
        let amf = SbiServer::on_listener(
            SbiServerConfig::new(std::net::SocketAddr::from(([127, 0, 0, 1], port))),
            port_listener,
        );
        amf.start(move |req: SbiRequest| {
            let sink = sink.clone();
            async move {
                sink.lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .push(req.header.uri.clone());
                SbiResponse::with_status(200)
            }
        })
        .await
        .expect("amf start");

        let reference = seed_registered_session("imsi-001010000000085", 2, "internet");
        let seid = {
            let ctx = smf_self();
            let context = ctx.read().expect("context");
            let mut sess = context
                .sess_find_by_sm_context_ref(&reference)
                .expect("session");
            // ACTIVATED, which `seed_registered_session` already sets.
            sess.sm_context_status_uri = Some(format!("http://127.0.0.1:{port}"));
            context.sess_update(&sess);
            sess.smf_n4_seid
        };

        let upf = tokio::net::UdpSocket::bind("127.0.0.1:0")
            .await
            .expect("fake UPF socket");
        let smf_sock = tokio::net::UdpSocket::bind("127.0.0.1:0")
            .await
            .expect("smf socket");
        let upf_addr = upf.local_addr().expect("upf addr");
        // #1509: the session's own, associated UPF, so the report is ACCEPTED and the
        // DLDR branch runs. Before, no pool was installed and the report was refused
        // (cause 65) before the branch: "not paged" held for the wrong reason.
        let smf_sock = std::sync::Arc::new(smf_sock);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        pfcp_path::set_global_pool(vec![
            pfcp_path::PfcpClient::associated_for_test(smf_sock.clone(), upf_addr).await,
        ]);
        handle_pfcp_session_report(&smf_sock, &dldr_report_packet(seid, 1), upf_addr).await;
        pfcp_path::clear_global_upf_for_test();
        let mut buf = vec![0u8; 512];
        let answer = tokio::time::timeout(std::time::Duration::from_secs(2), upf.recv(&mut buf))
            .await
            .expect("a Session Report Response")
            .map(|n| buf[..n].to_vec())
            .unwrap();

        assert_eq!(pfcp_cause_of(&answer), Some(1), "the report is accepted");
        assert!(
            seen.lock().unwrap_or_else(|e| e.into_inner()).is_empty(),
            "an active user-plane connection must not be paged"
        );

        amf.stop().await.expect("stop");
    }

    // ==================================================================
    // #1707: a UE the AMF reported unreachable (TS 23.502 §4.2.3.3 steps 3a, 3c).
    // ==================================================================

    /// What the #1707 stand-in AMF saw: (method, path, body).
    type AmfSeen1707 = Arc<std::sync::Mutex<Vec<(String, String, serde_json::Value)>>>;

    /// A stand-in AMF for #1707. It answers the `n`-th N1N2MessageTransfer with
    /// `answers[n]` (the last one repeated). It answers a Namf_EventExposure
    /// subscribe 201 with `subscriptionId` `sub-1707-<n>`, and an unsubscribe 204. It
    /// is strict: a subscription missing a mandatory member of AmfEventSubscription
    /// (TS 29.518 Table 6.2.6.2.3-1) gets the 400 amfd answers.
    async fn reachability_amf_1707(
        answers: Vec<(u16, serde_json::Value)>,
    ) -> (nextgcore_sbi::server::SbiServer, u16, AmfSeen1707) {
        reachability_amf_with_1707(answers, false).await
    }

    /// [`reachability_amf_1707`]; with `immediate`, it behaves as a conformant AMF for
    /// a UE reachable at subscription time (TS 29.518 §5.3.1, `29518-k00.txt:5074-5080`):
    /// before it answers the subscription, it delivers a REACHABLE report to its
    /// `eventNotifyUri` (seen as `NOTIFY`, with the SMF's status as the body), then
    /// answers 201 with `subscriptionId` `sub-late`.
    async fn reachability_amf_with_1707(
        answers: Vec<(u16, serde_json::Value)>,
        immediate: bool,
    ) -> (nextgcore_sbi::server::SbiServer, u16, AmfSeen1707) {
        let (listener, addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let seen: AmfSeen1707 = Arc::default();
        let sink = Arc::clone(&seen);
        let answers = Arc::new(answers);
        let transfers = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let subscriptions = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let server = nextgcore_sbi::server::SbiServer::on_listener(
            nextgcore_sbi::server::SbiServerConfig::new(addr),
            listener,
        );
        server
            .start(move |req: SbiRequest| {
                let sink = Arc::clone(&sink);
                let answers = Arc::clone(&answers);
                let transfers = Arc::clone(&transfers);
                let subscriptions = Arc::clone(&subscriptions);
                async move {
                    use std::sync::atomic::Ordering;
                    let body = req
                        .http
                        .content
                        .as_deref()
                        .and_then(|c| serde_json::from_str(c).ok())
                        .unwrap_or(serde_json::Value::Null);
                    let method = req.header.method.clone();
                    let path = req.header.uri.clone();
                    sink.lock()
                        .unwrap_or_else(|e| e.into_inner())
                        .push((method.clone(), path.clone(), body.clone()));
                    if path.ends_with("/n1-n2-messages") {
                        let n = transfers.fetch_add(1, Ordering::SeqCst);
                        let (status, answer) = answers[n.min(answers.len() - 1)].clone();
                        return SbiResponse::with_status(status)
                            .with_json_body(&answer)
                            .unwrap_or_else(|_| SbiResponse::with_status(status));
                    }
                    if path == "/namf-evts/v1/subscriptions" && method == "POST" {
                        let sub = &body["subscription"];
                        let complete = sub["eventList"].as_array().is_some_and(|l| !l.is_empty())
                            && sub["eventNotifyUri"].is_string()
                            && sub["notifyCorrelationId"].is_string()
                            && sub["nfId"].is_string();
                        if !complete {
                            return SbiResponse::with_status(400);
                        }
                        let id = if immediate {
                            let uri = sub["eventNotifyUri"].as_str().unwrap_or_default();
                            let path = &uri[uri.find("/nsmf-callback/").unwrap_or(0)..];
                            let status = smf_sbi_request_handler(
                                SbiRequest::post(path.to_string()).with_body(
                                    serde_json::json!({
                                        "notifyCorrelationId": sub["notifyCorrelationId"],
                                        "reportList": [{
                                            "type": "REACHABILITY_REPORT",
                                            "state": { "active": true },
                                            "timeStamp": "2026-11-18T00:00:00Z",
                                            "reachability": "REACHABLE",
                                        }],
                                    })
                                    .to_string(),
                                    "application/json",
                                ),
                            )
                            .await
                            .status;
                            sink.lock().unwrap_or_else(|e| e.into_inner()).push((
                                "NOTIFY".to_string(),
                                path.to_string(),
                                serde_json::json!(status),
                            ));
                            "sub-late".to_string()
                        } else {
                            format!(
                                "sub-1707-{}",
                                subscriptions.fetch_add(1, Ordering::SeqCst)
                            )
                        };
                        return SbiResponse::with_status(201)
                            .with_json_body(&serde_json::json!({
                                "subscription": sub,
                                "subscriptionId": format!("http://127.0.0.1/namf-evts/v1/subscriptions/{id}"),
                            }))
                            .expect("json");
                    }
                    if method == "DELETE" {
                        return SbiResponse::with_status(204);
                    }
                    SbiResponse::with_status(404)
                }
            })
            .await
            .expect("stand-in AMF starts");
        (server, addr.port(), seen)
    }

    fn not_reachable_1707() -> (u16, serde_json::Value) {
        (
            504,
            serde_json::json!({ "error": { "status": 504, "cause": "UE_NOT_REACHABLE" } }),
        )
    }

    fn transfers_1707(seen: &AmfSeen1707) -> usize {
        seen.lock()
            .unwrap()
            .iter()
            .filter(|(_, p, _)| p.ends_with("/n1-n2-messages"))
            .count()
    }

    fn requests_1707(
        seen: &AmfSeen1707,
        method: &str,
        path_has: &str,
    ) -> Vec<(String, serde_json::Value)> {
        seen.lock()
            .unwrap()
            .iter()
            .filter(|(m, p, _)| m == method && p.contains(path_has))
            .map(|(_, p, b)| (p.clone(), b.clone()))
            .collect()
    }

    /// Wait for the `n`-th request matching (method, path).
    async fn await_requests_1707(seen: &AmfSeen1707, method: &str, path_has: &str, n: usize) {
        let ok = nextgcore_sbi::test_support::poll_until(
            std::time::Duration::from_secs(5),
            std::time::Duration::from_millis(10),
            || async { (requests_1707(seen, method, path_has).len() >= n).then_some(()) },
        )
        .await;
        assert!(
            ok.is_some(),
            "{method} {path_has} x{n}: {:?}",
            seen.lock().unwrap()
        );
    }

    /// The token in a subscription's `eventNotifyUri`, which must be the session's
    /// `{ref}/ue-reachability/{token}`.
    fn reachability_token_1707(body: &serde_json::Value, reference: &str) -> String {
        let uri = body["subscription"]["eventNotifyUri"]
            .as_str()
            .unwrap_or_else(|| panic!("an eventNotifyUri: {body}"));
        let marker = format!("/nsmf-callback/v1/{reference}/ue-reachability/");
        let at = uri.find(&marker).unwrap_or_else(|| panic!("{uri}"));
        uri[at + marker.len()..].to_string()
    }

    async fn notify_reachability_1707(reference: &str, token: &str, reachability: &str) -> u16 {
        smf_sbi_request_handler(
            SbiRequest::post(format!(
                "/nsmf-callback/v1/{reference}/ue-reachability/{token}"
            ))
            .with_body(
                serde_json::json!({
                    "notifyCorrelationId": reference,
                    "reportList": [{
                        "type": "REACHABILITY_REPORT",
                        "state": { "active": true },
                        "timeStamp": "2026-11-18T00:00:00Z",
                        "reachability": reachability,
                    }],
                })
                .to_string(),
                "application/json",
            ),
        )
        .await
        .status
    }

    /// #1707, TS 23.502 §4.2.3.3 steps 3a and 3c, both peers' halves of the
    /// exchange the SMF drives:
    /// - a paging the AMF answers 504 UE_NOT_REACHABLE records the UE unreachable,
    ///   and the SMF subscribes at the AMF to REACHABILITY_REPORT, "UE Reachable for
    ///   DL Traffic", with an `eventNotifyUri` carrying a token of its own;
    /// - while it holds, a Downlink Data Report for that session, or for another
    ///   session of the UE, pages nothing (step 3a);
    /// - a second 504 does not subscribe twice;
    /// - a notification with another token, or reporting UNREACHABLE, or with no
    ///   reportList, changes nothing;
    /// - REACHABLE ends it: the subscription is deleted, a report pages again, and
    ///   the same notification again is refused, with no second delete.
    ///
    /// REVERT-VERIFIED: with the report path not asking `ue_unreachable_holds`,
    /// "step 3a: no page" fails; with the notify handler not clearing, "REACHABLE: a
    /// report pages again" fails; with `record_ue_unreachable` recording every time,
    /// "a repeated indication" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn an_unreachable_ue_is_paged_again_only_once_the_amf_reports_it_reachable_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (amf, port, seen) =
            reachability_amf_1707(vec![not_reachable_1707(), attempting_1631()]).await;
        let supi = "imsi-001010000170701";
        let (reference, seid) = seed_paged_session_1631(supi, 5, port);
        let (other, other_seid) = seed_paged_session_1631(supi, 6, port);

        report_dl_data_1631(seid, 5).await;
        assert_eq!(transfers_1707(&seen), 1);
        await_requests_1707(&seen, "POST", "/namf-evts/v1/subscriptions", 1).await;
        let (_, sub) = requests_1707(&seen, "POST", "/namf-evts/v1/subscriptions")[0].clone();
        let event = &sub["subscription"]["eventList"][0];
        assert_eq!(event["type"], "REACHABILITY_REPORT");
        assert_eq!(event["reachabilityFilter"], "UE_REACHABLE_DL_TRAFFIC");
        assert_eq!(sub["subscription"]["supi"], supi);
        assert!(
            sub["subscription"]["options"]["expiry"].is_string(),
            "{sub}"
        );
        let token = reachability_token_1707(&sub, &reference);
        assert_eq!(up_state_1631(&reference), context::UpCnxState::Deactivated);
        assert!(ue_reachability::ue_unreachable_holds(&reference));
        assert!(
            ue_reachability::ue_unreachable_holds(&other),
            "UE-wide: its other session too"
        );

        report_dl_data_1631(seid, 5).await;
        report_dl_data_1631(other_seid, 5).await;
        assert_eq!(transfers_1707(&seen), 1, "step 3a: no page");

        // A repeated indication makes no second record or subscription.
        assert!(
            !ue_reachability::record_ue_unreachable(&reference, true),
            "a repeated indication"
        );
        assert!(
            !ue_reachability::record_ue_unreachable(&other, true),
            "a repeated indication, on another session"
        );

        // Nothing changes on a wrong token, an UNREACHABLE, or a malformed body.
        assert_eq!(
            notify_reachability_1707(&reference, "0123456789abcdef0123456789abcdef", "REACHABLE")
                .await,
            404
        );
        assert_eq!(
            notify_reachability_1707(&reference, &token, "UNREACHABLE").await,
            204
        );
        let malformed = smf_sbi_request_handler(
            SbiRequest::post(format!(
                "/nsmf-callback/v1/{reference}/ue-reachability/{token}"
            ))
            .with_body("{}".to_string(), "application/json"),
        )
        .await;
        assert_eq!(malformed.status, 400);
        assert!(
            ue_reachability::ue_unreachable_holds(&reference),
            "still held"
        );

        assert_eq!(
            notify_reachability_1707(&reference, &token, "REACHABLE").await,
            204
        );
        report_dl_data_1631(other_seid, 5).await;
        assert_eq!(transfers_1707(&seen), 2, "REACHABLE: a report pages again");
        await_requests_1707(&seen, "DELETE", "/namf-evts/v1/subscriptions/sub-1707-0", 1).await;

        // The same notification again: its token is gone, and nothing is undone twice.
        assert_eq!(
            notify_reachability_1707(&reference, &token, "REACHABLE").await,
            404
        );
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        assert_eq!(requests_1707(&seen, "DELETE", "/namf-evts/").len(), 1);
        assert_eq!(requests_1707(&seen, "POST", "/namf-evts/").len(), 1);

        drop_session_for_retry(&reference);
        drop_session_for_retry(&other);
        amf.stop().await.expect("stop");
    }

    /// #1707: UE_NOT_REACHABLE_FOR_SESSION in a failure notification names the
    /// non-3GPP session (TS 29.518 Table 6.1.6.3.x), so that session is held and the
    /// UE's other one still pages. UE_NOT_RESPONDING, as a notification or as the 504
    /// cause, says nothing of reachability, and records nothing. The UE's user plane
    /// being activated ends the record, and deletes the subscription.
    ///
    /// REVERT-VERIFIED: with the failure notification recording UE-wide, "the other
    /// session still pages" fails; with every 504 cause read as UE_NOT_REACHABLE,
    /// "UE_NOT_RESPONDING holds nothing" fails; with `mark_up_cnx_state` not clearing,
    /// "an activation ends it" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_session_unreachable_record_holds_that_session_until_the_ue_activates_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (amf, port, seen) = reachability_amf_1707(vec![
            attempting_1631(),
            (
                504,
                serde_json::json!({ "error": { "status": 504, "cause": "UE_NOT_RESPONDING" } }),
            ),
            attempting_1631(),
        ])
        .await;
        let supi = "imsi-001010000170702";
        let (n3gpp, n3gpp_seid) = seed_paged_session_1631(supi, 5, port);
        let (other, other_seid) = seed_paged_session_1631(supi, 6, port);

        report_dl_data_1631(n3gpp_seid, 5).await;
        let (_, transfer) = requests_1707(&seen, "POST", "/n1-n2-messages")[0].clone();
        let failure_token = failure_token_1631(&transfer, &n3gpp);
        assert_eq!(
            notify_failure_1631(
                &n3gpp,
                &failure_token,
                serde_json::json!({
                    "cause": "UE_NOT_REACHABLE_FOR_SESSION",
                    "n1n2MsgDataUri": "http:",
                }),
            )
            .await,
            204
        );
        await_requests_1707(&seen, "POST", "/namf-evts/v1/subscriptions", 1).await;
        assert!(ue_reachability::ue_unreachable_holds(&n3gpp));
        report_dl_data_1631(n3gpp_seid, 5).await;
        assert_eq!(transfers_1707(&seen), 1, "the session is held");

        // The other session pages; its 504 UE_NOT_RESPONDING records nothing.
        report_dl_data_1631(other_seid, 5).await;
        assert_eq!(transfers_1707(&seen), 2, "the other session still pages");
        report_dl_data_1631(other_seid, 5).await;
        assert_eq!(transfers_1707(&seen), 3, "UE_NOT_RESPONDING holds nothing");
        assert_eq!(requests_1707(&seen, "POST", "/namf-evts/").len(), 1);

        // The UE answers the other session's paging: it is reachable.
        mark_up_cnx_state(&other, context::UpCnxState::Activating);
        assert!(
            !ue_reachability::ue_unreachable_holds(&n3gpp),
            "an activation ends it"
        );
        await_requests_1707(&seen, "DELETE", "/namf-evts/v1/subscriptions/sub-1707-0", 1).await;

        drop_session_for_retry(&n3gpp);
        drop_session_for_retry(&other);
        amf.stop().await.expect("stop");
    }

    /// #1707, step 3c's policy toward the UPF and its undo:
    /// - `stop-notifications` sets the downlink FAR to BUFF without NOCP;
    /// - REACHABLE re-arms it to BUFF|NOCP;
    /// - `discard` sets it to DROP;
    /// - the hold running out ends the record as REACHABLE does: re-armed, the
    ///   subscription deleted.
    ///
    /// REVERT-VERIFIED: with `undo` not restoring the FAR, "re-armed on REACHABLE"
    /// fails; with the hold not taking the record, "the hold ends it" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn the_step_3c_upf_policy_is_applied_and_undone_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (upf, mods, upf_task) = modification_recording_upf_1387().await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        let far_actions = |mods: &Arc<std::sync::Mutex<Vec<Vec<u8>>>>| -> Vec<u16> {
            mods.lock()
                .unwrap()
                .iter()
                .filter_map(|body| {
                    let far = pfcp_path::find_ie(body, n4_build::pfcp_ie::UPDATE_FAR)?;
                    let aa = pfcp_path::find_ie(far, n4_build::pfcp_ie::APPLY_ACTION)?;
                    Some(n4_build::decode_apply_action(aa))
                })
                .collect()
        };
        let report = |seid: u64| async move {
            let sock = tokio::net::UdpSocket::bind("127.0.0.1:0")
                .await
                .expect("sock");
            handle_pfcp_session_report(&sock, &dldr_report_packet(seid, 5), upf).await;
        };
        let await_far = |n: usize, what: &'static str| {
            let mods = mods.clone();
            async move {
                let ok = nextgcore_sbi::test_support::poll_until(
                    std::time::Duration::from_secs(5),
                    std::time::Duration::from_millis(10),
                    || async { (far_actions(&mods).len() >= n).then_some(()) },
                )
                .await;
                assert!(
                    ok.is_some(),
                    "{what}: {n} FAR updates: {:?}",
                    far_actions(&mods)
                );
            }
        };
        let bind_upf = |reference: &str, upf_seid: u64| {
            let ctx = smf_self();
            let ctx = ctx.read().expect("ctx");
            ctx.pfcp_sessions
                .write()
                .expect("w")
                .insert(reference.to_string(), upf_seid);
        };
        use n4_build::apply_action as aa;

        // stop-notifications, ended by REACHABLE.
        *ue_reachability::TEST_OVERRIDES.lock().unwrap() =
            (Some(ue_reachability::UpfPolicy::StopNotifications), None);
        let (amf, port, seen) = reachability_amf_1707(vec![not_reachable_1707()]).await;
        let (reference, seid) = seed_paged_session_1631("imsi-001010000170703", 5, port);
        bind_upf(&reference, 0x1707_0003);
        report(seid).await;
        await_far(1, "the policy").await;
        assert_eq!(
            far_actions(&mods),
            vec![aa::BUFF],
            "stop Data Notifications"
        );
        await_requests_1707(&seen, "POST", "/namf-evts/v1/subscriptions", 1).await;
        let (_, sub) = requests_1707(&seen, "POST", "/namf-evts/v1/subscriptions")[0].clone();
        let token = reachability_token_1707(&sub, &reference);
        assert_eq!(
            notify_reachability_1707(&reference, &token, "REACHABLE").await,
            204
        );
        await_far(2, "re-armed on REACHABLE").await;
        assert_eq!(
            far_actions(&mods)[1],
            aa::BUFF | aa::NOCP,
            "re-armed on REACHABLE"
        );
        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");

        // discard, ended by the hold.
        mods.lock().unwrap().clear();
        *ue_reachability::TEST_OVERRIDES.lock().unwrap() = (
            Some(ue_reachability::UpfPolicy::Discard),
            Some(std::time::Duration::from_millis(300)),
        );
        let (amf, port, seen) = reachability_amf_1707(vec![not_reachable_1707()]).await;
        let (reference, seid) = seed_paged_session_1631("imsi-001010000170704", 5, port);
        bind_upf(&reference, 0x1707_0004);
        report(seid).await;
        await_far(1, "the policy").await;
        assert_eq!(
            far_actions(&mods),
            vec![aa::DROP],
            "discard the buffered data"
        );
        assert!(ue_reachability::ue_unreachable_holds(&reference));
        await_far(2, "the hold ends it").await;
        assert_eq!(far_actions(&mods)[1], aa::BUFF | aa::NOCP);
        assert!(
            !ue_reachability::ue_unreachable_holds(&reference),
            "the hold ends it"
        );
        await_requests_1707(&seen, "DELETE", "/namf-evts/v1/subscriptions/sub-1707-0", 1).await;

        *ue_reachability::TEST_OVERRIDES.lock().unwrap() = (None, None);
        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");
        pfcp_path::clear_global_upf_for_test();
        listener.abort();
        upf_task.abort();
    }

    // ---- #1773 R13 M1: a late success is cleaned up ----

    /// What the #1707 holding UPF did, in order: `("recv", action)` when a Session
    /// Modification arrived and `("apply", action)` when it answered it, `action`
    /// being the Apply Action of its first Update FAR.
    type UpfLog1707 = Arc<std::sync::Mutex<Vec<(&'static str, u16)>>>;

    /// A stand-in UPF for #1773 R13 M1 that APPLIES a Session Modification when it
    /// answers it, as the FAR state the UPF ends at is the one it answered last. It
    /// answers at once, except a modification whose Update FAR sets `held`, which it
    /// answers only once `release` is notified. A retransmission is ignored.
    async fn holding_upf_1707(
        held: u16,
    ) -> (
        std::net::SocketAddr,
        UpfLog1707,
        Arc<tokio::sync::Notify>,
        tokio::task::JoinHandle<()>,
    ) {
        use pfcp_path::pfcp_message_type as t;
        let upf = Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let addr = upf.local_addr().unwrap();
        let log: UpfLog1707 = Arc::default();
        let release = Arc::new(tokio::sync::Notify::new());
        let (sink, gate) = (log.clone(), release.clone());
        let task = tokio::spawn(async move {
            let mut buf = vec![0u8; 4096];
            let mut seen = std::collections::HashSet::new();
            while let Ok((len, from)) = upf.recv_from(&mut buf).await {
                let Some(h) = pfcp_path::parse_wire_header(&buf[..len]) else {
                    continue;
                };
                if h.msg_type != t::SESSION_MODIFICATION_REQUEST || !seen.insert(h.sequence_number)
                {
                    continue;
                }
                let body = &buf[h.body_offset..len];
                let action = pfcp_path::find_ie(body, n4_build::pfcp_ie::UPDATE_FAR)
                    .and_then(|far| pfcp_path::find_ie(far, n4_build::pfcp_ie::APPLY_ACTION))
                    .map_or(0, n4_build::decode_apply_action);
                sink.lock().unwrap().push(("recv", action));
                let reply = pfcp_path::encode_wire_message(
                    t::SESSION_MODIFICATION_RESPONSE,
                    Some(h.seid),
                    h.sequence_number,
                    &[0x00, 0x13, 0x00, 0x01, 1],
                );
                let (upf, sink, gate) = (upf.clone(), sink.clone(), gate.clone());
                tokio::spawn(async move {
                    if action == held {
                        gate.notified().await;
                    }
                    sink.lock().unwrap().push(("apply", action));
                    let _ = upf.send_to(&reply, from).await;
                });
            }
        });
        (addr, log, release, task)
    }

    fn upf_log_1707(log: &UpfLog1707, what: &str) -> Vec<u16> {
        log.lock()
            .unwrap()
            .iter()
            .filter(|(w, _)| *w == what)
            .map(|(_, a)| *a)
            .collect()
    }

    async fn await_upf_1707(log: &UpfLog1707, what: &str, action: u16, why: &str) {
        let ok = nextgcore_sbi::test_support::poll_until(
            std::time::Duration::from_secs(5),
            std::time::Duration::from_millis(5),
            || async { upf_log_1707(log, what).contains(&action).then_some(()) },
        )
        .await;
        assert!(ok.is_some(), "{why}: {:?}", log.lock().unwrap());
    }

    /// A Downlink Data Report for `seid` through the real PFCP Session Report path,
    /// from `upf`, whose client the caller installed.
    async fn report_from_1707(seid: u64, upf: std::net::SocketAddr) {
        let sock = tokio::net::UdpSocket::bind("127.0.0.1:0")
            .await
            .expect("sock");
        handle_pfcp_session_report(&sock, &dldr_report_packet(seid, 5), upf).await;
    }

    fn bind_upf_1707(reference: &str, upf_seid: u64) {
        let ctx = smf_self();
        let ctx = ctx.read().expect("ctx");
        ctx.pfcp_sessions
            .write()
            .expect("w")
            .insert(reference.to_string(), upf_seid);
    }

    fn record_token_1707(reference: &str) -> String {
        lookup_policy_binding(reference)
            .and_then(|b| b.ue_unreachable)
            .expect("a record")
            .notify_token
            .as_str()
            .to_string()
    }

    /// #1773 R13 M1(a): a conformant AMF sends the immediate REACHABLE report for a
    /// UE reachable at subscription time BEFORE it answers the subscription 201
    /// (TS 29.518 §5.3.1, `29518-k00.txt:5074-5080`; amfd #1641). The record is then
    /// cleared before the SMF learns the subscriptionId, so the late 201's
    /// subscription is deleted, and nothing holds.
    ///
    /// REVERT-VERIFIED: with `establish` not unsubscribing when `update_record` fails
    /// after the 201, "the late 201's subscription is deleted" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_201_after_the_immediate_reachable_is_unsubscribed_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (amf, port, seen) = reachability_amf_with_1707(vec![not_reachable_1707()], true).await;
        let (reference, seid) = seed_paged_session_1631("imsi-001010000170705", 5, port);

        report_dl_data_1631(seid, 5).await;
        await_requests_1707(&seen, "NOTIFY", "/ue-reachability/", 1).await;
        let (_, status) = requests_1707(&seen, "NOTIFY", "/ue-reachability/")[0].clone();
        assert_eq!(status, 204, "the immediate REACHABLE is admitted");
        let ok = nextgcore_sbi::test_support::poll_until(
            std::time::Duration::from_secs(5),
            std::time::Duration::from_millis(10),
            || async {
                (!requests_1707(&seen, "DELETE", "/namf-evts/v1/subscriptions/sub-late").is_empty())
                    .then_some(())
            },
        )
        .await;
        assert!(
            ok.is_some(),
            "the late 201's subscription is deleted: {:?}",
            seen.lock().unwrap()
        );
        assert!(!ue_reachability::ue_unreachable_holds(&reference));

        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");
    }

    /// #1773 R13 M1(b): the UPF takes the step 3c DROP only after the record was
    /// cleared (REACHABLE arrived within the PFCP round trip). `establish` then puts
    /// the FAR back to BUFF|NOCP, so a DEACTIVATED session with no record is not left
    /// silently discarding its downlink, and it subscribes to nothing.
    ///
    /// REVERT-VERIFIED: with `establish` not calling `restore_far_locked` when
    /// `update_record` fails after the UPF's answer, "a late FAR change is restored"
    /// fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_far_change_the_upf_takes_after_reachable_is_restored_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        use n4_build::apply_action as aa;
        let (upf, log, release, upf_task) = holding_upf_1707(aa::DROP).await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        *ue_reachability::TEST_OVERRIDES.lock().unwrap() =
            (Some(ue_reachability::UpfPolicy::Discard), None);
        let (amf, port, seen) = reachability_amf_1707(vec![not_reachable_1707()]).await;
        let (reference, seid) = seed_paged_session_1631("imsi-001010000170706", 5, port);
        bind_upf_1707(&reference, 0x1707_0006);

        report_from_1707(seid, upf).await;
        await_upf_1707(&log, "recv", aa::DROP, "the policy is in flight").await;
        let token = record_token_1707(&reference);
        assert_eq!(
            notify_reachability_1707(&reference, &token, "REACHABLE").await,
            204
        );
        assert!(!ue_reachability::ue_unreachable_holds(&reference));
        release.notify_one();
        await_upf_1707(
            &log,
            "apply",
            aa::BUFF | aa::NOCP,
            "a late FAR change is restored",
        )
        .await;
        assert_eq!(
            upf_log_1707(&log, "apply"),
            vec![aa::DROP, aa::BUFF | aa::NOCP],
            "a late FAR change is restored"
        );
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        assert!(
            requests_1707(&seen, "POST", "/namf-evts/").is_empty(),
            "a cleared record subscribes to nothing"
        );

        *ue_reachability::TEST_OVERRIDES.lock().unwrap() = (None, None);
        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");
        pfcp_path::clear_global_upf_for_test();
        listener.abort();
        upf_task.abort();
    }

    /// The #1773 R13 M1(c) set-up: a session the AMF reported unreachable under the
    /// `discard` policy, whose step 3c DROP the holding UPF has received and holds.
    /// Returns what the test needs, the caller holding the ambient and N4 locks.
    async fn a_drop_in_flight_1707(
        supi: &str,
        upf_seid: u64,
    ) -> (
        String,
        UpfLog1707,
        Arc<tokio::sync::Notify>,
        nextgcore_sbi::server::SbiServer,
        Vec<tokio::task::JoinHandle<()>>,
    ) {
        use n4_build::apply_action as aa;
        let (upf, log, release, upf_task) = holding_upf_1707(aa::DROP).await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        *ue_reachability::TEST_OVERRIDES.lock().unwrap() =
            (Some(ue_reachability::UpfPolicy::Discard), None);
        let (amf, port, _seen) = reachability_amf_1707(vec![not_reachable_1707()]).await;
        let (reference, seid) = seed_paged_session_1631(supi, 5, port);
        bind_upf_1707(&reference, upf_seid);
        report_from_1707(seid, upf).await;
        await_upf_1707(&log, "recv", aa::DROP, "the policy is in flight").await;
        (reference, log, release, amf, vec![listener, upf_task])
    }

    /// The activation's FORW lands after the step 3c DROP in flight: it is SENT only
    /// once the UPF answered the DROP, so the FAR ends at FORW.
    async fn assert_forw_lands_last_1707(
        log: &UpfLog1707,
        release: &tokio::sync::Notify,
        activation: tokio::task::JoinHandle<SbiResponse>,
    ) {
        use n4_build::apply_action as aa;
        // The activation runs meanwhile, on another worker.
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        release.notify_one();
        let resp = tokio::time::timeout(std::time::Duration::from_secs(10), activation)
            .await
            .expect("the activation completes")
            .expect("joins");
        assert_eq!(resp.status, 200, "{:?}", resp.http.content);
        await_upf_1707(log, "apply", aa::FORW, "the activation").await;
        assert_eq!(
            upf_log_1707(log, "apply").last(),
            Some(&aa::FORW),
            "the activation's FORW lands last: {:?}",
            log.lock().unwrap()
        );
    }

    async fn end_drop_in_flight_1707(
        reference: &str,
        amf: nextgcore_sbi::server::SbiServer,
        tasks: Vec<tokio::task::JoinHandle<()>>,
    ) {
        *ue_reachability::TEST_OVERRIDES.lock().unwrap() = (None, None);
        drop_session_for_retry(reference);
        amf.stop().await.expect("stop");
        pfcp_path::clear_global_upf_for_test();
        for t in tasks {
            t.abort();
        }
    }

    /// #1773 R13 M1(c), `pfcp_session_modify`: the gNB's PDU_RES_SETUP_RSP arrives
    /// while the step 3c DROP is in flight. Its FORW waits on `dl_far_locks`, so it
    /// cannot land before the DROP and then be overwritten by it on an ACTIVE session.
    ///
    /// REVERT-VERIFIED: with `pfcp_session_modify` not taking its `dl_far_locks`
    /// entry, "the activation's FORW lands last" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn an_activation_s_forw_lands_after_a_drop_in_flight_1707() {
        use base64::Engine as _;
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (reference, log, release, amf, tasks) =
            a_drop_in_flight_1707("imsi-001010000170707", 0x1707_0007).await;

        let setup_rsp = serde_json::json!({
            "n2SmInfoType": "PDU_RES_SETUP_RSP",
            "n2SmInfo": base64::engine::general_purpose::STANDARD.encode(GNB_SETUP_RESPONSE_TRANSFER),
        })
        .to_string();
        let r = reference.clone();
        let activation = tokio::spawn(async move {
            handle_sm_context_update(
                &r,
                &SbiRequest::post("/x/modify").with_body(setup_rsp, "application/json"),
            )
            .await
        });
        assert_forw_lands_last_1707(&log, &release, activation).await;

        end_drop_in_flight_1707(&reference, amf, tasks).await;
    }

    /// #1773 R13 M1(c), `split_pdu_session_modification`: a Service Request marks the
    /// session ACTIVATING, then a Modify Indication for a split session (one with
    /// additional NG-U tunnel FARs) arrives while the step 3c DROP is in flight. Its
    /// FORW waits on `dl_far_locks` too.
    ///
    /// REVERT-VERIFIED: with `split_pdu_session_modification` not taking its
    /// `dl_far_locks` entry, "the activation's FORW lands last" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_split_modification_s_forw_lands_after_a_drop_in_flight_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (reference, log, release, amf, tasks) =
            a_drop_in_flight_1707("imsi-001010000170708", 0x1707_0008).await;
        if let Ok(ctx) = smf_self().read() {
            let mut sess = ctx.sess_find_by_sm_context_ref(&reference).expect("sess");
            sess.dc_tunnel_fars = vec![DC_TUNNEL_FAR_BASE + 1];
            ctx.sess_update(&sess);
        }
        mark_up_cnx_state(&reference, context::UpCnxState::Activating);

        let r = reference.clone();
        let activation = tokio::spawn(async move {
            an_initiated_modification(&r, &indication([10, 1, 7, 8], 0x1707, &[5])).await
        });
        assert_forw_lands_last_1707(&log, &release, activation).await;

        end_drop_in_flight_1707(&reference, amf, tasks).await;
    }

    /// #1773 R13 m1: an `undo` that waited on `dl_far_locks` while a NEWER record's
    /// `establish` took the lock first and set DROP is stale: it re-checks under the
    /// lock and leaves the newer record's FAR alone. The newer record's own end then
    /// re-arms it.
    ///
    /// REVERT-VERIFIED: with `restore_far_locked` not re-checking for a newer record's
    /// action, "a stale undo leaves the newer record's DROP" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_stale_undo_leaves_a_newer_record_s_far_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        use n4_build::apply_action as aa;
        let (upf, log, _release, upf_task) = holding_upf_1707(u16::MAX).await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        *ue_reachability::TEST_OVERRIDES.lock().unwrap() =
            (Some(ue_reachability::UpfPolicy::Discard), None);
        let (amf, port, _seen) = reachability_amf_1707(vec![not_reachable_1707()]).await;
        let (reference, seid) = seed_paged_session_1631("imsi-001010000170709", 5, port);
        bind_upf_1707(&reference, 0x1707_0009);

        // The newer record: its DROP applied.
        report_from_1707(seid, upf).await;
        await_upf_1707(&log, "apply", aa::DROP, "the newer record's policy").await;
        let ok = nextgcore_sbi::test_support::poll_until(
            std::time::Duration::from_secs(5),
            std::time::Duration::from_millis(5),
            || async {
                lookup_policy_binding(&reference)
                    .and_then(|b| b.ue_unreachable)
                    .and_then(|u| u.upf_action)
                    .map(|_| ())
            },
        )
        .await;
        assert!(ok.is_some(), "the newer record holds its DROP");

        // The older record's undo, reaching the lock only now.
        let mut stale = lookup_policy_binding(&reference)
            .and_then(|b| b.ue_unreachable)
            .expect("record");
        stale.notify_token = nextgcore_sbi::callback_auth::CallbackToken::mint();
        stale.subscription_id = None;
        ue_reachability::undo(reference.clone(), stale).await;
        assert_eq!(
            upf_log_1707(&log, "recv"),
            vec![aa::DROP],
            "a stale undo leaves the newer record's DROP"
        );

        // The newer record's own end re-arms it.
        let token = record_token_1707(&reference);
        assert_eq!(
            notify_reachability_1707(&reference, &token, "REACHABLE").await,
            204
        );
        await_upf_1707(&log, "apply", aa::BUFF | aa::NOCP, "its own end re-arms").await;

        *ue_reachability::TEST_OVERRIDES.lock().unwrap() = (None, None);
        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");
        pfcp_path::clear_global_upf_for_test();
        listener.abort();
        upf_task.abort();
    }

    /// #1773 R13 m4: a record that ends stops its hold task at once, rather than
    /// leaving it to sleep out `SMF_UE_UNREACHABLE_HOLD_SECS` (3600 s by default).
    ///
    /// REVERT-VERIFIED: with the hold a plain sleep (no `select!` on the record's
    /// end), "the hold ends with its record" fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_hold_ends_with_its_record_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        let (amf, port, seen) = reachability_amf_1707(vec![not_reachable_1707()]).await;
        let (reference, seid) = seed_paged_session_1631("imsi-001010000170710", 5, port);

        report_dl_data_1631(seid, 5).await;
        await_requests_1707(&seen, "POST", "/namf-evts/v1/subscriptions", 1).await;
        let token = record_token_1707(&reference);
        let running = |want: bool| {
            let token = token.clone();
            async move {
                nextgcore_sbi::test_support::poll_until(
                    std::time::Duration::from_secs(5),
                    std::time::Duration::from_millis(5),
                    || async { (ue_reachability::hold_running(&token) == want).then_some(()) },
                )
                .await
                .is_some()
            }
        };
        assert!(running(true).await, "the hold runs");
        assert_eq!(
            notify_reachability_1707(&reference, &token, "REACHABLE").await,
            204
        );
        assert!(running(false).await, "the hold ends with its record");
        await_requests_1707(&seen, "DELETE", "/namf-evts/v1/subscriptions/sub-1707-0", 1).await;

        drop_session_for_retry(&reference);
        amf.stop().await.expect("stop");
    }

    /// #1707: the default policy, `refrain`, changes no FAR; an unknown value falls
    /// back to it; the step's second and third options are one Apply Action (DROP),
    /// since NOCP needs BUFF (TS 29.244 §8.2.26, `29244-k00.txt:30338`).
    #[test]
    fn the_step_3c_policy_values_1707() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.blocking_lock();
        use ue_reachability::UpfPolicy;
        assert_eq!(ue_reachability::upf_policy(), UpfPolicy::Refrain);
        for (value, policy) in [
            ("refrain", UpfPolicy::Refrain),
            ("stop-notifications", UpfPolicy::StopNotifications),
            ("discard", UpfPolicy::Discard),
            ("stop-notifications-and-discard", UpfPolicy::Discard),
            ("maybe", UpfPolicy::Refrain),
        ] {
            std::env::set_var("SMF_UE_UNREACHABLE_UPF_POLICY", value);
            assert_eq!(ue_reachability::upf_policy(), policy, "{value}");
        }
        std::env::remove_var("SMF_UE_UNREACHABLE_UPF_POLICY");
    }

    // ---- #1387: an SM policy UpdateNotify is a DELTA over what the session enforces ----

    /// A stub UPF that records each Session Modification Request body and accepts it.
    async fn modification_recording_upf_1387() -> (
        std::net::SocketAddr,
        std::sync::Arc<std::sync::Mutex<Vec<Vec<u8>>>>,
        tokio::task::JoinHandle<()>,
    ) {
        modification_recording_upf_delayed_1387(std::time::Duration::ZERO).await
    }

    /// [`modification_recording_upf_1387`], answering each request after `delay` on its
    /// own task, so two modifications can be in flight together.
    async fn modification_recording_upf_delayed_1387(
        delay: std::time::Duration,
    ) -> (
        std::net::SocketAddr,
        std::sync::Arc<std::sync::Mutex<Vec<Vec<u8>>>>,
        tokio::task::JoinHandle<()>,
    ) {
        use pfcp_path::pfcp_message_type as t;
        let upf = Arc::new(tokio::net::UdpSocket::bind("127.0.0.1:0").await.unwrap());
        let addr = upf.local_addr().unwrap();
        let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let task = tokio::spawn(async move {
            let mut buf = vec![0u8; 4096];
            while let Ok((len, from)) = upf.recv_from(&mut buf).await {
                let Some(h) = pfcp_path::parse_wire_header(&buf[..len]) else {
                    continue;
                };
                if h.msg_type != t::SESSION_MODIFICATION_REQUEST {
                    continue;
                }
                sink.lock().unwrap().push(buf[h.body_offset..len].to_vec());
                // Cause (IE 19) 1, Request accepted.
                let reply = pfcp_path::encode_wire_message(
                    t::SESSION_MODIFICATION_RESPONSE,
                    Some(h.seid),
                    h.sequence_number,
                    &[0x00, 0x13, 0x00, 0x01, 1],
                );
                let upf = upf.clone();
                tokio::spawn(async move {
                    tokio::time::sleep(delay).await;
                    let _ = upf.send_to(&reply, from).await;
                });
            }
        });
        (addr, seen, task)
    }

    /// The session's `session_ambr` (what Retrieve and the EPS/GTP-C encoders read) and
    /// the APN-AMBR an Update Bearer Request built from it carries, in kbit/s
    /// (TS 29.274 §8.7).
    fn session_and_eps_ambr_1387(sm_context_ref: &str) -> ((u64, u64), (u32, u32)) {
        let sess = smf_self()
            .read()
            .expect("context")
            .sess_find_by_sm_context_ref(sm_context_ref)
            .expect("session");
        let bearer = context::SmfBearer::new(1, sess.id);
        let msg = gtp_build::build_update_bearer_request(&sess, &bearer, None, None, false);
        let mut bytes = bytes::Bytes::from(msg);
        let m = nextgcore_gtp::v2::Gtp2Message::decode(&mut bytes).expect("decode");
        let ambr = m
            .get_ie(nextgcore_gtp::v2::Gtp2IeType::Ambr as u8, 0)
            .expect("APN-AMBR")
            .value
            .to_vec();
        let be = |b: &[u8]| u32::from_be_bytes([b[0], b[1], b[2], b[3]]);
        (
            (sess.session_ambr.uplink, sess.session_ambr.downlink),
            (be(&ambr[..4]), be(&ambr[4..8])),
        )
    }

    /// The (UL, DL) MBR, in bit/s, of the Update QER in a Session Modification body
    /// (TS 29.244 §7.5.4.4 Update QER, §8.2.8 MBR in kbit/s, 5 octets each).
    fn updated_qer_mbr_1387(body: &[u8]) -> Option<(u64, u64)> {
        let qer = pfcp_path::find_ie(body, n4_build::pfcp_ie::UPDATE_QER)?;
        let mbr = pfcp_path::find_ie(qer, n4_build::pfcp_ie::MBR)?;
        let kbps = |b: &[u8]| b.iter().fold(0u64, |a, x| (a << 8) | u64::from(*x)) * 1000;
        (mbr.len() == 10).then(|| (kbps(&mbr[..5]), kbps(&mbr[5..])))
    }

    /// The session the #1387 tests notify: PCF-authorised, with a UPF session, and
    /// holding a Session-AMBR (30/70 Mbps) and default 5QI (6) that are ALL different
    /// from the config default (100/100 Mbps, 5QI 9) -- so a reset to it is visible.
    fn seed_notified_session_1387(supi: &str, psi: u8, upf_seid: u64) -> String {
        let sm_context_ref = seed_pcf_authorised(supi, psi, "pol-1387");
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut(&sm_context_ref) {
                    b.ambr_ul_bps = 30_000_000;
                    b.ambr_dl_bps = 70_000_000;
                    b.five_qi = 6;
                }
            }
            if let Ok(mut sessions) = ctx.pfcp_sessions.write() {
                sessions.insert(sm_context_ref.clone(), upf_seid);
            }
        }
        sm_context_ref
    }

    fn policy_notify_1387(sm_context_ref: &str, decision: serde_json::Value) -> SbiRequest {
        SbiRequest::post(sm_policy_notify_path(sm_context_ref, "update")).with_body(
            serde_json::json!({
                "resourceUri": "http://pcf/npcf-smpolicycontrol/v1/sm-policies/pol-1387",
                "smPolicyDecision": decision,
            })
            .to_string(),
            "application/json",
        )
    }

    /// The (UL, DL, 5QI) the binding holds: what the update, release and the durable
    /// snapshot (#191) read.
    fn enforced_1387(sm_context_ref: &str) -> (u64, u64, u8) {
        let b = lookup_policy_binding(sm_context_ref).expect("binding");
        (b.ambr_ul_bps, b.ambr_dl_bps, b.five_qi)
    }

    /// #1387 criteria 1-3, through the real SBI router and a stub UPF: each
    /// UpdateNotify is applied as the TS 29.512 §4.2.6.1 delta it is.
    ///
    /// 1. Only `pccRules`: Session-AMBR and 5QI unchanged, on the QER and the binding.
    /// 2. A changed `sessRules` AMBR only: the AMBR changes, the 5QI does not.
    /// 3. `null` members: a removed PCC rule and a removed session rule change
    ///    nothing; a removed rule plus its replacement enforces the replacement, even
    ///    with the `null` entry first in the map.
    ///
    /// REVERT-VERIFIED: with the handler on `parse_sm_policy_decision` again, step 1
    /// fails `left: (100000000, 100000000, 9) right: (30000000, 70000000, 6)`; with
    /// `values().next()` in place of the non-null find, step 3's replacement fails.
    #[tokio::test]
    async fn an_sm_policy_update_notify_is_applied_as_a_delta_1387() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let (upf, seen, upf_task) = modification_recording_upf_1387().await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        let sm_context_ref = seed_notified_session_1387("imsi-001010000001387", 21, 0x1387);

        let notify = |decision: serde_json::Value| {
            let reference = sm_context_ref.clone();
            let seen = seen.clone();
            async move {
                seen.lock().unwrap().clear();
                let status = smf_sbi_request_handler(policy_notify_1387(&reference, decision))
                    .await
                    .status;
                assert_eq!(status, 204);
                let bodies = seen.lock().unwrap().clone();
                assert_eq!(bodies.len(), 1, "one QER Session Modification");
                updated_qer_mbr_1387(&bodies[0]).expect("Update QER with an MBR")
            }
        };

        // 1. Only pccRules (an AF / TSC decision): nothing session-level changes.
        let qer = notify(serde_json::json!({
            "pccRules": { "PccRule-af-1": {
                "pccRuleId": "PccRule-af-1", "precedence": 10,
                "flowInfos": [{ "flowDescription": "permit out ip from any to assigned" }],
                "refQosData": ["QosDec-af-1"],
            }},
            "qosDecs": { "QosDec-af-1": { "qosId": "QosDec-af-1", "5qi": 1 } },
        }))
        .await;
        assert_eq!(
            enforced_1387(&sm_context_ref),
            (30_000_000, 70_000_000, 6),
            "a notify carrying only PCC rules must leave the session's Session-AMBR and \
             5QI as they were, not reset them to the config default"
        );
        assert_eq!(
            qer,
            (30_000_000, 70_000_000),
            "and the QER keeps enforcing that AMBR"
        );
        assert_eq!(
            session_and_eps_ambr_1387(&sm_context_ref),
            ((30_000_000, 70_000_000), (30_000, 70_000)),
            "the session, and the EPS encoder reading it, hold the enforced AMBR"
        );

        // 2. A changed session rule, AMBR only: only the AMBR changes.
        let qer = notify(serde_json::json!({
            "sessRules": { "SessRule-pol-1387": {
                "sessRuleId": "SessRule-pol-1387",
                "authSessAmbr": { "uplink": "40 Mbps", "downlink": "80 Mbps" },
            }},
        }))
        .await;
        assert_eq!(
            enforced_1387(&sm_context_ref),
            (40_000_000, 80_000_000, 6),
            "a session rule that modifies only authSessAmbr leaves the default 5QI \
             (TS 29.512 §4.2.6.3.1: unsupplied attributes remain valid)"
        );
        assert_eq!(qer, (40_000_000, 80_000_000));
        assert_eq!(
            session_and_eps_ambr_1387(&sm_context_ref),
            ((40_000_000, 80_000_000), (40_000, 80_000)),
            "a PCF-changed AMBR reaches the session, so an EPS move carries it"
        );

        // 3a. A removed PCC rule changes nothing session-level.
        notify(serde_json::json!({ "pccRules": { "PccRule-af-1": null } })).await;
        assert_eq!(enforced_1387(&sm_context_ref), (40_000_000, 80_000_000, 6));

        // 3b. A removed session rule with no replacement: removed, not read as a rule
        // and not replaced by the config default.
        let qer = notify(serde_json::json!({ "sessRules": { "SessRule-pol-1387": null } })).await;
        assert_eq!(
            enforced_1387(&sm_context_ref),
            (40_000_000, 80_000_000, 6),
            "a null session rule is a removal and carries no values"
        );
        assert_eq!(qer, (40_000_000, 80_000_000));

        // 3c. A removal plus its replacement, the null FIRST in the map: the
        // replacement is enforced.
        let qer = notify(serde_json::json!({
            "sessRules": {
                "A-SessRule-old": null,
                "B-SessRule-new": {
                    "sessRuleId": "B-SessRule-new",
                    "authSessAmbr": { "uplink": "50 Mbps", "downlink": "90 Mbps" },
                    "authDefQos": { "5qi": 7, "arp": { "priorityLevel": 5 } },
                },
            },
        }))
        .await;
        assert_eq!(
            enforced_1387(&sm_context_ref),
            (50_000_000, 90_000_000, 7),
            "the replacing session rule is enforced, whichever order the map has"
        );
        assert_eq!(qer, (50_000_000, 90_000_000));
        assert_eq!(
            lookup_policy_binding(&sm_context_ref)
                .expect("binding")
                .arp_priority_level,
            5,
            "the merged ARP is written back (TS 29.512 §4.2.6.3.3): a re-activation \
             rebuilds the Setup Request Transfer from it"
        );
        assert_eq!(
            session_and_eps_ambr_1387(&sm_context_ref),
            ((50_000_000, 90_000_000), (50_000, 90_000))
        );

        listener.abort();
        upf_task.abort();
    }

    // ---- #1385: a PCF-changed Session-AMBR / 5QI reaches the UE and the NG-RAN ----

    /// One N1N2MessageTransfer the AMF stand-in received: path, JSON part, N1, N2.
    type N1n2Post = (String, serde_json::Value, Vec<u8>, Vec<u8>);

    /// An AMF stand-in recording every N1N2MessageTransfer with its binary parts. When
    /// `refuse_first` it answers the first one 409 HIGHER_PRIORITY_REQUEST_ONGOING with
    /// `retryAfter` 1 s (TS 29.518 §5.2.2.3.1), as an AMF already paging the UE does;
    /// every other one 200 N1_N2_TRANSFER_INITIATED.
    async fn n1n2_recording_amf_1385(
        refuse_first: bool,
    ) -> (
        nextgcore_sbi::server::SbiServer,
        u16,
        std::sync::Arc<std::sync::Mutex<Vec<N1n2Post>>>,
    ) {
        let posts = std::sync::Arc::new(std::sync::Mutex::new(Vec::<N1n2Post>::new()));
        let sink = posts.clone();
        let (srv, addr) =
            nextgcore_sbi::test_support::sbi_server_on_free_port(move |req: SbiRequest| {
                let sink = sink.clone();
                async move {
                    let part = |id: &str| {
                        req.http
                            .parts
                            .iter()
                            .find(|p| p.content_id.as_deref() == Some(id))
                            .map(|p| p.data.to_vec())
                            .unwrap_or_default()
                    };
                    let body = req
                        .http
                        .content
                        .as_deref()
                        .and_then(|c| serde_json::from_str(c).ok())
                        .unwrap_or(serde_json::Value::Null);
                    let first = {
                        let mut seen = sink.lock().unwrap();
                        seen.push((
                            req.header.uri.clone(),
                            body,
                            part("n1SmMsg"),
                            part("n2SmInfo"),
                        ));
                        seen.len() == 1
                    };
                    if refuse_first && first {
                        return SbiResponse::with_status(409)
                            .with_json_body(&serde_json::json!({
                                "error": { "status": 409, "cause": "HIGHER_PRIORITY_REQUEST_ONGOING" },
                                "errInfo": { "retryAfter": 1 },
                            }))
                            .unwrap();
                    }
                    SbiResponse::with_status(200)
                        .with_json_body(&serde_json::json!({ "cause": "N1_N2_TRANSFER_INITIATED" }))
                        .unwrap()
                }
            })
            .await;
        (srv, addr.port(), posts)
    }

    /// The posts once `n` have arrived (or after 10 s).
    async fn await_n1n2_1385(posts: &std::sync::Mutex<Vec<N1n2Post>>, n: usize) -> Vec<N1n2Post> {
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            let got = posts.lock().unwrap().clone();
            if got.len() >= n || tokio::time::Instant::now() >= deadline {
                return got;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
    }

    /// The posts after a settle window, for absence checks.
    async fn settled_n1n2_1385(posts: &std::sync::Mutex<Vec<N1n2Post>>) -> Vec<N1n2Post> {
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        posts.lock().unwrap().clone()
    }

    fn set_amf_1385(sm_context_ref: &str, amf_port: u16) {
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut(sm_context_ref) {
                    b.sm_context_status_uri =
                        Some(format!("http://127.0.0.1:{amf_port}/sm-status"));
                }
            }
        }
    }

    /// #1398, TS 29.512 §4.2.3.18, through the real SBI router and an AMF stand-in:
    /// a notify with `pcscfRestIndication: true` is acknowledged 204, then:
    /// - the SM Policy Association is terminated;
    /// - the session is released toward the UE with 5GSM #39 "reactivation
    ///   requested" plus the N2 Release Command, under T3592.
    ///
    /// This SMF gives the UE no P-CSCF list it could update, so TS 23.380 leaves it
    /// the release. A retried copy of the notify starts no second release.
    ///
    /// REVERT-VERIFIED: without the `pcscfRestIndication` arm the notify is applied
    /// as an ordinary (empty) policy change. No N1N2 transfer arrives, and the
    /// association keeps its policy id.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_pcscf_restoration_indication_releases_the_session_for_reactivation_1398() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (amf, amf_port, posts) = n1n2_recording_amf_1385(false).await;
        let supi = "imsi-001010000001398";
        let psi = 13;
        let sm_context_ref = seed_pcf_authorised(supi, psi, "pol-1398");
        set_amf_1385(&sm_context_ref, amf_port);
        // #1563: a session whose UP connection is active, so the release carries N2.
        mark_up_cnx_state(&sm_context_ref, context::UpCnxState::Activated);

        let restore = || {
            smf_sbi_request_handler(policy_notify_1387(
                &sm_context_ref,
                serde_json::json!({ "pcscfRestIndication": true }),
            ))
        };
        assert_eq!(restore().await.status, 204, "the SMF acknowledges the PCF");
        let got = await_n1n2_1385(&posts, 1).await;
        assert_eq!(got.len(), 1, "one N1N2MessageTransfer, got {got:?}");
        let (path, body, n1_cmd, n2) = &got[0];
        assert_eq!(
            path,
            &format!("/namf-comm/v1/ue-contexts/{supi}/n1-n2-messages")
        );
        assert_eq!(
            n1_cmd[..5],
            [
                0x2E,
                psi,
                0,
                crate::gsm_build::message_type::PDU_SESSION_RELEASE_COMMAND,
                policy::gsm_cause::REACTIVATION_REQUESTED
            ],
            "5GSM, the PSI, PTI 0 (network-initiated), RELEASE COMMAND, cause #39"
        );
        assert_eq!(
            body["n2InfoContainer"]["smInfo"]["n2InfoContent"]["ngapIeType"],
            "PDU_RES_REL_CMD"
        );
        assert!(
            !n2.is_empty(),
            "the N2 Release Command transfer rides along"
        );
        assert_eq!(
            lookup_policy_binding(&sm_context_ref).and_then(|b| b.sm_policy_id),
            None,
            "the SM Policy Association is terminated"
        );

        // A retried copy (TS 29.500 §6.10): acknowledged, and no second release,
        // because the first took the policy id that starting one needs.
        assert_eq!(restore().await.status, 204);
        let binding = lookup_policy_binding(&sm_context_ref).expect("binding");
        assert!(
            !restore_pcscf(&sm_context_ref, &binding),
            "a second restoration starts nothing"
        );

        assert!(
            cancel_gsm_timer_for_test(&sm_context_ref),
            "T3592 guards the release"
        );
        amf.stop().await.ok();
    }

    /// The N2 transfer's (Session-AMBR DL/UL, the default flow's (QFI, 5QI, ARP PL)).
    fn decode_modify_transfer_1385(n2: &[u8]) -> ((u64, u64), Vec<(u8, u16, u8)>) {
        use nextgcore_ngap::transfer::{
            PduSessionResourceModifyRequestTransfer, QosCharacteristics,
        };
        let t = PduSessionResourceModifyRequestTransfer::decode(n2).expect("N2 decodes");
        let ambr = t
            .pdu_session_aggregate_maximum_bit_rate
            .map(|a| (a.dl, a.ul))
            .expect("Session-AMBR");
        let flows = t
            .qos_flow_add_or_modify_request_list
            .iter()
            .map(|i| {
                let q = i
                    .qos_flow_level_qos_parameters
                    .as_ref()
                    .expect("the modified flow carries its QoS profile");
                let five_qi = match &q.qos_characteristics {
                    QosCharacteristics::NonDynamic5qi(d) => d.five_qi,
                    other => panic!("non-dynamic 5QI expected, got {other:?}"),
                };
                (
                    i.qos_flow_identifier,
                    five_qi,
                    q.allocation_and_retention_priority.priority_level_arp,
                )
            })
            .collect();
        (ambr, flows)
    }

    /// #1385 criteria 1-3, through the real SBI router, the real N4 listener and an AMF
    /// stand-in. A notify that changes the Session-AMBR sends the QER update AND one
    /// N1N2MessageTransfer:
    /// - N1 = PDU SESSION MODIFICATION COMMAND, PTI 0, the new AMBR;
    /// - N2 = PDUSessionResourceModifyRequestTransfer with the new AMBR and the default
    ///   flow's QoS profile.
    ///
    /// T3591 is armed, and MODIFICATION COMPLETE stops it. A notify changing neither
    /// the AMBR nor the 5QI sends nothing. A 5QI-only change carries the new 5QI on
    /// both legs.
    ///
    /// REVERT-VERIFIED: without the `signal_policy_change` call no transfer arrives;
    /// without its change check the PCC-only notify sends one; without the 0x79 IE the
    /// 5QI-only N1 carries no QoS flow description.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_pcf_ambr_change_reaches_the_ue_and_the_ran_1385() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (upf, qers, upf_task) = modification_recording_upf_1387().await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        let (amf, amf_port, posts) = n1n2_recording_amf_1385(false).await;
        let supi = "imsi-001010000001385";
        let psi = 23;
        let sm_context_ref = seed_notified_session_1387(supi, psi, 0x1385);
        set_amf_1385(&sm_context_ref, amf_port);

        // ---- the AMBR changes: QER + N1 + N2 ----
        let status = smf_sbi_request_handler(policy_notify_1387(
            &sm_context_ref,
            serde_json::json!({ "sessRules": { "SessRule-pol-1387": {
                "authSessAmbr": { "uplink": "40 Mbps", "downlink": "80 Mbps" },
            }}}),
        ))
        .await
        .status;
        assert_eq!(status, 204);
        assert_eq!(
            qers.lock()
                .unwrap()
                .iter()
                .rev()
                .find_map(|b| updated_qer_mbr_1387(b)),
            Some((40_000_000, 80_000_000)),
            "the QER update is still sent"
        );
        let got = await_n1n2_1385(&posts, 1).await;
        assert_eq!(got.len(), 1, "one N1N2MessageTransfer, got {got:?}");
        let (path, body, n1_cmd, n2) = &got[0];
        assert_eq!(
            path,
            &format!("/namf-comm/v1/ue-contexts/{supi}/n1-n2-messages")
        );
        assert_eq!(
            body["n2InfoContainer"]["smInfo"]["n2InfoContent"]["ngapIeType"],
            "PDU_RES_MOD_REQ"
        );
        assert_eq!(body["pduSessionId"], psi);
        assert!(
            body.get("skipInd").is_none(),
            "no skipInd: a CM-IDLE UE is to be paged (TS 29.518 §6.1.6.2.18)"
        );
        assert_eq!(
            body["5qi"], 6,
            "the flow's 5QI and ARP, for the AMF's paging policy"
        );
        // N1, TS 24.501 §8.3.9: EPD, PSI, PTI 0 (§6.3.2.2), MODIFICATION COMMAND, then the
        // Session-AMBR IE (0x2A, §9.11.4.14): DL 80 Mbps, UL 40 Mbps, unit 0x06 = 1 Mbps.
        assert_eq!(
            n1_cmd,
            &vec![0x2E, psi, 0, 0xCB, 0x2A, 6, 0x06, 0, 80, 0x06, 0, 40],
            "N1 is a network-requested MODIFICATION COMMAND with PTI 0 and the new AMBR"
        );
        assert_eq!(
            decode_modify_transfer_1385(n2),
            ((80_000_000, 40_000_000), vec![(1, 6, 8)]),
            "N2 carries the new Session-AMBR and the default flow's QoS profile"
        );
        assert_eq!(
            gsm_procedure_timers()
                .lock()
                .unwrap()
                .get(&sm_context_ref)
                .map(|t| (t.timer_id, t.command.clone())),
            Some((timer::SmfTimerId::T3591, n1_cmd.clone())),
            "T3591 guards the command"
        );
        let resp = handle_n1_sm_message(
            &sm_context_ref,
            &n1(
                psi,
                0,
                gsm_build::message_type::PDU_SESSION_MODIFICATION_COMPLETE,
                &[],
            ),
        )
        .await;
        assert_eq!(resp.status, 204);
        assert!(
            !gsm_procedure_timers()
                .lock()
                .unwrap()
                .contains_key(&sm_context_ref),
            "MODIFICATION COMPLETE stops T3591"
        );

        // ---- neither the AMBR nor the 5QI changes: no N1/N2 ----
        let status = smf_sbi_request_handler(policy_notify_1387(
            &sm_context_ref,
            serde_json::json!({ "pccRules": { "PccRule-af-1": { "precedence": 10 } } }),
        ))
        .await
        .status;
        assert_eq!(status, 204);
        assert_eq!(
            settled_n1n2_1385(&posts).await.len(),
            1,
            "a notify that changes neither the AMBR nor the 5QI sends no N1/N2"
        );
        assert!(!gsm_procedure_timers()
            .lock()
            .unwrap()
            .contains_key(&sm_context_ref));

        // ---- the 5QI alone changes: both legs carry it ----
        let status = smf_sbi_request_handler(policy_notify_1387(
            &sm_context_ref,
            serde_json::json!({ "sessRules": { "SessRule-pol-1387": {
                "authDefQos": { "5qi": 8 },
            }}}),
        ))
        .await
        .status;
        assert_eq!(status, 204);
        let got = await_n1n2_1385(&posts, 2).await;
        assert_eq!(got.len(), 2, "{got:?}");
        let (_, _, n1_cmd, n2) = &got[1];
        // ... AMBR as before, then the Authorized QoS flow descriptions (0x79, TLV-E,
        // §9.11.4.12): QFI 1, operation "create new" (1 << 5, review B1), E=1 with one parameter, the
        // 5QI (0x01) of length 1 = 8.
        assert_eq!(
            &n1_cmd[..],
            &[
                0x2E, psi, 0, 0xCB, 0x2A, 6, 0x06, 0, 80, 0x06, 0, 40, 0x79, 0, 6, 1, 0x20, 0x41,
                0x01, 1, 8
            ][..]
        );
        assert_eq!(
            decode_modify_transfer_1385(n2),
            ((80_000_000, 40_000_000), vec![(1, 8, 8)])
        );

        amf.stop().await.ok();
        listener.abort();
        upf_task.abort();
    }

    /// #1409 (TS 23.502 §4.3.3.2 step 3b; TS 24.501 §6.3.2.5): T3591 expiry resends
    /// the PDU SESSION MODIFICATION COMMAND in an N1N2MessageTransfer that carries the
    /// SAME PDUSessionResourceModifyRequestTransfer as the first one, so a lost first
    /// transfer still reaches the NG-RAN. And an ARP-only policy change is signalled:
    /// N2 carries the new ARP in the flow's QoS profile; N1 restates the Session-AMBR
    /// with no QoS flow description (ARP is not UE-facing, TS 24.501 §9.11.4.12).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn t3591_resends_the_n2_and_an_arp_change_is_signalled_1409() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (upf, _qers, upf_task) = modification_recording_upf_1387().await;
        let (_client, listener) = client_behind_the_real_listener(upf).await;
        let (amf, amf_port, posts) = n1n2_recording_amf_1385(false).await;
        let supi = "imsi-001010000001409";
        let psi = 24;
        let sm_context_ref = seed_notified_session_1387(supi, psi, 0x1409);
        set_amf_1385(&sm_context_ref, amf_port);

        // ---- the AMBR changes; then T3591 expires: N1 and the same N2 again ----
        let status = smf_sbi_request_handler(policy_notify_1387(
            &sm_context_ref,
            serde_json::json!({ "sessRules": { "SessRule-pol-1387": {
                "authSessAmbr": { "uplink": "40 Mbps", "downlink": "80 Mbps" },
            }}}),
        ))
        .await
        .status;
        assert_eq!(status, 204);
        let got = await_n1n2_1385(&posts, 1).await;
        assert_eq!(got.len(), 1, "{got:?}");
        let (_, first_body, first_n1, first_n2) = got[0].clone();
        assert!(!first_n2.is_empty());
        if let Ok(mut timers) = gsm_procedure_timers().lock() {
            let t = timers.get_mut(&sm_context_ref).expect("T3591 armed");
            assert_eq!(t.timer_id, timer::SmfTimerId::T3591);
            t.deadline = std::time::Instant::now() - std::time::Duration::from_millis(1);
        }
        run_gsm_timer_tick().await;
        let got = await_n1n2_1385(&posts, 2).await;
        assert_eq!(got.len(), 2, "the T3591 retransmission, got {got:?}");
        let (path, body, n1_again, n2_again) = &got[1];
        assert_eq!(
            path,
            &format!("/namf-comm/v1/ue-contexts/{supi}/n1-n2-messages")
        );
        assert_eq!(n1_again, &first_n1, "the same command, verbatim");
        assert_eq!(
            n2_again, &first_n2,
            "the retransmission carries the same N2 Modify Request Transfer"
        );
        assert_eq!(
            body["n2InfoContainer"]["smInfo"]["n2InfoContent"]["ngapIeType"],
            "PDU_RES_MOD_REQ"
        );
        assert_eq!(body["5qi"], first_body["5qi"], "paging info kept");
        assert_eq!(
            decode_modify_transfer_1385(n2_again),
            ((80_000_000, 40_000_000), vec![(1, 6, 8)])
        );
        let resp = handle_n1_sm_message(
            &sm_context_ref,
            &n1(
                psi,
                0,
                gsm_build::message_type::PDU_SESSION_MODIFICATION_COMPLETE,
                &[],
            ),
        )
        .await;
        assert_eq!(resp.status, 204);

        // ---- the ARP alone changes: N2 carries it, N1 restates the AMBR ----
        let status = smf_sbi_request_handler(policy_notify_1387(
            &sm_context_ref,
            serde_json::json!({ "sessRules": { "SessRule-pol-1387": {
                "authDefQos": { "arp": { "priorityLevel": 3 } },
            }}}),
        ))
        .await
        .status;
        assert_eq!(status, 204);
        let got = await_n1n2_1385(&posts, 3).await;
        assert_eq!(got.len(), 3, "an ARP-only change is signalled, got {got:?}");
        let (_, _, n1_arp, n2_arp) = &got[2];
        assert_eq!(
            decode_modify_transfer_1385(n2_arp),
            ((80_000_000, 40_000_000), vec![(1, 6, 3)]),
            "N2 carries the new ARP priority level"
        );
        assert_eq!(
            n1_arp,
            &vec![0x2E, psi, 0, 0xCB, 0x2A, 6, 0x06, 0, 80, 0x06, 0, 40],
            "N1: the AMBR restated, no QoS flow description"
        );
        assert_eq!(
            gsm_procedure_timers()
                .lock()
                .unwrap()
                .get(&sm_context_ref)
                .map(|t| t.timer_id),
            Some(timer::SmfTimerId::T3591)
        );
        assert!(cancel_gsm_timer_for_test(&sm_context_ref));

        amf.stop().await.ok();
        listener.abort();
        upf_task.abort();
    }

    /// Expire `sm_context_ref`'s armed 5GSM timer now and run one tick (#1430).
    async fn expire_gsm_timer_now_1430(sm_context_ref: &str, timer_id: timer::SmfTimerId) {
        if let Ok(mut timers) = gsm_procedure_timers().lock() {
            let t = timers.get_mut(sm_context_ref).expect("a 5GSM timer armed");
            assert_eq!(t.timer_id, timer_id);
            t.deadline = std::time::Instant::now() - std::time::Duration::from_millis(1);
        }
        run_gsm_timer_tick().await;
    }

    /// An SM context with a binding addressed to the AMF stand-in on `amf_port`, and
    /// no N4 session or SM policy, so a release has no UPF or PCF leg (#1430).
    fn seed_release_session_1430(supi: &str, psi: u8, amf_port: u16) -> String {
        let reference = {
            let ctx = smf_self();
            let context = ctx.read().expect("context");
            register_sm_context(&context, supi, psi)
                .expect("register")
                .0
        };
        seed_binding(&reference, psi);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut(&reference) {
                    b.supi = supi.to_string();
                }
            }
        }
        set_amf_1385(&reference, amf_port);
        // #1563: a session whose UP connection is active, so its release carries N2.
        mark_up_cnx_state(&reference, context::UpCnxState::Activated);
        reference
    }

    /// #1430, TS 23.502 §4.3.4.2 steps 3a/3b, TS 24.501 §6.3.3.3: a T3592
    /// retransmission of a PDU SESSION RELEASE COMMAND that went out with the N2
    /// Resource Release request carries the same N1 and the same
    /// PDUSessionResourceReleaseCommandTransfer (`PDU_RES_REL_CMD`), so a lost first
    /// transfer still releases the NG-RAN resources:
    /// - network-initiated (the UPF-restart reactivation release, step 3b);
    /// - UE-requested (the UpdateSMContext answer carried the N2, step 3a).
    ///
    /// A release that went out N1-only (the NG-RAN already released, step 3a: no N2)
    /// is retransmitted N1-only.
    ///
    /// REVERT-VERIFIED: with the tick's release arm removed (or the release sites
    /// arming T3592 with no N2), both N2 retransmissions go out N1-only.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn t3592_resends_the_n2_release_command_1430() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (amf, amf_port, posts) = n1n2_recording_amf_1385(false).await;
        let amf_uri = format!("http://127.0.0.1:{amf_port}");
        let expected_n2 = n2_transfer::release_command_transfer().expect("release transfer");
        assert!(!expected_n2.is_empty());

        // ---- network-initiated: N1 + N2 in the first transfer and the retransmission ----
        let supi = "imsi-001010000001430";
        let net = seed_release_session_1430(supi, 14, amf_port);
        release_for_reactivation(&net, &amf_uri, supi, 14).await;
        let got = await_n1n2_1385(&posts, 1).await;
        assert_eq!(got.len(), 1, "{got:?}");
        let (_, first_body, first_n1, first_n2) = got[0].clone();
        assert_eq!(first_n2, expected_n2);
        assert_eq!(
            first_body["n2InfoContainer"]["smInfo"]["n2InfoContent"]["ngapIeType"],
            "PDU_RES_REL_CMD"
        );
        expire_gsm_timer_now_1430(&net, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 2).await;
        assert_eq!(got.len(), 2, "the T3592 retransmission, got {got:?}");
        let (path, body, n1_again, n2_again) = &got[1];
        assert_eq!(
            path,
            &format!("/namf-comm/v1/ue-contexts/{supi}/n1-n2-messages")
        );
        assert_eq!(n1_again, &first_n1, "the same command, verbatim");
        assert_eq!(
            n2_again, &expected_n2,
            "the retransmission carries the same PDUSessionResourceReleaseCommandTransfer"
        );
        assert_eq!(
            body["n2InfoContainer"]["smInfo"]["n2InfoContent"]["ngapIeType"],
            "PDU_RES_REL_CMD"
        );
        assert_eq!(body["n2InfoContainer"]["smInfo"]["pduSessionId"], 14);
        assert!(cancel_gsm_timer_for_test(&net));

        // ---- UE-requested: the answer carried N1 + N2; so does the retransmission ----
        let supi_ue = "imsi-001010000001431";
        let ue = seed_release_session_1430(supi_ue, 15, amf_port);
        let resp = handle_n1_sm_message(
            &ue,
            &n1(
                15,
                3,
                gsm_build::message_type::PDU_SESSION_RELEASE_REQUEST,
                &[],
            ),
        )
        .await;
        assert_eq!(resp.status, 200);
        let part = |id: &str| {
            resp.http
                .parts
                .iter()
                .find(|p| p.content_id.as_deref() == Some(id))
                .map(|p| p.data.to_vec())
        };
        let answered_n1 = part("n1SmMsg").expect("the RELEASE COMMAND");
        assert_eq!(part("n2SmInfo"), Some(expected_n2.clone()));
        expire_gsm_timer_now_1430(&ue, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 3).await;
        assert_eq!(got.len(), 3, "the T3592 retransmission, got {got:?}");
        let (path, body, n1_again, n2_again) = &got[2];
        assert_eq!(
            path,
            &format!("/namf-comm/v1/ue-contexts/{supi_ue}/n1-n2-messages")
        );
        assert_eq!(
            n1_again, &answered_n1,
            "the command the UE was answered with"
        );
        assert_eq!(n2_again, &expected_n2, "and the N2 it went out with");
        assert_eq!(
            body["n2InfoContainer"]["smInfo"]["n2InfoContent"]["ngapIeType"],
            "PDU_RES_REL_CMD"
        );
        assert!(cancel_gsm_timer_for_test(&ue));

        // ---- the NG-RAN already released: N1-only, and so is the retransmission ----
        let supi_an = "imsi-001010000001432";
        let an = seed_release_session_1430(supi_an, 16, amf_port);
        let resp = ran_released_session(&an, None).await;
        assert_eq!(resp.status, 200);
        assert!(
            !resp
                .http
                .parts
                .iter()
                .any(|p| p.content_id.as_deref() == Some("n2SmInfo")),
            "no N2 in the answer"
        );
        expire_gsm_timer_now_1430(&an, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 4).await;
        assert_eq!(got.len(), 4, "the T3592 retransmission, got {got:?}");
        let (path, body, n1_again, n2_again) = &got[3];
        assert_eq!(
            path,
            &format!("/namf-comm/v1/ue-contexts/{supi_an}/n1-n2-messages")
        );
        assert_eq!(
            n1_again[3],
            gsm_build::message_type::PDU_SESSION_RELEASE_COMMAND
        );
        assert!(n2_again.is_empty(), "N1-only: no N2 part");
        assert!(body["n2InfoContainer"].is_null(), "{body}");
        assert!(cancel_gsm_timer_for_test(&an));

        amf.stop().await.ok();
    }

    /// #1563, TS 23.502 §4.3.4.2 (`23502-k20.txt:14016-14020`): "If the User Plane
    /// connection of the PDU Session is not activated, the message sent by the SMF to
    /// the AMF shall not include N2 SM Resource Release request". A session whose UP
    /// connection is DEACTIVATED (the UE went CM-IDLE) is released N1-only on both
    /// paths, and so is its T3592 retransmission:
    /// - network-initiated (the UPF-restart reactivation release, step 3b): no
    ///   `n2InfoContainer` in the N1N2MessageTransfer;
    /// - UE-requested (step 3a): no `n2SmInfo` part and no `n2SmInfoType` in the
    ///   UpdateSMContext answer.
    ///
    /// REVERT-VERIFIED: with the N2 built unconditionally again, every transfer and
    /// the answer carry the PDU_RES_REL_CMD.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_release_of_a_deactivated_up_connection_carries_no_n2_1563() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (amf, amf_port, posts) = n1n2_recording_amf_1385(false).await;
        let amf_uri = format!("http://127.0.0.1:{amf_port}");

        // ---- network-initiated: N1-only, and so is the retransmission ----
        let supi = "imsi-001010000001563";
        let net = seed_release_session_1430(supi, 14, amf_port);
        mark_up_cnx_state(&net, context::UpCnxState::Deactivated);
        release_for_reactivation(&net, &amf_uri, supi, 14).await;
        let got = await_n1n2_1385(&posts, 1).await;
        assert_eq!(got.len(), 1, "{got:?}");
        let (_, body, first_n1, n2) = &got[0];
        assert_eq!(
            first_n1[3],
            gsm_build::message_type::PDU_SESSION_RELEASE_COMMAND
        );
        assert!(n2.is_empty(), "no N2 part");
        assert!(body["n2InfoContainer"].is_null(), "{body}");
        expire_gsm_timer_now_1430(&net, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 2).await;
        assert_eq!(got.len(), 2, "the T3592 retransmission, got {got:?}");
        let (_, body, n1_again, n2_again) = &got[1];
        assert_eq!(n1_again, first_n1, "the same command, verbatim");
        assert!(n2_again.is_empty(), "the retransmission is N1-only too");
        assert!(body["n2InfoContainer"].is_null(), "{body}");
        assert!(cancel_gsm_timer_for_test(&net));

        // ---- UE-requested: the answer is N1-only, and so is the retransmission ----
        let supi_ue = "imsi-001010000001564";
        let ue = seed_release_session_1430(supi_ue, 15, amf_port);
        mark_up_cnx_state(&ue, context::UpCnxState::Deactivated);
        let resp = handle_n1_sm_message(
            &ue,
            &n1(
                15,
                3,
                gsm_build::message_type::PDU_SESSION_RELEASE_REQUEST,
                &[],
            ),
        )
        .await;
        assert_eq!(resp.status, 200);
        let part = |id: &str| {
            resp.http
                .parts
                .iter()
                .find(|p| p.content_id.as_deref() == Some(id))
                .map(|p| p.data.to_vec())
        };
        let answered_n1 = part("n1SmMsg").expect("the RELEASE COMMAND");
        assert_eq!(
            answered_n1[3],
            gsm_build::message_type::PDU_SESSION_RELEASE_COMMAND
        );
        assert_eq!(part("n2SmInfo"), None, "no N2 in the answer");
        let answer: serde_json::Value =
            serde_json::from_str(resp.http.content.as_deref().unwrap_or("{}")).expect("JSON");
        assert!(answer["n2SmInfoType"].is_null(), "{answer}");
        expire_gsm_timer_now_1430(&ue, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 3).await;
        assert_eq!(got.len(), 3, "the T3592 retransmission, got {got:?}");
        let (_, body, n1_again, n2_again) = &got[2];
        assert_eq!(n1_again, &answered_n1);
        assert!(n2_again.is_empty(), "the retransmission is N1-only too");
        assert!(body["n2InfoContainer"].is_null(), "{body}");
        assert!(cancel_gsm_timer_for_test(&ue));

        amf.stop().await.ok();
    }

    /// #1563 (review of #1564): once the NG-RAN has acknowledged the N2 Resource
    /// Release (`PDU_RES_REL_RSP`), the UP connection is no longer active, so a later
    /// T3592 retransmission of the release command is N1-only (TS 23.502 §4.3.4.2),
    /// not a PDU_RES_REL_CMD that pages a CM-IDLE UE for resources the NG-RAN freed.
    /// Before the acknowledgement the retransmission keeps its N2 (#1430).
    ///
    /// REVERT-VERIFIED: without the drop in the `PDU_RES_REL_RSP` arm, the
    /// retransmission after the acknowledgement still carries the PDU_RES_REL_CMD.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn t3592_drops_the_n2_once_the_ran_released_1563() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _seeded = crate::context::SeededState::track();
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (amf, amf_port, posts) = n1n2_recording_amf_1385(false).await;
        let amf_uri = format!("http://127.0.0.1:{amf_port}");
        let expected_n2 = n2_transfer::release_command_transfer().expect("release transfer");

        let supi = "imsi-001010000001565";
        let net = seed_release_session_1430(supi, 14, amf_port);
        release_for_reactivation(&net, &amf_uri, supi, 14).await;
        let got = await_n1n2_1385(&posts, 1).await;
        assert_eq!(got.len(), 1, "{got:?}");
        assert_eq!(
            got[0].3, expected_n2,
            "the active session's release carries N2"
        );
        let first_n1 = got[0].2.clone();
        // A retransmission before the NG-RAN answered keeps the N2.
        expire_gsm_timer_now_1430(&net, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 2).await;
        assert_eq!(got.len(), 2, "{got:?}");
        assert_eq!(got[1].3, expected_n2, "not yet acknowledged: N2 again");

        let rel_rsp = {
            use base64::Engine as _;
            base64::engine::general_purpose::STANDARD.encode([0x00])
        };
        let req = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts/x/modify").with_body(
            serde_json::json!({
                "n2SmInfoType": "PDU_RES_REL_RSP",
                "n2SmInfo": rel_rsp,
            })
            .to_string(),
            "application/json",
        );
        let resp = handle_sm_context_update(&net, &req).await;
        assert_eq!(resp.status, 200, "{:?}", resp.http.content);

        expire_gsm_timer_now_1430(&net, timer::SmfTimerId::T3592).await;
        let got = await_n1n2_1385(&posts, 3).await;
        assert_eq!(got.len(), 3, "the T3592 retransmission, got {got:?}");
        let (_, body, n1_again, n2_again) = &got[2];
        assert_eq!(n1_again, &first_n1, "the same command, verbatim");
        assert!(n2_again.is_empty(), "N1-only after the NG-RAN released");
        assert!(body["n2InfoContainer"].is_null(), "{body}");
        assert!(cancel_gsm_timer_for_test(&net));

        amf.stop().await.ok();
    }

    /// The UP connection state `sm_context_ref`'s session records (#1606).
